package com.gielinorguide;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.Skill;

public final class BarracudaTrialsAdvisor
{
    private final LocationResolver locationResolver;

    public BarracudaTrialsAdvisor(LocationResolver locationResolver)
    {
        this.locationResolver = locationResolver;
    }

    public boolean supports(String destination)
    {
        String normalized = destination.toLowerCase(Locale.ENGLISH)
            .replaceAll("[^a-z0-9]+", " ").trim();
        return normalized.equals("barracuda trials") || normalized.equals("barracuda trial") ||
            normalized.equals("baracuda trials") || normalized.equals("baracuda trial");
    }

    public GuideResponse answer(Map<Skill, Integer> levels)
    {
        int sailing = levels.getOrDefault(Skill.SAILING, 0);
        String recommendation;
        if (sailing >= 72)
        {
            recommendation = "At " + sailing + " Sailing, your highest unlocked tier by level is The Gwenith Glide at Porth Gwenith; it also requires Regicide.";
        }
        else if (sailing >= 55)
        {
            recommendation = "At " + sailing + " Sailing, your highest unlocked trial is The Jubbly Jive at Backwater.";
        }
        else if (sailing >= 30)
        {
            recommendation = "At " + sailing + " Sailing, your unlocked trial is The Tempor Tantrum at The Storm Tempor.";
        }
        else
        {
            recommendation = "Your current Sailing level is " + sailing + "; the first trial unlocks at level 30.";
        }

        String answer = "Barracuda Trials is an umbrella name for three different destinations, so there is no single safe marker. " +
            recommendation + " The choices are: The Tempor Tantrum at The Storm Tempor (30), The Jubbly Jive at Backwater (55), " +
            "and The Gwenith Glide at Porth Gwenith (72 plus Regicide). Choose a named map button below or ask about that exact trial. " +
            "Shortest Path may only plan the land portion; these destinations are at sea.";

        List<VerifiedLocation> destinations = Arrays.asList(
            locationResolver.byId("storm-tempor"),
            locationResolver.byId("backwater"),
            locationResolver.byId("porth-gwenith"));
        List<WikiSource> sources = new ArrayList<>();
        sources.add(new WikiSource("Barracuda Trials - OSRS Wiki",
            "https://oldschool.runescape.wiki/w/Barracuda_Trials",
            "Verified trial levels, names, requirements, and locations."));
        return new GuideResponse(answer, sources, destinations);
    }
}

package com.gielinorguide;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class ConversationState
{
    private static final int MAX_MESSAGES = 8;
    private final List<GuideMessage> messages = new ArrayList<>();

    public synchronized void addUserMessage(String text)
    {
        add(new GuideMessage(GuideMessage.Role.USER, text));
    }

    public synchronized void addAssistantMessage(String text)
    {
        add(new GuideMessage(GuideMessage.Role.ASSISTANT, text));
    }

    private void add(GuideMessage message)
    {
        messages.add(message);
        while (messages.size() > MAX_MESSAGES)
        {
            messages.remove(0);
        }
    }

    public synchronized List<GuideMessage> snapshot()
    {
        return Collections.unmodifiableList(new ArrayList<>(messages));
    }

    public synchronized void clear()
    {
        messages.clear();
    }

    public synchronized boolean isEmpty()
    {
        return messages.isEmpty();
    }
}

package com.gielinorguide;

import net.runelite.api.coords.WorldPoint;

/** Reapplies an interior objective after the player crosses into its map space. */
final class FinalObjectiveRouteTracker
{
    private static final int DIFFERENT_MAP_DISTANCE = 512;
    private static final int SAME_AREA_DISTANCE = 128;
    private VerifiedLocation destination;
    private boolean approachedFromDifferentMap;

    synchronized void arm(VerifiedLocation candidate)
    {
        if (candidate != null && candidate.getGuidance().contains("final objective"))
        {
            destination = candidate;
            approachedFromDifferentMap = false;
        }
        else
        {
            clear();
        }
    }

    synchronized VerifiedLocation update(WorldPoint player)
    {
        if (destination == null || player == null)
        {
            return null;
        }
        int distance = player.distanceTo(destination.getWorldPoint());
        if (distance > DIFFERENT_MAP_DISTANCE)
        {
            approachedFromDifferentMap = true;
            return null;
        }
        if (!approachedFromDifferentMap || distance > SAME_AREA_DISTANCE)
        {
            return null;
        }
        VerifiedLocation result = destination;
        clear();
        return result;
    }

    synchronized void clear()
    {
        destination = null;
        approachedFromDifferentMap = false;
    }
}

package com.gielinorguide;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(GielinorGuideConfig.GROUP)
public interface GielinorGuideConfig extends Config
{
    String GROUP = "gielinor-guide";
    String PLAYER_CONTEXT_SECTION = "playerContext";
    String THIRD_PARTY_WARNING = "Sends OSRS Wiki search queries to the OSRS Wiki and sends your questions, conversation history, retrieved Wiki excerpts, and any player context you separately enable to OpenAI. These third-party services are not controlled or verified by RuneLite developers.";

    @ConfigSection(
        name = "Optional player context",
        description = "Choose which read-only game-state summaries may be sent to OpenAI.",
        position = 10
    )
    String playerContextSection = PLAYER_CONTEXT_SECTION;

    @ConfigItem(
        keyName = "enableExternalRequests",
        name = "Enable external requests",
        description = "Required opt-in. Sends search queries to the OSRS Wiki, then sends the question, Wiki excerpts, conversation history, and any separately enabled player context to OpenAI.",
        warning = THIRD_PARTY_WARNING,
        position = 0
    )
    default boolean enableExternalRequests()
    {
        return false;
    }

    @ConfigItem(
        keyName = "openAiApiKey",
        name = "OpenAI API key",
        description = "Your OpenAI Platform API key. The field is masked; the plugin never displays or logs it.",
        secret = true,
        position = 1
    )
    default String openAiApiKey()
    {
        return "";
    }

    @ConfigItem(
        keyName = "openAiModel",
        name = "OpenAI model",
        description = "Responses API model ID. gpt-5.6-terra with instant-style reasoning balances answer quality, latency, and cost.",
        position = 2
    )
    default String openAiModel()
    {
        return "gpt-5.6-terra";
    }

    @ConfigItem(
        keyName = "shareAllContext",
        name = "Share all player context",
        description = "Master opt-in. Includes location, skills, completed quests and diary tiers, inventory, equipment, the latest bank snapshot, and your active Slayer assignment. Public and private chat are never included.",
        warning = THIRD_PARTY_WARNING,
        position = 10,
        section = PLAYER_CONTEXT_SECTION
    )
    default boolean shareAllContext()
    {
        return false;
    }

    @ConfigItem(
        keyName = "shareLocation",
        name = "Share current location",
        description = "Includes your current world tile coordinates with OpenAI requests. Does not share your account name.",
        warning = THIRD_PARTY_WARNING,
        position = 11,
        section = PLAYER_CONTEXT_SECTION
    )
    default boolean shareLocation()
    {
        return false;
    }

    @ConfigItem(
        keyName = "shareSkills",
        name = "Share skill levels",
        description = "Includes the real level of every skill with OpenAI requests.",
        warning = THIRD_PARTY_WARNING,
        position = 12,
        section = PLAYER_CONTEXT_SECTION
    )
    default boolean shareSkills()
    {
        return false;
    }

    @ConfigItem(
        keyName = "shareCompletedQuests",
        name = "Share quests and diaries",
        description = "Includes the names of completed quests and achievement diary tiers with OpenAI requests.",
        warning = THIRD_PARTY_WARNING,
        position = 13,
        section = PLAYER_CONTEXT_SECTION
    )
    default boolean shareCompletedQuests()
    {
        return false;
    }

    @ConfigItem(
        keyName = "shareInventory",
        name = "Share inventory",
        description = "Includes inventory item names and quantities with OpenAI requests.",
        warning = THIRD_PARTY_WARNING,
        position = 14,
        section = PLAYER_CONTEXT_SECTION
    )
    default boolean shareInventory()
    {
        return false;
    }

    @ConfigItem(
        keyName = "shareEquipment",
        name = "Share equipment",
        description = "Includes equipped item names and quantities with OpenAI requests.",
        warning = THIRD_PARTY_WARNING,
        position = 15,
        section = PLAYER_CONTEXT_SECTION
    )
    default boolean shareEquipment()
    {
        return false;
    }

    @ConfigItem(
        keyName = "shareBank",
        name = "Share bank summary",
        description = "Includes bank item names and quantities from the latest bank snapshot in this plugin session. Open the bank once after enabling it.",
        warning = THIRD_PARTY_WARNING,
        position = 16,
        section = PLAYER_CONTEXT_SECTION
    )
    default boolean shareBank()
    {
        return false;
    }

    @ConfigItem(
        keyName = "shareSlayerTask",
        name = "Share Slayer assignment",
        description = "Includes the active Slayer task name, remaining count, initial count, and assigned area with OpenAI requests. Does not include chat messages.",
        warning = THIRD_PARTY_WARNING,
        position = 17,
        section = PLAYER_CONTEXT_SECTION
    )
    default boolean shareSlayerTask()
    {
        return false;
    }
}

package com.gielinorguide;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import okhttp3.OkHttpClient;

@PluginDescriptor(
    name = "Gielinor Guide",
    description = "A conversational, Wiki-grounded OSRS guide in the RuneLite side panel",
    tags = {"guide", "wiki", "assistant", "help", "map"}
)
public final class GielinorGuidePlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private WorldMapPointManager worldMapPointManager;

    @Inject
    private OkHttpClient httpClient;

    @Inject
    private Gson gson;

    @Inject
    private EventBus eventBus;

    @Inject
    private PluginManager pluginManager;

    @Inject
    private GielinorGuideConfig config;

    @Inject
    private ConfigManager configManager;

    private final ConversationState conversation = new ConversationState();
    private final LocationResolver locationResolver = new LocationResolver();
    private final TravelResolver travelResolver = new TravelResolver();
    private final LocalMapIntentResolver localMapIntentResolver =
        new LocalMapIntentResolver(locationResolver);
    private final TravelIntentResolver travelIntentResolver = new TravelIntentResolver();
    private final BarracudaTrialsAdvisor barracudaTrialsAdvisor =
        new BarracudaTrialsAdvisor(locationResolver);
    private final SlayerTaskIntentResolver slayerTaskIntentResolver =
        new SlayerTaskIntentResolver();
    private final FinalObjectiveRouteTracker finalObjectiveRouteTracker =
        new FinalObjectiveRouteTracker();
    private final Map<String, VerifiedLocation> sessionDestinations = new LinkedHashMap<>();
    private GuideService guideService;
    private WikiDestinationClient wikiDestinationClient;
    private PlayerContextProvider playerContextProvider;
    private MapMarkerController mapMarkerController;
    private GuidePanel panel;
    private NavigationButton navigationButton;
    private volatile boolean running;
    private volatile VerifiedLocation lastTravelDestination;
    private volatile String lastAchievementDiaryQuery;
    private volatile String lastQuestPreparationQuery;
    private int automaticRouteGeneration;
    private volatile boolean awaitingRouteTransport;

    @Provides
    GielinorGuideConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(GielinorGuideConfig.class);
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (playerContextProvider != null)
        {
            if (event.getContainerId() == InventoryID.BANK &&
                (config.shareAllContext() || config.shareBank()) && panel != null)
            {
                playerContextProvider.updateBankSnapshot(event.getItemContainer());
                SwingUtilities.invokeLater(() ->
                {
                    panel.setBankContextStatus(true, playerContextProvider.hasBankSnapshot());
                    panel.setStatus("Bank snapshot ready for guide and travel advice.");
                });
            }
        }
    }

    @Subscribe
    public void onPluginMessage(PluginMessage event)
    {
        if (!awaitingRouteTransport || !"shortestpath".equals(event.getNamespace()) ||
            !"transports".equals(event.getName()))
        {
            return;
        }
        Object values = event.getData().get("displayInfo");
        if (!(values instanceof List<?>))
        {
            return;
        }
        for (Object value : (List<?>) values)
        {
            String step = value == null ? "" : value.toString()
                .replaceAll("<[^>]+>", "").trim();
            if (!step.isEmpty())
            {
                awaitingRouteTransport = false;
                SwingUtilities.invokeLater(() ->
                {
                    if (running && panel != null)
                    {
                        panel.setStatus("Shortest Path first route transport: " + step);
                    }
                });
                return;
            }
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        net.runelite.api.coords.WorldPoint location = client.getLocalPlayer() == null
            ? null : client.getLocalPlayer().getWorldLocation();
        VerifiedLocation interiorObjective = finalObjectiveRouteTracker.update(location);
        if (interiorObjective != null)
        {
            SwingUtilities.invokeLater(() ->
            {
                if (running && panel != null)
                {
                    scheduleAutomaticRoute(interiorObjective, true);
                }
            });
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (playerContextProvider != null && GielinorGuideConfig.GROUP.equals(event.getGroup()) &&
            ("shareAllContext".equals(event.getKey()) || "shareBank".equals(event.getKey())) &&
            !config.shareAllContext() && !config.shareBank())
        {
            playerContextProvider.clearBankSnapshot();
        }
        if (GielinorGuideConfig.GROUP.equals(event.getGroup()))
        {
            refreshIntegrationStatus();
        }
    }

    @Subscribe
    public void onPluginChanged(PluginChanged event)
    {
        if ("Shortest Path".equalsIgnoreCase(event.getPlugin().getName()))
        {
            refreshIntegrationStatus();
        }
    }

    @Override
    protected void startUp()
    {
        running = true;
        if ("gpt-5-mini".equals(config.openAiModel()))
        {
            // Migrate only the plugin's former default model. The API key and all
            // other settings are left untouched and are never displayed or logged.
            configManager.setConfiguration(GielinorGuideConfig.GROUP,
                "openAiModel", "gpt-5.6-terra");
        }
        WikiClient wikiClient = new WikiClient(httpClient, gson);
        OpenAiClient openAiClient = new OpenAiClient(httpClient, gson);
        guideService = new GuideService(
            wikiClient, openAiClient, conversation, locationResolver, travelResolver);
        wikiDestinationClient = new WikiDestinationClient(httpClient, gson);
        playerContextProvider = new PlayerContextProvider(client, clientThread, config);
        mapMarkerController = new MapMarkerController(
            client, clientThread, worldMapPointManager, eventBus);

        SwingUtilities.invokeLater(() ->
        {
            panel = new GuidePanel(this::submitQuestion, this::clearConversation, this::routeFromPanel);
            panel.setIntegrationStatus(integrationStatus());
            panel.setBankContextStatus(playerContextProvider.isBankSharingEnabled(),
                playerContextProvider.hasBankSnapshot());
            navigationButton = NavigationButton.builder()
                .tooltip("Gielinor Guide")
                .icon(GuideIcons.navigationIcon())
                .priority(6)
                .panel(panel)
                .build();
            clientToolbar.addNavigation(navigationButton);
        });
    }

    @Override
    protected void shutDown()
    {
        running = false;
        if (guideService != null)
        {
            guideService.clearContext();
        }
        if (wikiDestinationClient != null)
        {
            wikiDestinationClient.cancel();
        }
        if (mapMarkerController != null)
        {
            mapMarkerController.clear();
        }
        conversation.clear();
        finalObjectiveRouteTracker.clear();
        lastTravelDestination = null;
        lastAchievementDiaryQuery = null;
        lastQuestPreparationQuery = null;
        sessionDestinations.clear();
        SwingUtilities.invokeLater(() ->
        {
            if (navigationButton != null)
            {
                clientToolbar.removeNavigation(navigationButton);
            }
            panel = null;
            navigationButton = null;
        });
    }

    private void submitQuestion(String question)
    {
        panel.addUserMessage(question);
        Optional<VerifiedLocation> mapDestination = localMapIntentResolver.resolve(question);
        if (mapDestination.isPresent())
        {
            VerifiedLocation destination = mapDestination.get();
            conversation.addUserMessage(question);
            mapMarkerController.show(destination);
            GuideResponse response = new GuideResponse(
                "Marker added for " + destination.getName() + ". Open RuneLite's world map to view it.",
                Collections.singletonList(new WikiSource(destination.getName(),
                    destination.getSourceUrl(), destination.getGuidance())),
                Collections.emptyList());
            handleSuccess(response);
            return;
        }
        List<GuideMessage> questHistory = conversation.snapshot();
        if (slayerTaskIntentResolver.supports(question, questHistory))
        {
            conversation.addUserMessage(question);
            panel.setLoading(true);
            panel.setStatus("Reading your active Slayer assignment locally...");
            clientThread.invokeLater(() ->
            {
                SlayerTaskSnapshot task = SlayerTaskSnapshot.from(client);
                SwingUtilities.invokeLater(() -> handleSlayerQuestion(question, task));
            });
            return;
        }
        Optional<String> generalTravelDestination = travelIntentResolver.extractDestination(question);
        if (!generalTravelDestination.isPresent() && lastTravelDestination != null &&
            travelIntentResolver.isTravelFollowUp(question))
        {
            conversation.addUserMessage(question);
            askVerifiedTravelQuestion(question, lastTravelDestination);
            return;
        }
        if (generalTravelDestination.isPresent())
        {
            conversation.addUserMessage(question);
            String destinationQuery = generalTravelDestination.get();
            if (barracudaTrialsAdvisor.supports(destinationQuery))
            {
                panel.setLoading(true);
                panel.setStatus("Checking your Sailing level locally...");
                playerContextProvider.captureSkillLevels(levels -> SwingUtilities.invokeLater(() ->
                    handleSuccess(barracudaTrialsAdvisor.answer(levels))));
                return;
            }
            List<VerifiedLocation> localMatches = locationResolver.resolveMentions(destinationQuery);
            VerifiedLocation sessionMatch = sessionDestinations.get(normalizeDestination(destinationQuery));
            if (localMatches.isEmpty() && sessionMatch != null)
            {
                askVerifiedTravelQuestion(question, sessionMatch);
                return;
            }
            if (!localMatches.isEmpty())
            {
                askVerifiedTravelQuestion(question, localMatches.get(0));
                return;
            }
            if (!config.enableExternalRequests())
            {
                panel.addError("I do not have that destination in the local verified catalog. Enable external requests so I can check the OSRS Wiki for a verified map point.");
                return;
            }
            panel.setLoading(true);
            panel.setStatus("Finding a verified OSRS Wiki map point...");
            wikiDestinationClient.resolve(destinationQuery,
                location -> SwingUtilities.invokeLater(() ->
                    askVerifiedTravelQuestion(question, location)),
                () -> SwingUtilities.invokeLater(() ->
                {
                    if (running && panel != null)
                    {
                        panel.setStatus("No trusted map point found; answering without a marker...");
                        askOpenAi(question, false);
                    }
                }));
            return;
        }
        String plannedQuery = WikiQueryPlanner.plan(question);
        boolean referentialFollowUp = WikiQueryPlanner.isReferentialFollowUp(question);
        if (!WikiQueryPlanner.isAchievementDiaryQuery(plannedQuery) &&
            lastAchievementDiaryQuery != null &&
            referentialFollowUp)
        {
            plannedQuery = lastAchievementDiaryQuery;
        }
        else if (!WikiPageCatalog.isQuestPage(plannedQuery) &&
            lastQuestPreparationQuery != null && referentialFollowUp)
        {
            plannedQuery = lastQuestPreparationQuery;
        }
        if (WikiQueryPlanner.isAchievementDiaryQuery(plannedQuery))
        {
            lastAchievementDiaryQuery = plannedQuery;
            lastQuestPreparationQuery = null;
        }
        else if (WikiPageCatalog.isQuestPage(plannedQuery))
        {
            lastQuestPreparationQuery = plannedQuery;
            lastAchievementDiaryQuery = null;
        }
        else if (!referentialFollowUp)
        {
            lastAchievementDiaryQuery = null;
            lastQuestPreparationQuery = null;
        }
        if (WikiQueryPlanner.isAchievementDiaryWalkthroughQuestion(question, plannedQuery))
        {
            String integrationContext = prepareQuestIntegrations(
                WikiQueryPlanner.achievementDiaryHelperName(plannedQuery));
            askOpenAi(question, true, Collections.emptyList(), null,
                integrationContext, plannedQuery, false);
            return;
        }
        if (WikiQueryPlanner.isQuestReadinessQuestion(question, plannedQuery))
        {
            askOpenAi(question, true, Collections.emptyList(), null,
                null, plannedQuery, false);
            return;
        }
        if (WikiQueryPlanner.isQuestWalkthroughQuestion(question, plannedQuery))
        {
            String questIntegrationContext = prepareQuestIntegrations(plannedQuery);
            askOpenAi(question, true, Collections.emptyList(), null,
                questIntegrationContext, plannedQuery, false);
            return;
        }
        if (WikiQueryPlanner.isGoalWalkthroughQuestion(question))
        {
            String questIntegrationContext = prepareQuestIntegrations("");
            askOpenAi(question, true, Collections.emptyList(), null,
                questIntegrationContext, plannedQuery, false);
            return;
        }
        askOpenAi(question, true);
    }

    private String prepareQuestIntegrations(String questTitle)
    {
        String shortestPath = pluginStatus("Shortest Path");
        String questHelper = pluginStatus("Quest Helper");
        panel.setStatus("Checking Quest Helper and Shortest Path...");
        String selection = questTitle == null || questTitle.trim().isEmpty()
            ? "If the verified evidence establishes a prerequisite quest, tell the player to " +
                "open the Quest Helper sidebar and select that quest by name."
            : "Tell the player to open the Quest Helper sidebar and select " + questTitle + ".";
        return "RuneLite Quest Helper integration (local, authoritative): Quest Helper is " +
            questHelper + "; Shortest Path is " + shortestPath + ". " +
            "Gielinor Guide does not enable either plugin or change their settings. " +
            "If an integration is installed but disabled, tell the player to enable it manually. " +
            "There is no supported cross-plugin command to select a specific Quest Helper. " +
            selection + " Do not claim it was selected. Once selected, Quest Helper owns the live current " +
            "step and map highlights. The player may enable Quest Helper's Shortest Path " +
            "setting if they want Quest Helper to use it. " +
            "Shortest Path cannot display a route until a specific current step has a verified destination.";
    }

    private String pluginStatus(String pluginName)
    {
        for (Plugin candidate : pluginManager.getPlugins())
        {
            if (pluginName.equalsIgnoreCase(candidate.getName()))
            {
                return pluginManager.isPluginActive(candidate) ? "active" : "installed but disabled";
            }
        }
        return "not installed";
    }

    private void askOpenAi(String question, boolean addUserToConversation)
    {
        askOpenAi(question, addUserToConversation, Collections.emptyList(), null);
    }

    private void askVerifiedTravelQuestion(String question, VerifiedLocation destination)
    {
        rememberDestination(destination);
        panel.setStatus("Checking your items and the Wiki's travel guidance...");
        String destinationQuery = destination.getName();
        if (destinationQuery.contains("(") && !destination.getAliases().isEmpty())
        {
            destinationQuery = destination.getAliases().get(0);
        }
        askOpenAi(question, false, Collections.singletonList(destination), destination,
            "", destinationQuery, false);
    }

    private void askOpenAi(String question, boolean addUserToConversation,
        List<VerifiedLocation> verifiedDestinations, VerifiedLocation autoRouteDestination)
    {
        askOpenAi(question, addUserToConversation, verifiedDestinations,
            autoRouteDestination, "", null, false);
    }

    private void askOpenAi(String question, boolean addUserToConversation,
        List<VerifiedLocation> verifiedDestinations, VerifiedLocation autoRouteDestination,
        String additionalPlayerContext, String wikiQueryOverride,
        boolean autoRouteFirstResolvedDestination)
    {
        if (!config.enableExternalRequests())
        {
            panel.setLoading(false);
            panel.addError("External requests are disabled. Enable them in Gielinor Guide settings after reviewing the data-sharing warning.");
            return;
        }

        String apiKey = config.openAiApiKey() == null ? "" : config.openAiApiKey().trim();
        if (apiKey.isEmpty())
        {
            panel.setLoading(false);
            panel.addError("Add an OpenAI API key in Gielinor Guide settings. API usage is billed separately from a ChatGPT subscription.");
            return;
        }
        if (!apiKey.toLowerCase(Locale.ENGLISH).startsWith("sk-"))
        {
            panel.setLoading(false);
            panel.addError("That does not look like an OpenAI API key. Check the key in Gielinor Guide settings and try again.");
            return;
        }
        String model = config.openAiModel() == null ? "" : config.openAiModel().trim();
        if (model.isEmpty())
        {
            panel.setLoading(false);
            panel.addError("Choose an OpenAI model in Gielinor Guide settings.");
            return;
        }

        if (addUserToConversation)
        {
            conversation.addUserMessage(question);
        }
        panel.setLoading(true);
        playerContextProvider.capture(playerContext ->
        {
            String combinedPlayerContext = additionalPlayerContext == null ||
                additionalPlayerContext.isEmpty() ? playerContext :
                playerContext + "\n" + additionalPlayerContext;
            SwingUtilities.invokeLater(() ->
            {
                if (panel != null)
                {
                    panel.setBankContextStatus(playerContextProvider.isBankSharingEnabled(),
                        playerContextProvider.hasBankSnapshot());
                }
            });
            guideService.ask(
                question, combinedPlayerContext, apiKey, model, verifiedDestinations,
                wikiQueryOverride,
                response -> SwingUtilities.invokeLater(() ->
                    handleOpenAiSuccess(question, response, autoRouteDestination,
                        autoRouteFirstResolvedDestination)),
                error -> SwingUtilities.invokeLater(() -> handleError(error)));
        });
    }

    private void handleSlayerQuestion(String question, SlayerTaskSnapshot task)
    {
        if (!running || panel == null)
        {
            return;
        }
        if (!task.isActive())
        {
            handleSuccess(new GuideResponse(
                "RuneLite's current game state does not contain an active Slayer assignment. " +
                    "Get a task from a Slayer master, then try again; checking an enchanted gem should not normally be necessary.",
                Collections.emptyList(),
                Collections.emptyList()));
            return;
        }
        if (!config.shareAllContext() && !config.shareSlayerTask())
        {
            panel.addError("I found your Slayer assignment locally, but sharing it is disabled. Enable Share Slayer assignment—or Share all player context—in Gielinor Guide settings, then try again.");
            panel.setLoading(false);
            return;
        }
        panel.setStatus("Checking the OSRS Wiki task guide and your enabled gear context...");
        askOpenAi(question, false, Collections.emptyList(), null,
            task.asPlayerContext(), task.getWikiPageTitle(), true);
    }

    private void handleOpenAiSuccess(String question, GuideResponse response,
        VerifiedLocation autoRouteDestination, boolean autoRouteFirstResolvedDestination)
    {
        boolean shouldUseShortestPath = travelIntentResolver.shouldUseShortestPath(question);
        if (autoRouteDestination == null && response.getDestinations().isEmpty() &&
            shouldUseShortestPath)
        {
            panel.setStatus("Verifying the recommended destination with the OSRS Wiki...");
            wikiDestinationClient.resolveFromSources(response.getAnswer(), response.getSources(),
                destination -> SwingUtilities.invokeLater(() ->
                {
                    if (!running || panel == null)
                    {
                        return;
                    }
                    List<WikiSource> sources = new ArrayList<>(response.getSources());
                    sources.add(new WikiSource(destination.getName(),
                        destination.getSourceUrl(), destination.getGuidance()));
                    GuideResponse verified = new GuideResponse(response.getAnswer(), sources,
                        Collections.singletonList(destination), response.getRouting());
                    finishOpenAiSuccess(verified, autoRouteDestination,
                        autoRouteFirstResolvedDestination || shouldUseShortestPath);
                }),
                () -> SwingUtilities.invokeLater(() ->
                {
                    if (running && panel != null)
                    {
                        finishOpenAiSuccess(response, autoRouteDestination,
                            autoRouteFirstResolvedDestination || shouldUseShortestPath);
                    }
                }));
            return;
        }
        finishOpenAiSuccess(response, autoRouteDestination,
            autoRouteFirstResolvedDestination || shouldUseShortestPath);
    }

    private void finishOpenAiSuccess(GuideResponse response,
        VerifiedLocation autoRouteDestination, boolean autoRouteFirstResolvedDestination)
    {
        VerifiedLocation routeDestination = autoRouteDestination;
        if (routeDestination == null && autoRouteFirstResolvedDestination &&
            !response.getDestinations().isEmpty())
        {
            routeDestination = response.getDestinations().get(0);
        }
        if (routeDestination == null)
        {
            handleSuccess(response);
            return;
        }

        GuideResponse routedResponse = new GuideResponse(
            response.getAnswer(), response.getSources(), response.getDestinations(),
            GuideResponse.Routing.ROUTE_NOW);
        handleSuccess(routedResponse);
        applyAutomaticRoute(routeDestination);
    }

    private void applyAutomaticRoute(VerifiedLocation destination)
    {
        finalObjectiveRouteTracker.arm(destination);
        IntegrationStatus integrations = integrationStatus();
        if (integrations.isShortestPathReady())
        {
            scheduleAutomaticRoute(destination);
        }
        else
        {
            mapMarkerController.show(destination);
            panel.setStatus(shortestPathFallbackMessage(integrations));
        }
    }

    private void scheduleAutomaticRoute(VerifiedLocation destination)
    {
        scheduleAutomaticRoute(destination, false);
    }

    private void scheduleAutomaticRoute(VerifiedLocation destination,
        boolean finalObjective)
    {
        int generation = ++automaticRouteGeneration;
        panel.setStatus("Applying Shortest Path route for " + destination.getName() + "...");
        javax.swing.Timer timer = new javax.swing.Timer(350, event ->
        {
            if (running && panel != null && generation == automaticRouteGeneration)
            {
                routeFromPanel(destination, finalObjective);
                panel.setStatus("Shortest Path route applied automatically for " +
                    destination.getName() + ".");
            }
        });
        timer.setRepeats(false);
        timer.start();
    }

    private void handleSuccess(GuideResponse response)
    {
        if (!running || panel == null)
        {
            return;
        }
        if (response.getDestinations().size() == 1)
        {
            rememberDestination(response.getDestinations().get(0));
        }
        else
        {
            for (VerifiedLocation destination : response.getDestinations())
            {
                sessionDestinations.put(normalizeDestination(destination.getName()),
                    destination);
            }
        }
        conversation.addAssistantMessage(response.getAnswer());
        panel.addGuideResponse(response);
        panel.setLoading(false);
    }

    private void rememberDestination(VerifiedLocation destination)
    {
        lastTravelDestination = destination;
        sessionDestinations.put(normalizeDestination(destination.getName()), destination);
        for (String alias : destination.getAliases())
        {
            sessionDestinations.put(normalizeDestination(alias), destination);
        }
    }

    private void handleError(GuideApiException error)
    {
        if (!running || panel == null)
        {
            return;
        }
        panel.addError(error.getMessage());
        panel.setLoading(false);
    }

    private void routeFromPanel(VerifiedLocation destination)
    {
        routeFromPanel(destination, false);
    }

    private void routeFromPanel(VerifiedLocation destination, boolean finalObjective)
    {
        IntegrationStatus integrations = integrationStatus();
        if (integrations.isShortestPathReady())
        {
            awaitingRouteTransport = true;
            if (finalObjective)
            {
                mapMarkerController.routeFinalObjective(destination);
            }
            else
            {
                mapMarkerController.route(destination);
            }
            panel.setStatus("Shortest Path route set for " + destination.getName() +
                ". Open the world map to view it.");
        }
        else
        {
            mapMarkerController.show(destination);
            panel.setStatus(shortestPathFallbackMessage(integrations));
        }
    }

    private void clearConversation()
    {
        if (guideService != null)
        {
            guideService.clearContext();
        }
        conversation.clear();
        automaticRouteGeneration++;
        finalObjectiveRouteTracker.clear();
        lastTravelDestination = null;
        lastAchievementDiaryQuery = null;
        lastQuestPreparationQuery = null;
        sessionDestinations.clear();
        if (mapMarkerController != null)
        {
            mapMarkerController.clear();
        }
    }

    private IntegrationStatus integrationStatus()
    {
        boolean shortestPathInstalled = false;
        boolean shortestPathActive = false;
        for (Plugin candidate : pluginManager.getPlugins())
        {
            if ("Shortest Path".equalsIgnoreCase(candidate.getName()))
            {
                shortestPathInstalled = true;
                shortestPathActive = pluginManager.isPluginActive(candidate);
                break;
            }
        }

        boolean playerContextEnabled = config.shareAllContext() || config.shareLocation() ||
            config.shareSkills() || config.shareCompletedQuests() || config.shareInventory() ||
            config.shareEquipment() || config.shareBank() || config.shareSlayerTask();
        return IntegrationStatus.evaluate(shortestPathInstalled, shortestPathActive,
            config.enableExternalRequests(), config.openAiApiKey(), playerContextEnabled);
    }

    private void refreshIntegrationStatus()
    {
        IntegrationStatus integrations = integrationStatus();
        SwingUtilities.invokeLater(() ->
        {
            if (panel != null)
            {
                panel.setIntegrationStatus(integrations);
                if (playerContextProvider != null)
                {
                    panel.setBankContextStatus(playerContextProvider.isBankSharingEnabled(),
                        playerContextProvider.hasBankSnapshot());
                }
            }
        });
    }

    private static String shortestPathFallbackMessage(IntegrationStatus integrations)
    {
        return integrations.getShortestPath() == IntegrationStatus.ShortestPath.DISABLED
            ? "Shortest Path is disabled. I added a verified map marker instead."
            : "Shortest Path is not installed. I added a verified map marker instead.";
    }

    private static String normalizeDestination(String value)
    {
        return value.toLowerCase(Locale.ENGLISH).replaceAll("[^a-z0-9]+", " ").trim();
    }
}

