public final class GuidePanel extends PluginPanel
{
    // RuneLite's standard sidebar is narrow. Give HTML its wrapping width before
    // BoxLayout measures the card, otherwise the preferred height is one clipped line.
    private static final int CARD_CONTENT_WIDTH = 190;

    private final JPanel history = new ViewportWidthPanel();
    private final JScrollPane historyScrollPane;
    private final JTextArea input = new JTextArea(3, 20);
    private final JButton sendButton = new JButton("Send");
    private final JButton clearButton = new JButton("Clear");
    private final JProgressBar loading = new JProgressBar();
    private final JLabel status = new JLabel(" ");
    private final JLabel setupStatus = new JLabel();
    private final Consumer<String> questionHandler;
    private final Runnable clearHandler;
    private final Consumer<VerifiedLocation> mapHandler;
    private IntegrationStatus latestIntegrationStatus;
    private boolean bankSharingEnabled;
    private boolean bankSnapshotReady;

    public GuidePanel(Consumer<String> questionHandler, Runnable clearHandler,
        Consumer<VerifiedLocation> mapHandler)
    {
        // This panel owns a fixed header/composer and a scrollable conversation.
        // Disable PluginPanel's outer wrapper so the two scroll panes do not nest.
        super(false);
        this.questionHandler = questionHandler;
        this.clearHandler = clearHandler;
        this.mapHandler = mapHandler;

        setLayout(new BorderLayout(0, 8));
        setBorder(new EmptyBorder(8, 8, 8, 8));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel header = new JPanel(new BorderLayout());
        header.setOpaque(false);
        JLabel title = new JLabel("Gielinor Guide");
        title.setFont(title.getFont().deriveFont(Font.BOLD, 16f));
        clearButton.setToolTipText("Clear this session's conversation");
        clearButton.addActionListener(event -> clearConversation());
        header.add(title, BorderLayout.WEST);
        header.add(clearButton, BorderLayout.EAST);
        JPanel top = new JPanel(new BorderLayout(0, 5));
        top.setOpaque(false);
        top.add(header, BorderLayout.NORTH);
        setupStatus.setOpaque(true);
        setupStatus.setBackground(new Color(48, 62, 52));
        setupStatus.setForeground(Color.WHITE);
        setupStatus.setBorder(new EmptyBorder(5, 7, 5, 7));
        setupStatus.setToolTipText("Gielinor Guide checks integrations without displaying or logging your API key.");
        top.add(setupStatus, BorderLayout.SOUTH);
        add(top, BorderLayout.NORTH);

        history.setLayout(new BoxLayout(history, BoxLayout.Y_AXIS));
        history.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        historyScrollPane = new JScrollPane(history);
        historyScrollPane.setBorder(BorderFactory.createEmptyBorder());
        historyScrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        historyScrollPane.setWheelScrollingEnabled(true);
        historyScrollPane.getVerticalScrollBar().setUnitIncrement(16);
        add(historyScrollPane, BorderLayout.CENTER);

        JPanel composer = new JPanel(new BorderLayout(0, 5));
        composer.setOpaque(false);
        input.setLineWrap(true);
        input.setWrapStyleWord(true);
        input.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        input.setForeground(Color.WHITE);
        input.setCaretColor(Color.WHITE);
        input.setBorder(new EmptyBorder(6, 6, 6, 6));
        input.getInputMap().put(KeyStroke.getKeyStroke("ENTER"), "guide-send");
        input.getActionMap().put("guide-send", new AbstractAction()
        {
            @Override
            public void actionPerformed(ActionEvent event)
            {
                send();
            }
        });
        input.getInputMap().put(KeyStroke.getKeyStroke("shift ENTER"), DefaultEditorKit.insertBreakAction);
        JScrollPane inputScroll = new JScrollPane(input);
        inputScroll.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
        composer.add(inputScroll, BorderLayout.CENTER);

        JPanel actions = new JPanel(new BorderLayout(5, 0));
        actions.setOpaque(false);
        loading.setIndeterminate(true);
        loading.setVisible(false);
        loading.setPreferredSize(new Dimension(70, 8));
        actions.add(loading, BorderLayout.CENTER);
        sendButton.addActionListener(event -> send());
        actions.add(sendButton, BorderLayout.EAST);

        JPanel lower = new JPanel(new BorderLayout(0, 3));
        lower.setOpaque(false);
        lower.add(actions, BorderLayout.NORTH);
        status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        lower.add(status, BorderLayout.SOUTH);
        composer.add(lower, BorderLayout.SOUTH);
        add(composer, BorderLayout.SOUTH);

        addWelcome();
