    public void setIntegrationStatus(IntegrationStatus integrationStatus)
    {
        latestIntegrationStatus = integrationStatus;
        renderIntegrationStatus();
    }

    public void setBankContextStatus(boolean sharingEnabled, boolean snapshotReady)
    {
        bankSharingEnabled = sharingEnabled;
        bankSnapshotReady = snapshotReady;
        renderIntegrationStatus();
    }

    private void renderIntegrationStatus()
    {
        IntegrationStatus integrationStatus = latestIntegrationStatus;
        if (integrationStatus == null)
        {
            return;
        }
        String shortestPath;
        switch (integrationStatus.getShortestPath())
        {
            case READY:
                shortestPath = "ready";
                break;
            case DISABLED:
                shortestPath = "disabled";
                break;
            default:
                shortestPath = "not installed";
                break;
        }

        String openAi;
        switch (integrationStatus.getOpenAi())
        {
            case READY:
                openAi = "ready";
                break;
            case KEY_MISSING:
                openAi = "API key missing";
                break;
            default:
                openAi = "off";
                break;
        }

        String bank = !bankSharingEnabled ? "" : bankSnapshotReady
            ? "<br>Bank context: ready"
            : "<br>Bank context: open bank once";
        setupStatus.setText("<html><b>Setup check</b><br>Routes: Shortest Path " + shortestPath +
            "<br>OpenAI Q&amp;A: " + openAi + "<br>Player context: " +
            (integrationStatus.isPlayerContextEnabled() ? "on" : "off") + bank + "</html>");
        setupStatus.setBackground(integrationStatus.isShortestPathReady()
            ? new Color(48, 62, 52) : new Color(91, 70, 42));
    }

    public void addUserMessage(String text)
    {
        addMessage("You", text, new Color(43, 77, 96));
    }

    public void addGuideResponse(GuideResponse response)
    {
        JPanel card = messageCard("Guide", response.getAnswer(), new Color(48, 62, 52));

        if (!response.getDestinations().isEmpty())
        {
            JPanel buttons = new JPanel();
            buttons.setLayout(new BoxLayout(buttons, BoxLayout.Y_AXIS));
            buttons.setOpaque(false);
            buttons.setAlignmentX(Component.LEFT_ALIGNMENT);
            for (VerifiedLocation location : response.getDestinations())
            {
                String buttonText = response.getDestinations().size() == 1
                    ? response.getRouting() == GuideResponse.Routing.ROUTE_NOW
                        ? "Reapply route" : "Route"
                    : "Route: " + location.getName();
                JButton button = new JButton(buttonText);
                button.setAlignmentX(Component.LEFT_ALIGNMENT);
                button.setMaximumSize(new Dimension(Integer.MAX_VALUE,
                    button.getPreferredSize().height));
                button.setToolTipText("Add a verified RuneLite world-map marker for " + location.getName());
                button.addActionListener(event ->
                {
                    mapHandler.accept(location);
                });
                buttons.add(button);
                buttons.add(Box.createVerticalStrut(3));
            }
            card.add(buttons);
        }

        if (!response.getSources().isEmpty())
        {
            JEditorPane sources = htmlPane(sourceHtml(response.getSources()));
            fitHtmlToCard(sources);
            sources.setToolTipText("Open source in your browser");
            card.add(sources);
        }
        addCard(card);
    }

    public void addError(String message)
    {
        addMessage("Guide error", message, new Color(91, 48, 48));
    }

    public void setLoading(boolean isLoading)
    {
        loading.setVisible(isLoading);
        sendButton.setEnabled(!isLoading);
        input.setEnabled(!isLoading);
        clearButton.setEnabled(true);
        status.setText(isLoading ? "Checking the OSRS Wiki and asking OpenAI..." : " ");
        if (!isLoading)
        {
            input.requestFocusInWindow();
        }
    }

    public void setStatus(String message)
    {
        status.setText(message);
    }

    public void clearConversation()
    {
        clearHandler.run();
        history.removeAll();
        addWelcome();
        input.setText("");
        setLoading(false);
        revalidate();
        repaint();
    }

    private void send()
    {
        String question = input.getText().trim();
        if (question.isEmpty() || !sendButton.isEnabled())
        {
            return;
        }
        input.setText("");
        questionHandler.accept(question);
    }

    private void addWelcome()
    {
        JPanel card = messageCard("Guide",
            "Ask an OSRS question. I check the OSRS Wiki before asking OpenAI, and only locally verified destinations get map buttons.\n\n" +
            "External requests and every player-context option start disabled. Configure them in RuneLite settings to begin.",
            new Color(48, 62, 52));
        addCard(card);
    }

    private void addMessage(String speaker, String text, Color background)
    {
        addCard(messageCard(speaker, text, background));
    }

    private JPanel messageCard(String speaker, String text, Color background)
    {
        JPanel card = new JPanel();
        card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
        card.setAlignmentX(Component.LEFT_ALIGNMENT);
        card.setBackground(background);
        card.setBorder(new EmptyBorder(7, 7, 7, 7));

        JLabel label = new JLabel(speaker);
        label.setForeground(new Color(230, 210, 132));
        label.setFont(label.getFont().deriveFont(Font.BOLD));
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        card.add(label);
        card.add(Box.createVerticalStrut(4));

        JEditorPane body = htmlPane("<html><body style='font-family:sans-serif;color:#f2f2f2'>" +
            escape(text).replace("\n", "<br>") + "</body></html>");
        fitHtmlToCard(body);
        card.add(body);
        return card;
    }

    private void addCard(JPanel card)
    {
        card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
        history.add(card);
        history.add(Box.createVerticalStrut(7));
        history.revalidate();
        SwingUtilities.invokeLater(() ->
        {
            history.doLayout();
            card.scrollRectToVisible(new Rectangle(0,
                Math.max(0, card.getHeight() - 1), 1, 1));
            SwingUtilities.invokeLater(() ->
            {
                historyScrollPane.getViewport().setViewPosition(new Point(0,
                    Math.max(0, history.getHeight() -
                        historyScrollPane.getViewport().getExtentSize().height)));
                historyScrollPane.getVerticalScrollBar().setValue(
                    historyScrollPane.getVerticalScrollBar().getMaximum());
            });
        });
        Timer bottomFollow = new Timer(75, event -> scrollToBottom());
        bottomFollow.setRepeats(false);
        bottomFollow.start();
    }

    private void scrollToBottom()
    {
        history.revalidate();
        historyScrollPane.validate();
        JScrollBar bar = historyScrollPane.getVerticalScrollBar();
        bar.setValue(bar.getMaximum());
        historyScrollPane.getViewport().setViewPosition(new Point(0,
            Math.max(0, history.getPreferredSize().height -
                historyScrollPane.getViewport().getExtentSize().height)));
    }

    private static JEditorPane htmlPane(String html)
    {
        JEditorPane pane = new JEditorPane("text/html", html);
        pane.setEditable(false);
        pane.setOpaque(false);
        pane.setBorder(null);
        pane.putClientProperty(JEditorPane.HONOR_DISPLAY_PROPERTIES, Boolean.TRUE);
        pane.addHyperlinkListener(event ->
        {
            if (event.getEventType() == javax.swing.event.HyperlinkEvent.EventType.ACTIVATED)
            {
                LinkBrowser.browse(event.getURL().toString());
            }
        });
        pane.setAlignmentX(Component.LEFT_ALIGNMENT);
        return pane;
    }

    private static void fitHtmlToCard(JEditorPane pane)
    {
        pane.setSize(new Dimension(CARD_CONTENT_WIDTH, Short.MAX_VALUE));
        Dimension preferred = pane.getPreferredSize();
        preferred.width = CARD_CONTENT_WIDTH;
        pane.setPreferredSize(preferred);
        pane.setMinimumSize(new Dimension(0, preferred.height));
        pane.setMaximumSize(new Dimension(Integer.MAX_VALUE, preferred.height));
    }

    private static String sourceHtml(List<WikiSource> sources)
    {
        StringBuilder html = new StringBuilder("<html><body style='font-family:sans-serif;color:#b8b8b8'><b>Sources</b><br>");
        for (WikiSource source : sources)
        {
            html.append("&#8226; <a style='color:#6fa8dc' href='")
                .append(escape(source.getUrl())).append("'>")
                .append(escape(source.getTitle())).append("</a><br>");
        }
        return html.append("</body></html>").toString();
    }

    private static String escape(String text)
    {
        return text.replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
            .replace("\"", "&quot;")
            .replace("'", "&#39;");
    }

    private static final class ViewportWidthPanel extends JPanel implements Scrollable
    {
        @Override
        public Dimension getPreferredScrollableViewportSize()
        {
            return getPreferredSize();
        }

        @Override
        public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation,
            int direction)
        {
            return 16;
        }

        @Override
        public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation,
            int direction)
        {
            return Math.max(16, visibleRect.height - 16);
        }

        @Override
        public boolean getScrollableTracksViewportWidth()
        {
            return true;
        }

        @Override
        public boolean getScrollableTracksViewportHeight()
        {
            return false;
        }
    }
}

package com.gielinorguide;

import java.util.List;

/** The small, outcome-focused prompt used by the active OSRS chat path. */
final class GuidePrompt
{
    static final String SYSTEM =
        "You are Gielinor Guide, an expert Old School RuneScape chat assistant inside RuneLite. " +
        "Answer the newest question directly, naturally, and concisely. Use recent chat to resolve " +
        "follow-ups such as 'help me do this', but switch subjects when the player names a new goal. " +
        "For 'best way' questions, state the criterion you are optimizing and give the best practical " +
        "next action first. For 'help me do this', give a short actionable plan instead of a topic summary. " +
        "Use the supplied OSRS Wiki evidence as the current authority and player context when relevant. " +
        "You may use reliable OSRS knowledge to connect the evidence, but do not invent exact current " +
        "requirements, prices, drop rates, coordinates, ownership, or completion state. If one exact fact " +
        "is uncertain, say that briefly and still answer everything the evidence does establish. " +
        "Treat completion lists as exhaustive: listed quests and diary tiers are completed, and absent " +
        "entries are unfinished. If a list was not provided, completion is unknown. Never use post-quest " +
        "instructions for an unfinished quest or recommend a completed diary tier. " +
        "For an active Slayer task, respect the remaining count and assigned-area restriction. In the first " +
        "general task-help answer, include enemy attack types and distinguish normal attack-style defence, " +
        "elemental weakness (or explicitly say none), and optional specialty effects such as demonbane; do not " +
        "make the player ask again for weakness information. Answer focused follow-ups narrowly. For navigation " +
        "questions, lead with the " +
        "exact verified destination and only the access, protection, or setup needed to reach it and start. " +
        "A verified destination makes a Route action available; Shortest Path performs navigation. Never " +
        "invent a route target or claim that a route, marker, plugin, or inventory action already happened. " +
        "Use plain text and short bullets when useful. Do not use Markdown tables. Do not pad the answer with " +
        "generic warnings, repeated context, or unrelated alternatives.";

    private GuidePrompt()
    {
    }

    static String build(WikiResult wikiResult, String playerContext,
        List<VerifiedLocation> destinations, TravelResolver travelResolver)
    {
        return SYSTEM +
            "\n\nVERIFIED DESTINATION FOR THIS QUESTION:\n" +
            destinationGrounding(destinations) +
            "\nVERIFIED TRAVEL OPTIONS:\n" +
            travelResolver.asGroundingText(destinations) +
            "\nOSRS WIKI EVIDENCE:\n" + wikiResult.asGroundingText() +
            "\nPLAYER CONTEXT:\n" + usefulContext(playerContext);
    }

    private static String destinationGrounding(List<VerifiedLocation> destinations)
    {
        if (destinations.isEmpty())
        {
            return "None. Do not promise a Route action or invent a destination.";
        }
        StringBuilder text = new StringBuilder();
        for (VerifiedLocation destination : destinations)
        {
            text.append("- ").append(destination.getName()).append(": ")
                .append(destination.getGuidance()).append(" Source: ")
                .append(destination.getSourceUrl()).append('\n');
        }
        return text.toString().trim();
    }

    private static String usefulContext(String playerContext)
    {
        return playerContext == null || playerContext.trim().isEmpty()
            ? "No player context was shared." : playerContext.trim();
    }
}

