package com.gielinorguide;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;

public final class GuideService
{
    private final WikiClient wikiClient;
    private final OpenAiClient openAiClient;
    private final ConversationState conversation;
    private final LocationResolver locationResolver;
    private final TravelResolver travelResolver;
    private final SlayerAnswerGuard slayerAnswerGuard;
    private final SessionGroundingState sessionGrounding = new SessionGroundingState();

    public GuideService(WikiClient wikiClient, OpenAiClient openAiClient,
        ConversationState conversation, LocationResolver locationResolver,
        TravelResolver travelResolver)
    {
        this.wikiClient = wikiClient;
        this.openAiClient = openAiClient;
        this.conversation = conversation;
        this.locationResolver = locationResolver;
        this.travelResolver = travelResolver;
        this.slayerAnswerGuard = new SlayerAnswerGuard(locationResolver);
    }

    public void ask(String question, String playerContext, String apiKey, String model,
        Consumer<GuideResponse> onSuccess, Consumer<GuideApiException> onError)
    {
        ask(question, playerContext, apiKey, model, Collections.emptyList(), onSuccess, onError);
    }

    public void ask(String question, String playerContext, String apiKey, String model,
        List<VerifiedLocation> suppliedDestinations,
        Consumer<GuideResponse> onSuccess, Consumer<GuideApiException> onError)
    {
        ask(question, playerContext, apiKey, model, suppliedDestinations, null,
            onSuccess, onError);
    }

    public void ask(String question, String playerContext, String apiKey, String model,
        List<VerifiedLocation> suppliedDestinations, String wikiQueryOverride,
        Consumer<GuideResponse> onSuccess, Consumer<GuideApiException> onError)
    {
        List<GuideMessage> history = conversation.snapshot();
        List<VerifiedLocation> contextDestinations = mergeDestinations(suppliedDestinations,
            locationResolver.resolveForResponse(question, "", history));
        Consumer<WikiResult> continueWithGrounding = wikiResult ->
        {
            sessionGrounding.remember(wikiResult);
            boolean slayerLookup = wikiQueryOverride != null &&
                wikiQueryOverride.toLowerCase(java.util.Locale.ENGLISH)
                    .startsWith("slayer task/");
            List<VerifiedLocation> groundedDestinations = mergeDestinations(
                contextDestinations, wikiResult.getDestinations());
            if (slayerLookup || isDestinationQuestion(question))
            {
                groundedDestinations = mergeDestinations(groundedDestinations,
                    locationResolver.resolveNamedMentions(wikiResult.asGroundingText()));
            }
            String instructions = buildInstructions(
                wikiResult, playerContext, groundedDestinations);
            List<VerifiedLocation> responseDestinations = groundedDestinations;
            Consumer<String> acceptAnswer = answer ->
            {
                String finalAnswer = answer == null ? "" : answer.trim();
                List<VerifiedLocation> destinations;
                if (slayerLookup)
                {
                    SlayerAnswerGuard.Result guarded = slayerAnswerGuard.enforce(
                        question, finalAnswer, playerContext, wikiResult,
                        responseDestinations);
                    finalAnswer = guarded.getAnswer();
                    destinations = guarded.getDestinations();
                }
                else
                {
                    destinations = selectResponseDestinations(
                        question, finalAnswer, responseDestinations,
                        locationResolver.resolveForResponse(question, finalAnswer, history));
                }
                List<WikiSource> sources = mergeSources(
                    wikiResult.getSources(), destinations, travelResolver);
                onSuccess.accept(new GuideResponse(finalAnswer, sources, destinations));
            };
            openAiClient.createResponse(apiKey, model, instructions, history,
                acceptAnswer, onError);
        };
        boolean hasExplicitWikiTarget = wikiQueryOverride != null &&
            !wikiQueryOverride.trim().isEmpty();
        WikiResult carriedGrounding = sessionGrounding.forFollowUp(
            question, hasExplicitWikiTarget);
        if (carriedGrounding != null)
        {
            continueWithGrounding.accept(carriedGrounding);
        }
        else
        {
            String wikiQuery = wikiQueryOverride == null || wikiQueryOverride.trim().isEmpty()
                ? buildWikiSearchQuery(question, contextDestinations)
                : wikiQueryOverride.trim();
            Runnable deterministicSearch = () -> searchWiki(question, wikiQuery, null,
                playerContext,
                continueWithGrounding);
            if ((wikiQueryOverride == null || wikiQueryOverride.trim().isEmpty()) &&
                WikiQueryPlanner.needsSemanticPlanning(question, wikiQuery))
            {
                openAiClient.createWikiQueryPlan(apiKey, model, history,
                    plan ->
                    {
                        if (WikiQueryPlanner.isSemanticQuerySupportedByConversation(
                            question, history, plan.getQuery()))
                        {
                            searchWiki(question, plan.getQuery(), plan.getIntent(),
                                playerContext,
                                continueWithGrounding);
                        }
                        else
                        {
                            deterministicSearch.run();
                        }
                    },
                    deterministicSearch);
            }
            else
            {
                deterministicSearch.run();
            }
        }
    }

    private void searchWiki(String question, String wikiQuery,
        SemanticWikiQuery.Intent semanticIntent, String playerContext,
        Consumer<WikiResult> callback)
    {
        boolean slayerProgression = WikiQueryPlanner.isSlayerProgressionQuery(wikiQuery);
        boolean comparison = WikiQueryPlanner.isComparisonQuestion(question) ||
            semanticIntent == SemanticWikiQuery.Intent.COMPARISON || slayerProgression;
        boolean hasComparisonCandidates =
            !WikiComparisonExpander.candidatePages(wikiQuery).isEmpty();
        boolean charging = WikiQueryPlanner.isChargingQuestion(question);
        boolean acquisition = !charging && (WikiQueryPlanner.isAcquisitionQuestion(question) ||
            semanticIntent == SemanticWikiQuery.Intent.ACQUISITION) &&
            ("Slayer helmet".equals(wikiQuery) ||
                !(comparison && hasComparisonCandidates));
        boolean purpose = charging || WikiQueryPlanner.isPurposeQuestion(question) ||
            semanticIntent == SemanticWikiQuery.Intent.PURPOSE;
        boolean questReadiness = WikiQueryPlanner.isQuestReadinessQuestion(question, wikiQuery);
        boolean questWalkthrough = WikiQueryPlanner.isQuestWalkthroughQuestion(
            question, wikiQuery);
        boolean diaryWalkthrough = WikiQueryPlanner.isAchievementDiaryWalkthroughQuestion(
            question, wikiQuery);
        boolean questGuidance = WikiPageCatalog.isQuestPage(wikiQuery) ||
            WikiQueryPlanner.isQuestRequirementQuestion(question) ||
            questReadiness ||
            questWalkthrough ||
            semanticIntent == SemanticWikiQuery.Intent.QUEST;
        boolean accessGuidance = WikiQueryPlanner.isAccessQuestion(question);
        Consumer<WikiResult> finish = result ->
        {
            if (questReadiness || questWalkthrough || diaryWalkthrough)
            {
                expandQuestTrainingGuides(result,
                    QuestPreparationPlanner.missingTrainingPages(result, playerContext),
                    0, callback);
            }
            else
            {
                callback.accept(result);
            }
        };
        wikiClient.search(wikiQuery, acquisition, purpose, comparison,
            questGuidance, accessGuidance, finish);
    }

    private void expandQuestTrainingGuides(WikiResult accumulated, List<String> pages,
        int index, Consumer<WikiResult> callback)
    {
        if (index >= pages.size())
        {
            callback.accept(accumulated);
            return;
        }
        wikiClient.search(pages.get(index), training ->
        {
            WikiSource primary = training.getPrimarySource();
            WikiResult focused = primary == null ? WikiResult.unavailable() :
                new WikiResult(Collections.singletonList(primary), training.isAvailable(),
                    training.getDestinations());
            expandQuestTrainingGuides(mergeWikiResults(accumulated, focused), pages,
                index + 1, callback);
        });
    }

    private static WikiResult mergeWikiResults(WikiResult first, WikiResult second)
    {
        Map<String, WikiSource> sources = new LinkedHashMap<>();
        for (WikiSource source : first.getSources())
        {
            sources.put(source.getUrl(), source);
        }
        for (WikiSource source : second.getSources())
        {
            sources.put(source.getUrl(), source);
        }
        return new WikiResult(new ArrayList<>(sources.values()),
            first.isAvailable() || second.isAvailable(),
            mergeDestinations(first.getDestinations(), second.getDestinations()));
    }

    public void cancel()
    {
        wikiClient.cancel();
        openAiClient.cancel();
    }

    public void clearContext()
    {
        cancel();
        sessionGrounding.clear();
    }

    private String buildInstructions(WikiResult wikiResult, String playerContext,
        List<VerifiedLocation> contextDestinations)
    {
        return GuidePrompt.build(wikiResult, playerContext, contextDestinations,
            travelResolver);
    }

    private static boolean isDestinationQuestion(String question)
    {
        String normalized = question == null ? "" : question.toLowerCase(
            java.util.Locale.ENGLISH).replaceAll("[^a-z0-9]+", " ").trim();
        return WikiQueryPlanner.isAccessQuestion(question) || normalized.startsWith("where ") ||
            normalized.matches(".*\\b(?:what|which) (?:place|location|route)\\b.*");
    }

    static List<VerifiedLocation> selectResponseDestinations(String question, String answer,
        List<VerifiedLocation> available, List<VerifiedLocation> mentioned)
    {
        List<VerifiedLocation> trusted = mergeDestinations(available, mentioned);
        VerifiedLocation firstMentioned = firstMentionedDestination(answer, trusted);
        if (firstMentioned != null)
        {
            return Collections.singletonList(firstMentioned);
        }
        if (trusted.size() == 1)
        {
            return trusted;
        }
        // Multiple locations may all be valid for a monster, but Shortest Path needs one
        // deliberate target. Never pick an arbitrary Wiki/catalog ordering.
        return Collections.emptyList();
    }

    private static VerifiedLocation firstMentionedDestination(String answer,
        List<VerifiedLocation> destinations)
    {
        String normalizedAnswer = normalizeForMatch(answer);
        VerifiedLocation best = null;
        int bestPosition = Integer.MAX_VALUE;
        for (VerifiedLocation destination : destinations)
        {
            List<String> names = new ArrayList<>();
            names.add(destination.getName());
            names.addAll(destination.getAliases());
            for (String name : names)
            {
                String normalizedName = normalizeForMatch(name);
                if (normalizedName.length() < 4)
                {
                    continue;
                }
                int position = (" " + normalizedAnswer + " ").indexOf(
                    " " + normalizedName + " ");
                if (position >= 0 && position < bestPosition)
                {
                    best = destination;
                    bestPosition = position;
                }
            }
        }
        return best;
    }

    private static String normalizeForMatch(String value)
    {
        return value == null ? "" : value.toLowerCase(java.util.Locale.ENGLISH)
            .replaceAll("[^a-z0-9]+", " ").trim();
    }

    private static List<VerifiedLocation> mergeDestinations(List<VerifiedLocation> first,
        List<VerifiedLocation> second)
    {
        Map<String, VerifiedLocation> merged = new LinkedHashMap<>();
        for (VerifiedLocation destination : first)
        {
            merged.put(destination.getId(), destination);
        }
        for (VerifiedLocation destination : second)
        {
            merged.put(destination.getId(), destination);
        }
        return new ArrayList<>(merged.values());
    }

    private static List<WikiSource> mergeSources(List<WikiSource> wikiSources,
        List<VerifiedLocation> destinations, TravelResolver travelResolver)
    {
        Map<String, WikiSource> sources = new LinkedHashMap<>();
        for (WikiSource source : wikiSources)
        {
            sources.put(source.getUrl(), source);
        }
        for (VerifiedLocation destination : destinations)
        {
            sources.put(destination.getSourceUrl(), new WikiSource(
                destination.getName(), destination.getSourceUrl(), destination.getGuidance()));
            for (VerifiedTravelOption option : travelResolver.forDestination(destination.getId()))
            {
                sources.put(option.getSourceUrl(), new WikiSource(
                    option.getName(), option.getSourceUrl(), option.getGuidance()));
            }
        }
        return new ArrayList<>(sources.values());
    }

    static String buildWikiSearchQuery(String question, List<VerifiedLocation> destinations)
    {
        String plannedQuery = WikiQueryPlanner.plan(question);
        if (destinations.isEmpty())
        {
            return plannedQuery;
        }
        StringBuilder query = new StringBuilder(plannedQuery);
        String normalizedPlanned = plannedQuery.toLowerCase(java.util.Locale.ENGLISH)
            .replaceAll("[^a-z0-9]+", " ").trim();
        for (VerifiedLocation destination : destinations)
        {
            String normalizedDestination = destination.getName()
                .toLowerCase(java.util.Locale.ENGLISH)
                .replaceAll("[^a-z0-9]+", " ").trim();
            if (!(" " + normalizedPlanned + " ").contains(" " + normalizedDestination + " "))
            {
                query.append(' ').append(destination.getName());
            }
        }
        return query.toString();
    }
}

package com.gielinorguide;

public final class IntegrationStatus
{
    public enum ShortestPath
    {
        READY,
        DISABLED,
        NOT_INSTALLED
    }

    public enum OpenAi
    {
        READY,
        EXTERNAL_REQUESTS_OFF,
        KEY_MISSING
    }

    private final ShortestPath shortestPath;
    private final OpenAi openAi;
    private final boolean playerContextEnabled;

    private IntegrationStatus(ShortestPath shortestPath, OpenAi openAi,
        boolean playerContextEnabled)
    {
        this.shortestPath = shortestPath;
        this.openAi = openAi;
        this.playerContextEnabled = playerContextEnabled;
    }

    public static IntegrationStatus evaluate(boolean shortestPathInstalled,
        boolean shortestPathActive, boolean externalRequestsEnabled, String apiKey,
        boolean playerContextEnabled)
    {
        ShortestPath shortestPath = !shortestPathInstalled
            ? ShortestPath.NOT_INSTALLED
            : shortestPathActive ? ShortestPath.READY : ShortestPath.DISABLED;
        OpenAi openAi = !externalRequestsEnabled
            ? OpenAi.EXTERNAL_REQUESTS_OFF
            : apiKey == null || apiKey.trim().isEmpty() ? OpenAi.KEY_MISSING : OpenAi.READY;
        return new IntegrationStatus(shortestPath, openAi, playerContextEnabled);
    }

    public ShortestPath getShortestPath()
    {
        return shortestPath;
    }

    public OpenAi getOpenAi()
    {
        return openAi;
    }

    public boolean isPlayerContextEnabled()
    {
        return playerContextEnabled;
    }

    public boolean isShortestPathReady()
    {
        return shortestPath == ShortestPath.READY;
    }
}

package com.gielinorguide;

import java.util.List;
import java.util.Locale;
import java.util.Optional;

public final class LocalMapIntentResolver
{
    private final LocationResolver locationResolver;

    public LocalMapIntentResolver(LocationResolver locationResolver)
    {
        this.locationResolver = locationResolver;
    }

    public Optional<VerifiedLocation> resolve(String question)
    {
        String normalized = question.toLowerCase(Locale.ENGLISH)
            .replaceAll("[^a-z0-9]+", " ").trim();
        boolean mapCommand = normalized.contains("show on map") ||
            normalized.contains("show me on map") || normalized.contains("mark the map") ||
            normalized.contains("mark on map") || normalized.contains("map marker") ||
            normalized.contains("add marker") || normalized.contains("place marker") ||
            normalized.contains("drop a pin") || normalized.contains("pin on map") ||
            normalized.startsWith("pin ") || normalized.startsWith("mark ") ||
            normalized.startsWith("map ") || normalized.startsWith("waypoint ") ||
            normalized.startsWith("ping ");
        if (!mapCommand)
        {
            return Optional.empty();
        }

        List<VerifiedLocation> destinations = locationResolver.resolveMentions(question);
        return destinations.size() == 1 ? Optional.of(destinations.get(0)) : Optional.empty();
    }
}

