    }

    private static void add(Map<String, VerifiedLocation> target, VerifiedLocation location)
    {
        target.put(location.getId(), location);
    }

    public Collection<VerifiedLocation> all()
    {
        return locations.values();
    }

    public VerifiedLocation byId(String id)
    {
        return locations.get(id);
    }

    public List<VerifiedLocation> resolveMentions(String text)
    {
        Map<String, VerifiedLocation> resolved = new LinkedHashMap<>();
        Map<String, Integer> positions = new LinkedHashMap<>();
        String normalized = normalize(text);
        for (VerifiedLocation location : locations.values())
        {
            int position = phraseIndex(normalized, normalize(location.getName()));
            if (position >= 0)
            {
                resolved.put(location.getId(), location);
                positions.put(location.getId(), position);
            }
            for (String alias : location.getAliases())
            {
                int aliasPosition = phraseIndex(normalized, normalize(alias));
                if (aliasPosition >= 0 &&
                    (!positions.containsKey(location.getId()) ||
                        aliasPosition < positions.get(location.getId())))
                {
                    resolved.put(location.getId(), location);
                    positions.put(location.getId(), aliasPosition);
                }
            }
        }
        // Prefer a specific verified place over its containing city when both names
        // appear in the same phrase (for example, "Falador Hairdresser").
        if (resolved.size() > 1 && resolved.containsKey("falador"))
        {
            for (VerifiedLocation location : resolved.values())
            {
                if (!"falador".equals(location.getId()) &&
                    normalize(location.getName()).contains("falador"))
                {
                    resolved.remove("falador");
                    break;
                }
            }
        }
        List<VerifiedLocation> ordered = new ArrayList<>(resolved.values());
        ordered.sort(Comparator.comparingInt(location -> positions.get(location.getId())));
        return ordered;
    }

    /** Resolves full location names only, avoiding short aliases in long Wiki excerpts. */
    public List<VerifiedLocation> resolveNamedMentions(String text)
    {
        List<VerifiedLocation> resolved = new ArrayList<>();
        Map<String, Integer> positions = new LinkedHashMap<>();
        String normalized = normalize(text);
        for (VerifiedLocation location : locations.values())
        {
            int position = phraseIndex(normalized, normalize(location.getName()));
            if (position >= 0)
            {
                resolved.add(location);
                positions.put(location.getId(), position);
            }
        }
        resolved.sort(Comparator.comparingInt(location -> positions.get(location.getId())));
        return resolved;
    }

    public List<VerifiedLocation> resolveForResponse(String question, String answer,
        List<GuideMessage> previousMessages)
    {
        Map<String, VerifiedLocation> resolved = new LinkedHashMap<>();
        // A training or item answer can mention several places as supporting
        // context. Those are not necessarily the player's requested destination.
        // Only turn answer text into route actions when the user actually asked
        // for navigation; explicit place names in the question remain eligible.
        if (isNavigationIntent(question) || isSlayerTaskIntent(question))
        {
            addAll(resolved, resolveMentions(answer));
        }
        addAll(resolved, resolveMentions(question));

        String q = normalize(question);
        if (containsAny(q, "hair", "haircut", "hairstyle", "beard", "facial hair"))
        {
            put(resolved, "falador-hairdresser");
            resolved.remove("falador");
        }
        if (containsAny(q, "skin colour", "skin color", "body type", "gender", "pronoun"))
        {
            put(resolved, "makeover-mage");
        }
        if (containsAny(q, "clothes", "clothing", "outfit", "shirt", "trousers"))
        {
            put(resolved, "thessalia");
        }

        if (containsAny(q, "there", "that place", "that npc", "get there"))
        {
            for (int i = previousMessages.size() - 1; i >= 0; i--)
            {
                List<VerifiedLocation> prior = resolveMentions(previousMessages.get(i).getText());
                if (!prior.isEmpty())
                {
                    resolved.clear();
                    addAll(resolved, prior);
                    break;
                }
            }
        }
        return new ArrayList<>(resolved.values());
    }

    private static boolean isNavigationIntent(String question)
    {
        String q = normalize(question);
        return containsAny(q,
            "get to", "go to", "travel to", "route to", "directions to",
            "walk to", "run to", "teleport to", "reach ", "where is",
            "where s", "show on map", "mark on map", "map location",
            "fastest way to", "quickest way to", "shortest way to");
    }

    private static boolean isSlayerTaskIntent(String question)
    {
        String q = normalize(question);
        return containsAny(q, "slayer task", "slayer assignment", "my task",
            "my new task", "my latest task", "new task", "latest task",
            "my assignment", "new assignment", "current task", "finish my task",
            "do my task", "task i just got", "assignment i just got");
    }

    public String asGroundingText()
    {
        StringBuilder result = new StringBuilder();
        for (VerifiedLocation location : locations.values())
        {
            result.append("- ").append(location.getName()).append(": ")
                .append(location.getGuidance()).append(" Source: ")
                .append(location.getSourceUrl()).append('\n');
        }
        return result.toString();
    }

    private void put(Map<String, VerifiedLocation> target, String id)
    {
        VerifiedLocation location = locations.get(id);
        if (location != null)
        {
            target.put(id, location);
        }
    }

    private static void addAll(Map<String, VerifiedLocation> target, List<VerifiedLocation> values)
    {
        for (VerifiedLocation value : values)
        {
            target.put(value.getId(), value);
        }
    }

    private static boolean containsAny(String text, String... phrases)
    {
        return Arrays.stream(phrases).anyMatch(phrase -> containsPhrase(text, normalize(phrase)));
    }

    private static boolean containsPhrase(String text, String phrase)
    {
        return phraseIndex(text, phrase) >= 0;
    }

    private static int phraseIndex(String text, String phrase)
    {
        java.util.regex.Matcher matcher =
            Pattern.compile("(^|[^a-z0-9])" + Pattern.quote(phrase) + "([^a-z0-9]|$)")
                .matcher(text);
        if (matcher.find())
        {
            return matcher.start() + matcher.group(1).length();
        }
        return -1;
    }

    private static String normalize(String text)
    {
        return text == null ? "" : text.toLowerCase(Locale.ENGLISH)
            .replace('\u2019', '\'')
            .replaceAll("\\s+", " ")
            .trim();
    }
}

package com.gielinorguide;

import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

public final class MapMarkerController
{
    private final Client client;
    private final ClientThread clientThread;
    private final WorldMapPointManager pointManager;
    private final EventBus eventBus;
    private final BufferedImage markerImage = GuideIcons.mapMarker();
    private WorldMapPoint activeMarker;
    private boolean shortestPathRouteActive;

    public MapMarkerController(Client client, ClientThread clientThread,
        WorldMapPointManager pointManager, EventBus eventBus)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.pointManager = pointManager;
        this.eventBus = eventBus;
    }

    public void show(VerifiedLocation location)
    {
        removeGuideMarker();
        activeMarker = WorldMapPoint.builder()
            .worldPoint(location.getWorldPoint())
            .target(location.getWorldPoint())
            .image(markerImage)
            .tooltip(location.getName())
            .jumpOnClick(true)
            .name(location.getName())
            .build();
        pointManager.add(activeMarker);
        focusMap(location);
    }

    public void route(VerifiedLocation location)
    {
        route(location.getRouteWorldPoint());
    }

    public void routeFinalObjective(VerifiedLocation location)
    {
        route(location.getWorldPoint());
    }

    private void route(WorldPoint target)
    {
        removeGuideMarker();
        shortestPathRouteActive = true;
        clientThread.invokeLater(() ->
        {
            Player player = client.getLocalPlayer();
            WorldPoint start = player == null ? null :
                WorldPoint.fromLocalInstance(client, player.getLocalLocation());
            eventBus.post(new PluginMessage("shortestpath", "path",
                shortestPathPayload(target, start)));
            client.getWorldMap().setWorldMapPositionTarget(target);
        });
    }

    public void clear()
    {
        removeGuideMarker();
        if (shortestPathRouteActive)
        {
            shortestPathRouteActive = false;
            clientThread.invokeLater(() ->
                eventBus.post(new PluginMessage("shortestpath", "clear")));
        }
    }

    private void removeGuideMarker()
    {
        if (activeMarker != null)
        {
            pointManager.remove(activeMarker);
            activeMarker = null;
        }
    }

    private void focusMap(VerifiedLocation location)
    {
        clientThread.invokeLater(() ->
            client.getWorldMap().setWorldMapPositionTarget(location.getWorldPoint()));
    }

    static Map<String, Object> shortestPathPayload(WorldPoint target)
    {
        return shortestPathPayload(target, null);
    }

    static Map<String, Object> shortestPathPayload(WorldPoint target, WorldPoint start)
    {
        Map<String, Object> data = new HashMap<>();
        if (start != null)
        {
            data.put("start", start);
        }
        data.put("target", target);
        Map<String, Object> config = new HashMap<>();
        config.put("postTransports", true);
        data.put("config", config);
        return data;
    }
}

package com.gielinorguide;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.net.ConnectException;
import java.net.SocketTimeoutException;
import java.net.UnknownHostException;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.net.ssl.SSLException;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

public final class OpenAiClient
{
    private static final String RESPONSES_URL = "https://api.openai.com/v1/responses";
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    static final int CONNECT_TIMEOUT_SECONDS = 20;
    static final int WRITE_TIMEOUT_SECONDS = 30;
    static final int READ_TIMEOUT_SECONDS = 120;
    static final int CALL_TIMEOUT_SECONDS = 150;
    private final OkHttpClient httpClient;
    private final Gson gson;
    private final OpenAiResponseParser parser;
    private volatile Call activeCall;

    public OpenAiClient(OkHttpClient httpClient, Gson gson)
    {
        // Model generation routinely takes longer than OkHttp's short defaults. Clone RuneLite's
        // managed client so only OpenAI calls receive these bounded, asynchronous timeouts.
        this.httpClient = httpClient.newBuilder()
            .connectTimeout(CONNECT_TIMEOUT_SECONDS, TimeUnit.SECONDS)
            .writeTimeout(WRITE_TIMEOUT_SECONDS, TimeUnit.SECONDS)
            .readTimeout(READ_TIMEOUT_SECONDS, TimeUnit.SECONDS)
            .callTimeout(CALL_TIMEOUT_SECONDS, TimeUnit.SECONDS)
            .build();
        this.gson = gson;
        this.parser = new OpenAiResponseParser(gson);
    }

    public void createResponse(String apiKey, String model, String instructions,
        List<GuideMessage> messages, Consumer<String> onSuccess, Consumer<GuideApiException> onError)
    {
        JsonObject requestJson = buildRequestJson(model, instructions, messages);

        Request request = new Request.Builder()
            .url(RESPONSES_URL)
            .header("Authorization", "Bearer " + apiKey)
            .header("Content-Type", "application/json")
            .post(RequestBody.create(JSON, gson.toJson(requestJson)))
            .build();

        Call call = httpClient.newCall(request);
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                clearActiveCall(call);
                if (!call.isCanceled())
                {
                    onError.accept(new GuideApiException(friendlyConnectionError(exception)));
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    String responseText = body == null ? "" : body.string();
                    if (!response.isSuccessful())
                    {
                        onError.accept(new GuideApiException(
                            friendlyHttpError(response.code(), responseText)));
                        return;
                    }
                    onSuccess.accept(parser.parse(responseText));
                }
                catch (IOException | RuntimeException exception)
                {
                    onError.accept(new GuideApiException(
                        "OpenAI returned a response the guide could not read. Please try again."));
                }
                finally
                {
                    clearActiveCall(call);
                }
            }
        });
    }

    void createWikiQueryPlan(String apiKey, String model, List<GuideMessage> messages,
        Consumer<SemanticWikiQuery> onSuccess, Runnable onFallback)
    {
        JsonObject requestJson = buildWikiQueryPlanRequestJson(model, messages);
        Request request = new Request.Builder()
            .url(RESPONSES_URL)
            .header("Authorization", "Bearer " + apiKey)
            .header("Content-Type", "application/json")
            .post(RequestBody.create(JSON, gson.toJson(requestJson)))
            .build();
        Call call = httpClient.newCall(request);
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                clearActiveCall(call);
                if (!call.isCanceled())
                {
                    onFallback.run();
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    String responseText = body == null ? "" : body.string();
                    if (!response.isSuccessful())
                    {
                        onFallback.run();
                        return;
                    }
                    onSuccess.accept(SemanticWikiQuery.parse(gson,
                        parser.parse(responseText)));
                }
                catch (IOException | RuntimeException exception)
                {
                    onFallback.run();
                }
                finally
                {
                    clearActiveCall(call);
                }
            }
        });
    }

    static JsonObject buildRequestJson(String model, String instructions,
        List<GuideMessage> messages)
    {
        JsonObject requestJson = new JsonObject();
        requestJson.addProperty("model", model);
        requestJson.addProperty("instructions", instructions);
        requestJson.addProperty("store", false);
        requestJson.addProperty("prompt_cache_key", "gielinor-guide-chat-v2");
        requestJson.addProperty("max_output_tokens", 650);
        if (model.equals("gpt-5.6") || model.startsWith("gpt-5.6-") ||
            model.startsWith("gpt-5.4"))
        {
            JsonObject reasoning = new JsonObject();
            reasoning.addProperty("effort", "none");
            requestJson.add("reasoning", reasoning);
        }
        JsonObject text = new JsonObject();
        text.addProperty("verbosity", "low");
        requestJson.add("text", text);

        JsonArray input = new JsonArray();
        for (GuideMessage message : messages)
        {
            JsonObject item = new JsonObject();
            item.addProperty("role", message.getRole().getApiName());
            item.addProperty("content", message.getText());
            input.add(item);
        }
        requestJson.add("input", input);
        return requestJson;
    }

    static JsonObject buildWikiQueryPlanRequestJson(String model,
        List<GuideMessage> messages)
    {
        JsonObject request = buildRequestJson(model,
            "Normalize the latest player message into one concise Old School RuneScape Wiki " +
                "page title or search subject. Use conversation only to resolve genuine " +
                "follow-ups. Classify the player's intent as acquisition, purpose, comparison, " +
                "quest, diary, training, or general. Use diary for an Achievement Diary, one " +
                "of its tiers, or one or more diary tasks; normalize a named tier as " +
                "'<Area> Diary#<Easy|Medium|Hard|Elite>'. Acquisition includes any wording whose practical " +
                "goal is obtaining, making, assembling, or unlocking something. Do not answer " +
                "the question and do not include search instructions in query.",
            messages);
        request.addProperty("max_output_tokens", 100);
        request.addProperty("prompt_cache_key", "gielinor-guide-query-router-v1");
        if (request.has("reasoning"))
        {
            request.getAsJsonObject("reasoning").addProperty("effort", "none");
        }
        request.getAsJsonObject("text").add("format", wikiQueryPlanFormat());
        return request;
    }

    private static JsonObject wikiQueryPlanFormat()
    {
        JsonObject intent = stringSchema();
        JsonArray values = new JsonArray();
        for (String value : new String[]{"acquisition", "purpose", "comparison",
            "quest", "diary", "training", "general"})
        {
            values.add(value);
        }
        intent.add("enum", values);
        JsonObject properties = new JsonObject();
        properties.add("query", stringSchema());
        properties.add("intent", intent);
        JsonObject format = new JsonObject();
        format.addProperty("type", "json_schema");
        format.addProperty("name", "wiki_query_plan");
        format.addProperty("strict", true);
        format.add("schema", objectSchema(properties, "query", "intent"));
        return format;
    }

    private static JsonObject stringSchema()
    {
        JsonObject schema = new JsonObject();
        schema.addProperty("type", "string");
        return schema;
    }

    private static JsonObject objectSchema(JsonObject properties, String... requiredNames)
    {
        JsonObject schema = new JsonObject();
        schema.addProperty("type", "object");
        schema.add("properties", properties);
        JsonArray required = new JsonArray();
        for (String name : requiredNames)
        {
            required.add(name);
        }
        schema.add("required", required);
        schema.addProperty("additionalProperties", false);
        return schema;
    }

    public void cancel()
    {
        Call call = activeCall;
        if (call != null)
        {
            call.cancel();
        }
    }

    private void clearActiveCall(Call completedCall)
    {
        if (activeCall == completedCall)
        {
            activeCall = null;
        }
    }

    int connectTimeoutMillis()
    {
        return httpClient.connectTimeoutMillis();
    }

    int readTimeoutMillis()
    {
        return httpClient.readTimeoutMillis();
    }

    int callTimeoutMillis()
    {
        return httpClient.callTimeoutMillis();
    }

    static String friendlyConnectionError(IOException exception)
    {
        Throwable cause = exception;
        while (cause != null)
        {
            if (cause instanceof UnknownHostException)
            {
                return "OpenAI could not be found (DNS). Check your connection, VPN, or DNS settings and try again.";
            }
            if (cause instanceof SocketTimeoutException)
            {
                return "The OpenAI connection timed out. Check your connection or VPN and try again.";
            }
            if (cause instanceof SSLException)
            {
                return "A secure connection to OpenAI could not be established (TLS). Check your system clock and security software.";
            }
            if (cause instanceof ConnectException)
            {
                return "The OpenAI connection was blocked or refused. Check your firewall, VPN, or security software and try again.";
            }
            cause = cause.getCause();
        }
        return "The OpenAI connection closed unexpectedly (network). Try again, then check your firewall, VPN, or security software.";
    }

    private String friendlyHttpError(int status, String body)
    {
        if (status == 401 || status == 403)
        {
            return "The OpenAI API key was not accepted. Check the key in RuneLite settings and try again.";
        }
        if (status == 429)
        {
            return "OpenAI is rate-limiting this key or its API credits are unavailable. Check your OpenAI Platform billing and try again shortly.";
        }
        if (status >= 500)
        {
            return "OpenAI is temporarily unavailable. Please try again shortly.";
        }
        try
        {
            JsonObject root = gson.fromJson(body, JsonObject.class);
            JsonObject error = root == null ? null : root.getAsJsonObject("error");
            String type = error == null || error.get("type") == null ? "" : error.get("type").getAsString();
            if ("invalid_request_error".equals(type))
            {
                return "OpenAI rejected the request. Check the configured model name and try again.";
            }
        }
        catch (RuntimeException ignored)
        {
            // Deliberately avoid surfacing raw server responses, which can be technical or sensitive.
        }
        return "OpenAI could not answer that request (error " + status + "). Please try again.";
    }
}

package com.gielinorguide;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

public final class OpenAiResponseParser
{
    private final Gson gson;

    public OpenAiResponseParser(Gson gson)
    {
        this.gson = gson;
    }

    public String parse(String json)
    {
        JsonObject root;
        try
        {
            root = gson.fromJson(json, JsonObject.class);
        }
        catch (RuntimeException exception)
        {
            throw new IllegalArgumentException("OpenAI returned an unreadable response.", exception);
        }
        if (root == null)
        {
            throw new IllegalArgumentException("OpenAI returned an empty response.");
        }

        JsonObject error = objectValue(root.get("error"));
        if (error != null)
        {
            String message = stringValue(error.get("message"));
            throw new IllegalArgumentException(message.isEmpty() ? "OpenAI rejected the request." : message);
        }

        StringBuilder text = new StringBuilder();
        append(text, stringValue(root.get("output_text")));

        JsonArray output = arrayValue(root.get("output"));
        if (output != null)
        {
            for (JsonElement itemElement : output)
            {
                JsonObject item = objectValue(itemElement);
                if (item == null)
                {
                    continue;
                }
                if (!"message".equals(stringValue(item.get("type"))))
                {
                    continue;
                }
                JsonArray content = arrayValue(item.get("content"));
                if (content == null)
                {
                    continue;
                }
                for (JsonElement contentElement : content)
                {
                    JsonObject part = objectValue(contentElement);
                    if (part == null)
                    {
                        continue;
                    }
                    String type = stringValue(part.get("type"));
                    if ("output_text".equals(type))
                    {
                        append(text, stringValue(part.get("text")));
                    }
                    else if ("refusal".equals(type))
                    {
                        append(text, stringValue(part.get("refusal")));
                    }
                }
            }
        }

        if (text.length() == 0)
        {
            throw new IllegalArgumentException("OpenAI returned no readable answer.");
        }
        return text.toString();
    }

    private static void append(StringBuilder target, String value)
    {
        if (value.isEmpty())
        {
            return;
        }
        if (target.length() > 0)
        {
            target.append('\n');
        }
        target.append(value);
    }

    private static String stringValue(JsonElement element)
    {
        return element == null || element.isJsonNull() || !element.isJsonPrimitive()
            ? "" : element.getAsString();
    }

    private static JsonObject objectValue(JsonElement element)
    {
        return element != null && element.isJsonObject() ? element.getAsJsonObject() : null;
    }

    private static JsonArray arrayValue(JsonElement element)
    {
        return element != null && element.isJsonArray() ? element.getAsJsonArray() : null;
    }
}

package com.gielinorguide;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.IntUnaryOperator;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;

public final class PlayerContextProvider
{
    private static final DiaryTier[] ACHIEVEMENT_DIARY_TIERS = achievementDiaryTiers();

    private final Client client;
    private final ClientThread clientThread;
    private final GielinorGuideConfig config;
    private volatile String bankSummary;
    private volatile Map<String, Integer> bankItems;

    public PlayerContextProvider(Client client, ClientThread clientThread, GielinorGuideConfig config)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.config = config;
    }

    public void capture(Consumer<String> callback)
    {
        boolean all = config.shareAllContext();
        boolean location = all || config.shareLocation();
        boolean skills = all || config.shareSkills();
        boolean quests = all || config.shareCompletedQuests();
        boolean inventory = all || config.shareInventory();
        boolean equipment = all || config.shareEquipment();
        boolean bank = all || config.shareBank();

        if (!location && !skills && !quests && !inventory && !equipment && !bank)
        {
            callback.accept("No player context was shared.");
            return;
        }

        clientThread.invokeLater(() ->
        {
            StringBuilder context = new StringBuilder("Player context explicitly enabled in RuneLite settings:\n");
            if (location)
            {
                WorldPoint point = client.getLocalPlayer() == null ? null : client.getLocalPlayer().getWorldLocation();
                context.append("- Current location: ")
                    .append(point == null ? "unavailable" : point.getX() + ", " + point.getY() + ", plane " + point.getPlane())
                    .append('\n');
            }
            if (skills)
            {
                List<String> values = new ArrayList<>();
                for (Skill skill : Skill.values())
                {
                    values.add(skill.getName() + " " + client.getRealSkillLevel(skill) +
                        " (" + client.getSkillExperience(skill) + " XP)");
                }
                context.append("- Real skill levels: ").append(String.join(", ", values)).append('\n');
                context.append("- Combat level: ")
                    .append(client.getLocalPlayer() == null
                        ? "unavailable" : client.getLocalPlayer().getCombatLevel())
                    .append('\n');
            }
            if (quests)
            {
                List<String> completed = new ArrayList<>();
                for (Quest quest : Quest.values())
                {
                    if (quest.getState(client) == QuestState.FINISHED)
                    {
                        completed.add(quest.getName());
                    }
                }
                context.append("- Completed quests (exhaustive; any quest absent from this list is not completed): ")
                    .append(completed.isEmpty() ? "none found" : String.join(", ", completed)).append('\n');
                context.append("- Completed achievement diary tiers (exhaustive; any tier absent from this list is not completed): ")
                    .append(completedAchievementDiaryTiers(client::getVarbitValue)).append('\n');
            }
            if (inventory)
            {
                context.append("- Inventory: ").append(summarizeContainer(InventoryID.INV)).append('\n');
            }
            if (equipment)
            {
                context.append("- Equipment: ").append(summarizeContainer(InventoryID.WORN)).append('\n');
            }
            if (bank)
            {
                ItemContainer currentBank = client.getItemContainer(InventoryID.BANK);
                if (currentBank != null)
                {
                    storeBankSnapshot(currentBank);
                }
                context.append("- Bank snapshot: ")
                    .append(bankSummary == null
                        ? "unavailable; open the bank once after enabling bank sharing"
                        : bankSummary)
                    .append('\n');
            }
            callback.accept(context.toString());
        });
    }

    public void captureSkillLevels(Consumer<Map<Skill, Integer>> callback)
    {
        clientThread.invokeLater(() ->
        {
            Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
            for (Skill skill : Skill.values())
            {
                levels.put(skill, client.getRealSkillLevel(skill));
            }
            callback.accept(levels);
        });
    }

    public void updateBankSnapshot(ItemContainer bank)
    {
        if (config.shareAllContext() || config.shareBank())
        {
            storeBankSnapshot(bank);
        }
    }

    public void clearBankSnapshot()
    {
        bankSummary = null;
        bankItems = null;
    }

    public boolean isBankSharingEnabled()
    {
        return config.shareAllContext() || config.shareBank();
    }

    public boolean hasBankSnapshot()
    {
        return bankItems != null;
    }

    private String summarizeContainer(int inventoryId)
    {
        ItemContainer container = client.getItemContainer(inventoryId);
        if (container == null)
        {
            return "unavailable";
        }
        return summarizeContainer(container);
    }

    private String summarizeContainer(ItemContainer container)
    {
        Map<String, Integer> counts = itemCounts(container);
        List<String> items = new ArrayList<>();
        for (Map.Entry<String, Integer> item : counts.entrySet())
        {
            items.add(item.getKey() + (item.getValue() == 1 ? "" : " x" + item.getValue()));
        }
        return items.isEmpty() ? "empty" : String.join(", ", items);
    }

    private Map<String, Integer> itemCounts(ItemContainer container)
    {
        Map<String, Integer> items = new LinkedHashMap<>();
        if (container == null)
        {
            return items;
        }
        for (Item item : container.getItems())
        {
            if (item.getId() >= 0 && item.getQuantity() > 0)
            {
                ItemComposition definition = client.getItemDefinition(item.getId());
                if (definition.getPlaceholderTemplateId() != -1)
                {
                    continue;
                }
                String name = definition.getName();
                if (name != null && !name.isEmpty() && !"null".equalsIgnoreCase(name))
                {
                    String normalized = name.toLowerCase(Locale.ENGLISH);
                    items.put(normalized, items.getOrDefault(normalized, 0) + item.getQuantity());
                }
            }
        }
        return items;
    }

    private void storeBankSnapshot(ItemContainer bank)
    {
        bankItems = immutableItemCounts(bank);
        bankSummary = summarizeCounts(bankItems);
    }

    private Map<String, Integer> immutableItemCounts(ItemContainer container)
    {
        return Collections.unmodifiableMap(new LinkedHashMap<>(itemCounts(container)));
    }

    private static String summarizeCounts(Map<String, Integer> counts)
    {
        List<String> items = new ArrayList<>();
        for (Map.Entry<String, Integer> item : counts.entrySet())
        {
            items.add(item.getKey() + (item.getValue() == 1 ? "" : " x" + item.getValue()));
        }
        return items.isEmpty() ? "empty" : String.join(", ", items);
    }

    private static DiaryTier[] achievementDiaryTiers()
    {
