    private static void addDiaryTiers(List<DiaryTier> tiers, String area,
        int easy, int medium, int hard, int elite)
    {
        tiers.add(new DiaryTier(area + " Easy", easy));
        tiers.add(new DiaryTier(area + " Medium", medium));
        tiers.add(new DiaryTier(area + " Hard", hard));
        tiers.add(new DiaryTier(area + " Elite", elite));
    }

    static String completedAchievementDiaryTiers(IntUnaryOperator varbitValue)
    {
        List<String> completed = new ArrayList<>();
        for (DiaryTier tier : ACHIEVEMENT_DIARY_TIERS)
        {
            if (varbitValue.applyAsInt(tier.varbitId) == 1)
            {
                completed.add(tier.name);
            }
        }
        return completed.isEmpty() ? "none found" : String.join(", ", completed);
    }

    private static final class DiaryTier
    {
        private final String name;
        private final int varbitId;

        private DiaryTier(String name, int varbitId)
        {
            this.name = name;
            this.varbitId = varbitId;
        }
    }
}

package com.gielinorguide;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Selects bounded training evidence for the player's missing quest skills. */
final class QuestPreparationPlanner
{
    private static final int MAX_TRAINING_GUIDES = 6;
    private static final String SKILLS =
        "Attack|Strength|Defence|Ranged|Prayer|Magic|Runecraft|Construction|" +
        "Hitpoints|Agility|Herblore|Thieving|Crafting|Fletching|Slayer|Hunter|" +
        "Mining|Smithing|Fishing|Cooking|Firemaking|Woodcutting|Farming|Sailing";
    private static final Pattern REQUIRED_SKILL = Pattern.compile(
        "(?im)^\\s*-\\s*(\\d{1,3})\\s+(" + SKILLS + ")\\b");
    private static final Pattern PLAYER_SKILL = Pattern.compile(
        "(?i)\\b(" + SKILLS + ")\\s+(\\d{1,3})\\s*\\(");

    private QuestPreparationPlanner()
    {
    }

    static List<String> missingTrainingPages(WikiResult wikiResult, String playerContext)
    {
        Map<String, Integer> levels = playerLevels(playerContext);
        List<String> pages = new ArrayList<>();
        if (levels.isEmpty() || wikiResult == null)
        {
            return pages;
        }
        for (WikiSource source : wikiResult.getSources())
        {
            if (!source.getTitle().endsWith(" - Requirements") &&
                !source.getTitle().matches(".* - (?:Easy|Medium|Hard|Elite) tasks"))
            {
                continue;
            }
            Matcher requirements = REQUIRED_SKILL.matcher(source.getExcerpt());
            while (requirements.find() && pages.size() < MAX_TRAINING_GUIDES)
            {
                String skill = requirements.group(2);
                int required = Integer.parseInt(requirements.group(1));
                if (levels.getOrDefault(normalize(skill), 1) < required)
                {
                    String page = skill + " training";
                    if (!pages.contains(page))
                    {
                        pages.add(page);
                    }
                }
            }
        }
        return pages;
    }

    private static Map<String, Integer> playerLevels(String playerContext)
    {
        Map<String, Integer> levels = new LinkedHashMap<>();
        Matcher skills = PLAYER_SKILL.matcher(playerContext == null ? "" : playerContext);
        while (skills.find())
        {
            levels.put(normalize(skills.group(1)), Integer.parseInt(skills.group(2)));
        }
        return levels;
    }

    private static String normalize(String value)
    {
        return value.toLowerCase(Locale.ENGLISH).replaceAll("[^a-z0-9]+", " ").trim();
    }
}

package com.gielinorguide;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.Locale;

final class SemanticWikiQuery
{
    enum Intent
    {
        ACQUISITION,
        PURPOSE,
        COMPARISON,
        QUEST,
        DIARY,
        TRAINING,
        GENERAL
    }

    private final String query;
    private final Intent intent;

    private SemanticWikiQuery(String query, Intent intent)
    {
        this.query = query;
        this.intent = intent;
    }

    static SemanticWikiQuery parse(Gson gson, String json)
    {
        JsonObject object = gson.fromJson(json, JsonObject.class);
        String query = object == null || !object.has("query")
            ? "" : object.get("query").getAsString().trim();
        String intent = object == null || !object.has("intent")
            ? "" : object.get("intent").getAsString().trim();
        if (query.isEmpty())
        {
            throw new IllegalArgumentException("Semantic Wiki query was empty.");
        }
        try
        {
            return new SemanticWikiQuery(query,
                Intent.valueOf(intent.toUpperCase(Locale.ENGLISH)));
        }
        catch (IllegalArgumentException exception)
        {
            return new SemanticWikiQuery(query, Intent.GENERAL);
        }
    }

    String getQuery()
    {
        return query;
    }

    Intent getIntent()
    {
        return intent;
    }
}

package com.gielinorguide;

final class SessionGroundingState
{
    private WikiResult recentWikiResult;

    synchronized void remember(WikiResult result)
    {
        if (result != null && result.isAvailable() && !result.getSources().isEmpty())
        {
            recentWikiResult = result;
        }
    }

    synchronized WikiResult forFollowUp(String question, boolean hasExplicitTarget)
    {
        return !hasExplicitTarget && WikiQueryPlanner.isReferentialFollowUp(question)
            ? recentWikiResult : null;
    }

    synchronized void clear()
    {
        recentWikiResult = null;
    }
}

package com.gielinorguide;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/** Prevents an incomplete model answer from discarding verified Slayer evidence. */
final class SlayerAnswerGuard
{
    private final LocationResolver locationResolver;

    SlayerAnswerGuard(LocationResolver locationResolver)
    {
        this.locationResolver = locationResolver;
    }

    Result enforce(String answer, String playerContext, WikiResult wikiResult,
        List<VerifiedLocation> verifiedDestinations)
    {
        return enforce("", answer, playerContext, wikiResult, verifiedDestinations);
    }

    Result enforce(String question, String answer, String playerContext,
        WikiResult wikiResult, List<VerifiedLocation> verifiedDestinations)
    {
        List<VerifiedLocation> availableDestinations =
            new ArrayList<>(verifiedDestinations);
        SlayerFacts facts = SlayerEvidenceParser.parse(playerContext, wikiResult, availableDestinations);
        applyReviewedFallback(facts, availableDestinations);
        if (isWeaknessQuestion(question))
        {
            return enforceFocusedWeakness(answer, facts);
        }
        applyAssignedAreaPreference(facts, availableDestinations);
        VerifiedLocation destination = selectDestination(facts.assignedArea,
            availableDestinations);
        List<VerifiedLocation> destinations = destination == null
            ? Collections.emptyList() : Collections.singletonList(destination);
        if (isComplete(answer, facts, destination))
        {
            return new Result(answer, destinations, false);
        }

        return new Result(fallback(facts, destination), destinations, true);
    }

    private static boolean isComplete(String answer, SlayerFacts facts,
        VerifiedLocation destination)
    {
        String normalized = normalize(answer);
        if (normalized.contains("couldn t verify") ||
            normalized.contains("could not verify") ||
            normalized.contains("won t guess") ||
            normalized.contains("will not guess"))
        {
            return false;
        }
        if (!hasActionableGuidance(normalized))
        {
            return false;
        }
        if (destination != null && !containsDestination(answer,
            Collections.singletonList(destination)))
        {
            return false;
        }
        if (destination == null && hasAssignedArea(facts.assignedArea) &&
            containsDestination(answer, facts.destinations))
        {
            return false;
        }
        if (!facts.attackStyle.isEmpty() &&
            !normalized.contains(normalize(facts.attackStyle)))
        {
            return false;
        }
        if (!facts.weakness.isEmpty() &&
            !normalized.contains(normalize(facts.weakness)))
        {
            return false;
        }
        if (facts.hasDefensiveStats() && !mentionsConventionalDefence(normalized))
        {
            return false;
        }
        if (facts.hasDefensiveStats() && facts.weakness.isEmpty() &&
            !mentionsNoElementalWeakness(normalized))
        {
            return false;
        }
        if (normalize(facts.beneficialGearSentence).contains("demonbane") &&
            !normalized.contains("demonbane"))
        {
            return false;
        }
        if (!facts.requiredItems.isEmpty() &&
            !containsAny(normalized, facts.requiredItems))
        {
            return false;
        }
        if (!facts.recommendedTarget.isEmpty() &&
            !normalized.contains(normalize(facts.recommendedTarget)))
        {
            return false;
        }
        if (!facts.targetRecommendationSentence.isEmpty() &&
            !hasTargetRationale(normalized))
        {
            return false;
        }
        if (destination == null && !facts.travelAnchor.isEmpty() &&
            !normalized.contains(normalize(facts.travelAnchor)))
        {
            return false;
        }
        if (destination == null && facts.travelAnchor.isEmpty() &&
            !facts.travelSentence.isEmpty() &&
            !hasTravelGuidance(normalized))
        {
            return false;
        }
        if (!facts.offensiveAnchors.isEmpty() &&
            !containsAny(normalized, facts.offensiveAnchors))
        {
            return false;
        }
        if (!facts.protectionPrayer.isEmpty() &&
            !normalized.contains(normalize(facts.protectionPrayer)))
        {
            return false;
        }
        if (facts.hasZeroDamageMetalDragonPlan &&
            (!normalized.contains("super antifire") ||
                !normalized.contains("regular antifire") ||
                !normalized.contains("protect from melee") ||
                !mentionsMeleePrayerPosition(normalized)))
        {
            return false;
        }
        if (!facts.xpPriorityVariant.isEmpty() &&
            normalized.contains(normalize(facts.xpPriorityVariant)))
        {
            return false;
        }
        if (!facts.cannonSentence.isEmpty() && !normalized.contains("cannon"))
        {
            return false;
        }
        return true;
    }

    private static Result enforceFocusedWeakness(String answer, SlayerFacts facts)
    {
        String normalized = normalize(answer);
        boolean refusal = normalized.contains("couldn t verify") ||
            normalized.contains("could not verify") || normalized.contains("won t guess") ||
            normalized.contains("will not guess");
        boolean complete = !refusal &&
            (!facts.hasDefensiveStats() || mentionsConventionalDefence(normalized)) &&
            (facts.weakness.isEmpty()
                ? !facts.hasDefensiveStats() || mentionsNoElementalWeakness(normalized)
                : normalized.contains(normalize(facts.weakness))) &&
            (!normalize(facts.beneficialGearSentence).contains("demonbane") ||
                normalized.contains("demonbane"));
        if (complete)
        {
            return new Result(answer, Collections.emptyList(), false);
        }
        return new Result(focusedWeaknessFallback(facts), Collections.emptyList(), true);
    }

    private static String focusedWeaknessFallback(SlayerFacts facts)
    {
        String subject = facts.task.isEmpty() ? "This monster" : facts.task;
        StringBuilder answer = new StringBuilder();
        if (normalize(facts.beneficialGearSentence).contains("demonbane"))
        {
            answer.append(subject).append(" are susceptible to demonbane, but that is an " +
                "optional specialty benefit rather than the only viable weapon choice.\n\n");
        }
        else
        {
            answer.append("Here are the verified offensive weakness stats for ")
                .append(subject).append(".\n\n");
        }
        if (facts.hasDefensiveStats())
        {
            answer.append("- Conventional defence: ")
                .append(conventionalDefenceSummary(facts)).append(".\n");
        }
        if (facts.weakness.isEmpty())
        {
            if (facts.hasDefensiveStats())
            {
                answer.append("- Elemental: The Wiki lists no elemental weakness.\n");
            }
        }
        else
        {
            answer.append("- Elemental: ").append(facts.weakness);
            if (!facts.weaknessBonus.isEmpty())
            {
                answer.append(" (").append(facts.weaknessBonus.replace("%", ""))
                    .append("%)");
            }
            answer.append(".\n");
        }
        if (!facts.beneficialGearSentence.isEmpty())
        {
            answer.append("- Specialty: ").append(facts.beneficialGearSentence);
            if (normalize(facts.beneficialGearSentence).contains("demonbane"))
            {
                answer.append(" Use it if you own a worthwhile option; otherwise use your " +
                    "strongest conventional setup.");
            }
            answer.append('\n');
        }
        if (facts.hasEqualStyleDefences())
        {
            answer.append("- Practical choice: Every listed attack-style defence bonus is ")
                .append(facts.stabDefence)
                .append(", so none gets a bonus-stat advantage; use the normal setup that " +
                    "gives you the best damage.");
        }
        return answer.toString().trim();
    }

    private static boolean isWeaknessQuestion(String question)
    {
        String normalized = normalize(question);
        return normalized.matches(".*\\bweak(?:ness|nesses)?\\b.*") ||
            normalized.matches(".*\\bweak to\\b.*") ||
            normalized.matches(".*\\b(?:defence|defense) (?:stat|stats|bonus|bonuses)\\b.*") ||
            normalized.matches(".*\\b(?:best|which|what) (?:attack )?style\\b.*");
    }

    private static boolean mentionsConventionalDefence(String normalizedAnswer)
    {
        return (normalizedAnswer.contains("defence") || normalizedAnswer.contains("defense")) &&
            (normalizedAnswer.contains("stab") || normalizedAnswer.contains("slash") ||
                normalizedAnswer.contains("crush") || normalizedAnswer.contains("ranged") ||
                normalizedAnswer.contains("magic level"));
    }

    private static boolean mentionsNoElementalWeakness(String normalizedAnswer)
    {
        return normalizedAnswer.contains("no elemental weakness") ||
            normalizedAnswer.contains("doesn t have an elemental weakness") ||
            normalizedAnswer.contains("does not have an elemental weakness") ||
            normalizedAnswer.contains("without an elemental weakness");
    }

    private static String conventionalDefenceSummary(SlayerFacts facts)
    {
        List<String> values = new ArrayList<>();
        addStat(values, "Defence level", facts.defenceLevel);
        addStat(values, "Magic level", facts.magicLevel);
        addStat(values, "stab", facts.stabDefence);
        addStat(values, "slash", facts.slashDefence);
        addStat(values, "crush", facts.crushDefence);
        addStat(values, "magic", facts.magicDefence);
        addStat(values, "light ranged", facts.lightRangedDefence);
        addStat(values, "standard ranged", facts.standardRangedDefence);
        addStat(values, "heavy ranged", facts.heavyRangedDefence);
        return String.join(", ", values);
    }

    private static void addStat(List<String> values, String label, String value)
    {
        if (!value.isEmpty())
        {
            values.add(label + " " + value);
        }
    }

    private String fallback(SlayerFacts facts, VerifiedLocation destination)
    {
        StringBuilder answer = new StringBuilder();
        boolean hasGuidance = false;
        if (!facts.remaining.isEmpty() && !facts.task.isEmpty())
        {
            answer.append("You have ").append(facts.remaining).append(' ')
                .append(facts.task).append(" remaining");
            if (!facts.assignedArea.isEmpty() &&
                !facts.assignedArea.toLowerCase(Locale.ENGLISH).startsWith("none"))
            {
                answer.append(", restricted to ").append(facts.assignedArea);
            }
            answer.append(".\n\n");
        }

        if (!facts.targetRecommendationSentence.isEmpty())
        {
            hasGuidance = true;
            answer.append("- Fast task / points: Kill ")
                .append(facts.recommendedTarget);
            if (destination != null)
            {
                answer.append(" at ").append(destination.getName());
            }
            answer.append(". This is the Wiki's fast-completion recommendation.\n");
        }

        if (!facts.offensiveStyleSentence.isEmpty() || !facts.weakness.isEmpty() ||
            facts.hasDefensiveStats())
        {
            hasGuidance = true;
            answer.append("- Offense: ");
            if (!facts.offensiveStyleSentence.isEmpty())
            {
                answer.append(facts.offensiveStyleSentence).append(' ');
            }
            if (!facts.weakness.isEmpty())
            {
                answer.append("Elemental weakness: ").append(facts.weakness);
                if (!facts.weaknessBonus.isEmpty())
                {
                    answer.append(" (").append(facts.weaknessBonus.replace("%", ""))
                        .append("%)");
                }
                answer.append(". Use that element's spells if choosing Magic; a powered " +
                    "staff does not automatically trigger an elemental weakness.");
            }
            if (facts.hasDefensiveStats())
            {
                if (answer.charAt(answer.length() - 1) != ' ')
                {
                    answer.append(' ');
                }
                answer.append("Conventional defence stats: ")
                    .append(conventionalDefenceSummary(facts)).append('.');
                if (facts.weakness.isEmpty())
                {
                    answer.append(" The Wiki lists no elemental weakness.");
                }
                if (facts.hasEqualStyleDefences())
                {
                    answer.append(" The listed attack-style bonuses are tied, so use your " +
                        "strongest normal damage setup if you are not using specialty gear.");
                }
            }
            answer.append('\n');
        }
        if (!facts.beneficialGearSentence.isEmpty())
        {
            hasGuidance = true;
            answer.append("- Useful gear: ").append(facts.beneficialGearSentence).append('\n');
        }
        if (!facts.cannonSentence.isEmpty())
        {
            hasGuidance = true;
            answer.append("- Task setup: ").append(facts.assignedArea)
                .append(" allows a dwarf multicannon. ");
            if (!facts.cannonballCount.isEmpty())
            {
                answer.append("Your shared item context lists ")
                    .append(facts.cannonballCount).append(" steel cannonballs; ");
            }
            answer.append("bring the cannon parts and cannonballs for faster task completion.\n");
        }

        if (!facts.attackStyle.isEmpty() || !facts.requiredSentence.isEmpty() ||
            !facts.protectionPrayerSentence.isEmpty())
        {
            hasGuidance = true;
            answer.append("- Defence: ");
            if (!facts.attackStyle.isEmpty())
            {
                answer.append("They attack with ").append(facts.attackStyle).append(". ");
            }
            if (facts.hasZeroDamageMetalDragonPlan)
            {
                answer.append("Best if available: use a super antifire potion by itself " +
                    "and stay outside melee range; this zero-damage ranged or Magic setup " +
                    "gives full metallic-dragonfire protection and frees the shield slot " +
                    "for offensive gear. The cheaper full-protection alternative is an " +
                    "anti-dragon shield plus a regular antifire potion. If you fight in " +
                    "melee range instead, keep either full dragonfire setup active and use " +
                    "Protect from Melee to block the melee hits. Protect from Magic does " +
                    "not reduce metallic dragonfire. ");
            }
            if (!facts.requiredSentence.isEmpty())
            {
                String equipped = equippedRequiredItem(facts.equipment, facts.requiredItems);
                if (!equipped.isEmpty())
                {
                    answer.append("Your ").append(equipped).append(" is already equipped. ");
                }
                answer.append(facts.requiredSentence);
            }
            if (!facts.hasZeroDamageMetalDragonPlan &&
                !facts.protectionPrayerSentence.isEmpty() &&
                !normalize(facts.requiredSentence).contains(
                    normalize(facts.protectionPrayerSentence)))
            {
                answer.append(' ').append(facts.protectionPrayerSentence);
            }
            else if (!facts.hasZeroDamageMetalDragonPlan &&
                facts.protectionPrayerSentence.isEmpty() &&
                normalize(facts.attackStyle).contains("slash"))
            {
                answer.append(" Stay at range to avoid their melee attack; use Protect from " +
                    "Melee only if fighting next to them.");
            }
            answer.append('\n');
        }

        if (destination != null)
        {
            hasGuidance = true;
            if (!destination.getRouteWorldPoint().equals(destination.getWorldPoint()))
            {
                answer.append("- Route: Shortest Path routes to the verified entrance first, " +
                    "then retargets ").append(destination.getName())
                    .append(" after you enter.\n");
            }
            else
            {
                answer.append("- Route: Shortest Path handles navigation to ")
                    .append(destination.getName()).append("; the route target ")
                    .append(destination.getGuidance().contains("final objective")
                        ? "is a verified monster spawn inside.\n"
                        : "is the verified assignment location.\n");
            }
            if (!facts.routeInstruction.isEmpty())
            {
                answer.append("- Inside route: ").append(facts.routeInstruction).append('\n');
            }
        }
        else if (!facts.locationSentence.isEmpty())
        {
            hasGuidance = true;
            answer.append("- Location: ").append(facts.locationSentence).append('\n');
        }
        if (destination == null && !facts.travelSentence.isEmpty())
        {
            hasGuidance = true;
            answer.append("- Getting there: ").append(facts.travelSentence).append('\n');
        }
        if (!facts.riskSentence.isEmpty())
        {
            hasGuidance = true;
            answer.append("- Risk: ").append(facts.riskSentence).append('\n');
        }
        String accessSummary = conciseAccessSummary(facts);
        if (!accessSummary.isEmpty())
        {
            hasGuidance = true;
            answer.append("- Conditional access: ").append(accessSummary).append('\n');
        }
        if (!facts.combatAdviceSentence.isEmpty() &&
            !normalize(facts.combatAdviceSentence).equals(
                normalize(facts.offensiveStyleSentence)))
        {
            hasGuidance = true;
            answer.append("- Combat option: ").append(facts.combatAdviceSentence).append('\n');
        }
        if (!facts.usefulSupplySentence.isEmpty())
        {
            hasGuidance = true;
            answer.append("- Useful supplies: ").append(facts.usefulSupplySentence).append('\n');
        }
        if (!hasGuidance)
        {
            answer.append("I couldn't load actionable guidance from the OSRS Wiki for this task. " +
                "Try again; the task count alone is not a complete answer.");
        }
        return answer.toString().trim();
    }

    private static void applyAssignedAreaPreference(SlayerFacts facts,
        List<VerifiedLocation> destinations)
    {
        String normalizedArea = normalize(facts.assignedArea);
        if (normalizedArea.isEmpty() || normalizedArea.startsWith("none"))
        {
            return;
        }
        String assignedId = "";
        for (VerifiedLocation destination : destinations)
        {
            if (matchesAssignedArea(normalizedArea, destination))
            {
                assignedId = destination.getId();
                break;
            }
        }
        if (!assignedId.isEmpty())
        {
            promoteDestination(destinations, assignedId);
            facts.routeInstruction = "";
        }
    }

    private void applyReviewedFallback(SlayerFacts facts,
        List<VerifiedLocation> availableDestinations)
    {
        if (!"aberrant spectres".equals(normalize(facts.task)))
        {
            return;
        }
        if (facts.attackStyle.isEmpty())
        {
            facts.attackStyle = "Magic";
        }
        if (facts.weakness.isEmpty())
        {
            facts.weakness = "Air";
        }
        if (facts.weaknessBonus.isEmpty())
        {
            facts.weaknessBonus = "50";
        }
        if (facts.requiredItems.isEmpty())
        {
            facts.requiredItems.add("nose peg");
            facts.requiredItems.add("Slayer helmet");
        }
        if (facts.requiredSentence.isEmpty())
        {
            facts.requiredSentence =
                "A nose peg or Slayer helmet is required to prevent their stat-draining special attack.";
        }
        if (facts.protectionPrayerSentence.isEmpty())
        {
            facts.protectionPrayerSentence =
                "Use Protect from Magic against their normal attacks.";
            facts.protectionPrayer = "Protect from Magic";
        }
        if (facts.usefulSupplySentence.isEmpty())
        {
            facts.usefulSupplySentence =
                "Bring food and enough prayer restoration for the remaining kills; a herb sack and seed box help with their frequent drops.";
        }
        addDestinationIfMissing(availableDestinations,
            locationResolver.byId("slayer-tower"));
        addDestinationIfMissing(availableDestinations,
            locationResolver.byId("stronghold-slayer-cave"));
        promoteDestination(availableDestinations, "slayer-tower");
        facts.routeInstruction =
            "From Canifis, go north-west to Slayer Tower. Enter on the ground floor, then climb the 61 Agility spiked chain to the aberrant spectres on the 1st floor (UK), called the 2nd floor in US numbering.";
    }

    private static void addDestinationIfMissing(List<VerifiedLocation> destinations,
        VerifiedLocation addition)
    {
        if (addition == null)
        {
            return;
        }
        for (VerifiedLocation destination : destinations)
        {
            if (destination.getId().equals(addition.getId()))
            {
                return;
            }
        }
        destinations.add(addition);
    }

    private static void promoteDestination(List<VerifiedLocation> destinations, String id)
    {
        for (int i = 0; i < destinations.size(); i++)
        {
            if (id.equals(destinations.get(i).getId()))
            {
                VerifiedLocation preferred = destinations.remove(i);
                destinations.add(0, preferred);
                return;
            }
        }
    }

    private static boolean mentionsMeleePrayerPosition(String normalizedAnswer)
    {
        return normalizedAnswer.contains("melee range") ||
            normalizedAnswer.contains("outside melee") ||
            normalizedAnswer.contains("stay at range") ||
            normalizedAnswer.contains("staying at range") ||
            normalizedAnswer.contains("from range");
    }

    private static boolean isCannonSentence(String normalizedSentence)
    {
        return normalizedSentence.contains("allows for a cannon") ||
            normalizedSentence.contains("cannon may be used") ||
            normalizedSentence.contains("multicannon can be used") ||
            normalizedSentence.contains("allows a cannon");
    }

    private static boolean hasActionableGuidance(String normalizedAnswer)
    {
        if (normalizedAnswer.split(" ").length < 12)
        {
            return false;
        }
        return normalizedAnswer.matches(".*\\b(?:go|use|bring|wear|kill|fight|attack|weakness|" +
            "location|found|safespot|wilderness|teleport|prayer|gear|route|protect)\\b.*");
    }

    private static boolean hasTravelGuidance(String normalizedAnswer)
    {
        return normalizedAnswer.matches(".*\\b(?:travel|route|teleport|fairy ring|walk|run|" +
            "shortest path|ship)\\b.*");
    }

    private static boolean hasTargetRationale(String normalizedAnswer)
    {
        return normalizedAnswer.matches(".*\\b(?:fast|quick|easy|weak|combat level|xp|" +
            "experience|kill speed|cannonable)\\b.*");
    }

    private static boolean hasAssignedArea(String assignedArea)
    {
        String normalizedArea = normalize(assignedArea);
        return !normalizedArea.isEmpty() && !normalizedArea.startsWith("none");
    }

    private static VerifiedLocation selectDestination(String assignedArea,
        List<VerifiedLocation> destinations)
    {
        if (destinations.isEmpty())
        {
            return null;
        }
        String normalizedArea = normalize(assignedArea);
        if (!normalizedArea.isEmpty() && !normalizedArea.startsWith("none"))
        {
            for (VerifiedLocation destination : destinations)
            {
                if (matchesAssignedArea(normalizedArea, destination))
                {
                    return destination;
                }
            }
            return null;
        }
        return destinations.get(0);
    }

    private static boolean matchesAssignedArea(String normalizedArea,
        VerifiedLocation destination)
    {
        if (containsNormalizedPhrase(normalizedArea, normalize(destination.getName())) ||
            containsNormalizedPhrase(normalize(destination.getName()), normalizedArea))
        {
            return true;
        }
        for (String alias : destination.getAliases())
        {
            if (containsNormalizedPhrase(normalizedArea, normalize(alias)) ||
                containsNormalizedPhrase(normalize(alias), normalizedArea))
            {
                return true;
            }
        }
        return false;
    }

    private static boolean containsNormalizedPhrase(String value, String phrase)
    {
        return !phrase.isEmpty() && (" " + value + " ").contains(" " + phrase + " ");
    }

    private static boolean containsDestination(String answer,
        List<VerifiedLocation> destinations)
    {
        String normalized = normalize(answer);
        for (VerifiedLocation destination : destinations)
        {
            if (normalized.contains(normalize(destination.getName())))
            {
                return true;
            }
        }
        return false;
    }

    private static boolean containsAny(String text, List<String> values)
    {
        for (String value : values)
        {
            if (text.contains(normalize(value)))
            {
                return true;
            }
        }
        return false;
    }

    private static String conciseAccessSummary(SlayerFacts facts)
    {
        if (facts.accessSentences.isEmpty())
        {
            return "";
        }
        if (containsAny("axe", facts.accessAnchors))
        {
            String fee = "";
            for (String anchor : facts.accessAnchors)
            {
                if (anchor.matches("[0-9][0-9,]*"))
                {
                    fee = anchor;
                    break;
                }
            }
            return "If Shortest Path uses the north entrance, bring an axe" +
                (fee.isEmpty() ? "." : " and " + fee + " coins.");
        }
        return facts.accessSentences.get(0);
    }

    private static String equippedRequiredItem(String equipment, List<String> requiredItems)
    {
        String normalizedEquipment = normalize(equipment);
        for (String item : requiredItems)
        {
            if (normalizedEquipment.contains(normalize(item)))
            {
                return item;
            }
        }
        return "";
    }

    private static String normalize(String value)
    {
        return value == null ? "" : value.toLowerCase(Locale.ENGLISH)
            .replace('\u2019', '\'').replaceAll("[^a-z0-9%]+", " ").trim();
    }

    static final class Result
    {
        private final String answer;
        private final List<VerifiedLocation> destinations;
        private final boolean replaced;

        Result(String answer, List<VerifiedLocation> destinations, boolean replaced)
        {
            this.answer = answer;
            this.destinations = destinations;
            this.replaced = replaced;
        }

        String getAnswer()
        {
            return answer;
        }

        List<VerifiedLocation> getDestinations()
        {
            return destinations;
        }

        boolean wasReplaced()
        {
            return replaced;
        }
    }
}

package com.gielinorguide;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Converts trusted task context and Wiki excerpts into typed Slayer facts. */
final class SlayerEvidenceParser
{
    private static final Pattern CONTEXT_FIELD = Pattern.compile(
        "(?im)^-\\s*(Task|Remaining|Assigned area|Equipment):\\s*(.+)$");
    private static final Pattern EVIDENCE_FIELD = Pattern.compile(
        "(?im)^-\\s*(attack style|attributes|elemental weakness|" +
            "elemental weakness bonus|Defence level|Magic level|stab defence|" +
            "slash defence|crush defence|magic defence|light ranged defence|" +
            "standard ranged defence|heavy ranged defence):\\s*(.+)$");
    private static final Pattern REQUIRED_ITEMS = Pattern.compile(
        "(?i)\\b(?:an?\\s+)?([a-z][a-z '()-]{1,35}(?:\\s+or\\s+[a-z][a-z '()-]{1,35})?)\\s+is required\\b");
    private static final Pattern MANDATORY_ALTERNATIVES = Pattern.compile(
        "(?i)\\bmaking\\s+(?:an?\\s+)?([a-z][a-z '()-]{1,35}?)\\s+mandatory\\s+" +
            "if\\s+not\\s+using\\s+(?:an?\\s+)?([a-z][a-z '()-]{1,35}?)(?=[.,;]|$)");
    private static final Pattern RECOMMENDED_TARGET = Pattern.compile(
        "(?i)\\brecommended to (?:kill|fight|attack)\\s+(?:an?\\s+)?" +
            "([a-z][a-z '-]{1,45}?)(?=\\s+(?:at|in|inside|for|because|with|using)\\b|[.,;]|$)");
    private static final Pattern FAIRY_RING_CODE = Pattern.compile(
        "(?i)\\bfairy ring(?: code)?\\s+([a-z]{3})\\b");
    private static final Pattern PROTECTION_PRAYER = Pattern.compile(
        "(?i)\\bProtect from (Melee|Magic|Missiles)\\b");
    private static final Pattern LEVEL_VARIANT = Pattern.compile(
        "(?i)\\blevel\\s+([0-9]+)\\b");
    private static final Pattern CANNONBALL_COUNT = Pattern.compile(
        "(?i)\\b(?:steel\\s+)?cannonballs?\\s+x?([0-9][0-9,]*)\\b");
    private static final Pattern NUMBER = Pattern.compile("\\b[0-9][0-9,]*\\b");

    private SlayerEvidenceParser()
    {
    }

    static SlayerFacts parse(String playerContext, WikiResult wikiResult,
        List<VerifiedLocation> destinations)
    {
        SlayerFacts facts = new SlayerFacts(destinations);
        parsePlayerContext(playerContext, facts);
        String grounding = wikiResult == null ? "" : wikiResult.asGroundingText();
        parseEvidenceFields(grounding, facts);
        parseEvidenceSentences(grounding, facts);
        String normalizedGrounding = normalize(grounding);
        facts.hasZeroDamageMetalDragonPlan =
            normalize(facts.task).contains("metal dragons") &&
                normalize(facts.recommendedTarget).contains("bronze dragon") &&
                normalizedGrounding.contains("super antifire") &&
                normalizedGrounding.contains("complete protection") &&
                normalizedGrounding.contains("all damage") &&
                normalizedGrounding.contains("anti dragon shield") &&
                normalizedGrounding.contains("antifire potion");
        return facts;
    }

    private static void parsePlayerContext(String playerContext, SlayerFacts facts)
    {
        String contextText = playerContext == null ? "" : playerContext;
        Matcher context = CONTEXT_FIELD.matcher(contextText);
        while (context.find())
        {
            String name = context.group(1).toLowerCase(Locale.ENGLISH);
            String value = context.group(2).trim();
            if ("task".equals(name))
            {
                facts.task = value;
            }
            else if ("remaining".equals(name))
            {
                facts.remaining = value;
            }
            else if ("assigned area".equals(name))
            {
                facts.assignedArea = value;
            }
            else if ("equipment".equals(name))
            {
                facts.equipment = value;
            }
        }
        Matcher cannonballs = CANNONBALL_COUNT.matcher(contextText);
        if (cannonballs.find())
        {
            facts.cannonballCount = cannonballs.group(1);
        }
    }

    private static void parseEvidenceFields(String grounding, SlayerFacts facts)
    {
        Matcher evidence = EVIDENCE_FIELD.matcher(grounding);
        while (evidence.find())
        {
            String name = evidence.group(1).toLowerCase(Locale.ENGLISH);
            String value = evidence.group(2).trim();
            if ("attack style".equals(name))
            {
                facts.attackStyle = value;
            }
            else if ("elemental weakness".equals(name))
            {
                facts.weakness = value;
            }
            else if ("elemental weakness bonus".equals(name))
            {
                facts.weaknessBonus = value;
            }
            else if ("attributes".equals(name))
            {
                facts.attributes = value;
            }
            else if ("defence level".equals(name))
            {
                facts.defenceLevel = value;
            }
            else if ("magic level".equals(name))
            {
                facts.magicLevel = value;
            }
            else if ("stab defence".equals(name))
            {
                facts.stabDefence = value;
            }
            else if ("slash defence".equals(name))
            {
                facts.slashDefence = value;
            }
            else if ("crush defence".equals(name))
            {
                facts.crushDefence = value;
            }
            else if ("magic defence".equals(name))
            {
                facts.magicDefence = value;
            }
            else if ("light ranged defence".equals(name))
            {
                facts.lightRangedDefence = value;
            }
            else if ("standard ranged defence".equals(name))
            {
                facts.standardRangedDefence = value;
            }
            else if ("heavy ranged defence".equals(name))
            {
                facts.heavyRangedDefence = value;
            }
        }
    }

    private static void parseEvidenceSentences(String grounding, SlayerFacts facts)
    {
        for (String sentence : sentences(grounding))
        {
            parseSentence(sentence, facts);
        }
    }

    private static void parseSentence(String sentence, SlayerFacts facts)
    {
        String lower = normalize(sentence);
        parseRequiredItems(sentence, lower, facts);
        parseTargetRecommendation(sentence, facts);
        parseProtectionPrayer(sentence, lower, facts);
        parseUtilityAndLocation(sentence, lower, facts);
        parseAccess(sentence, lower, facts);
        parseTravel(sentence, lower, facts);
        parseOffence(sentence, lower, facts);
        parseCannonAndVariant(sentence, lower, facts);
    }

    private static void parseRequiredItems(String sentence, String lower, SlayerFacts facts)
    {
        if (!facts.requiredSentence.isEmpty() ||
            (!lower.contains(" is required") && !lower.contains(" mandatory")))
        {
            return;
        }
        facts.requiredSentence = sentence;
        Matcher required = REQUIRED_ITEMS.matcher(sentence);
        if (required.find())
        {
            String items = required.group(1).replaceFirst("(?i)^an?\\s+", "");
            for (String item : items.split("(?i)\\s+or\\s+"))
            {
                facts.requiredItems.add(item.trim());
            }
            return;
        }
        Matcher alternatives = MANDATORY_ALTERNATIVES.matcher(sentence);
        if (alternatives.find())
        {
            facts.requiredItems.add(alternatives.group(1).trim());
            facts.requiredItems.add(alternatives.group(2).trim());
        }
    }

    private static void parseTargetRecommendation(String sentence, SlayerFacts facts)
    {
        if (!facts.targetRecommendationSentence.isEmpty())
        {
            return;
        }
        Matcher recommendation = RECOMMENDED_TARGET.matcher(sentence);
        if (recommendation.find())
        {
            facts.targetRecommendationSentence = sentence;
            facts.recommendedTarget = recommendation.group(1).trim();
        }
    }

    private static void parseProtectionPrayer(String sentence, String lower, SlayerFacts facts)
    {
        if (!facts.protectionPrayerSentence.isEmpty() || !isPositiveProtectionPrayer(lower))
        {
            return;
        }
        facts.protectionPrayerSentence = sentence;
        Matcher prayer = PROTECTION_PRAYER.matcher(sentence);
        if (prayer.find())
        {
            facts.protectionPrayer = prayer.group();
        }
    }

    private static void parseUtilityAndLocation(String sentence, String lower,
        SlayerFacts facts)
    {
        if (facts.usefulSupplySentence.isEmpty() &&
            (lower.contains("herb sack") || lower.contains("seed box") ||
                lower.contains("emergency teleport") || lower.contains("bring food")))
        {
            facts.usefulSupplySentence = sentence;
        }
        if (facts.locationSentence.isEmpty() &&
            (lower.contains(" found in ") || lower.contains(" located in ") ||
                lower.startsWith("found in ") || lower.startsWith("located in ")))
        {
            facts.locationSentence = sentence;
        }
        if (facts.riskSentence.isEmpty() &&
            (lower.contains(" wilderness") || lower.contains("player killer")))
        {
            facts.riskSentence = sentence;
        }
    }

    private static void parseAccess(String sentence, String lower, SlayerFacts facts)
    {
        boolean access = lower.contains("monkey bars") ||
            lower.contains("requires") && lower.contains("agility") ||
            lower.contains("needed if entering") || lower.contains("entry fee") ||
            lower.contains("coins entry") || lower.contains("one time fee");
        if (facts.accessSentences.size() >= 2 || !access)
        {
            return;
        }
        addSentenceIfMissing(facts.accessSentences, sentence, 2);
        addAnchorIfPresent(facts.accessAnchors, lower, "axe");
        addAnchorIfPresent(facts.accessAnchors, lower, "monkey bars");
        addAnchorIfPresent(facts.accessAnchors, lower, "agility");
        if (lower.contains("coins entry"))
        {
            Matcher amount = NUMBER.matcher(sentence);
            if (amount.find())
            {
                addValueIfMissing(facts.accessAnchors, amount.group());
            }
        }
    }

    private static void parseTravel(String sentence, String lower, SlayerFacts facts)
    {
        if (!facts.travelSentence.isEmpty() ||
            !(lower.contains("fairy ring") || lower.contains("teleport to") ||
                lower.startsWith("teleport") || lower.contains(" ship to ") ||
                lower.contains(" walk to ") || lower.contains(" run to ")))
        {
            return;
        }
        facts.travelSentence = sentence;
        Matcher fairyRing = FAIRY_RING_CODE.matcher(sentence);
        if (fairyRing.find())
        {
            facts.travelAnchor = fairyRing.group(1);
        }
    }

    private static void parseOffence(String sentence, String lower, SlayerFacts facts)
    {
        if (facts.offensiveStyleSentence.isEmpty() && !lower.contains("protect from") &&
            (lower.contains("weakest to") || lower.contains("weak against") ||
                lower.contains("recommended to use") &&
                    (lower.contains("weapon") || lower.contains("magic") ||
                        lower.contains("ranged") || lower.contains("melee"))))
        {
            facts.offensiveStyleSentence = sentence;
            addOffensiveAnchors(facts.offensiveAnchors, lower);
        }
        if (facts.beneficialGearSentence.isEmpty() && lower.contains("susceptible to") &&
            (lower.contains("weapon") || lower.contains("dragon hunter")))
        {
            facts.beneficialGearSentence = sentence;
            addOffensiveAnchors(facts.offensiveAnchors, lower);
        }
        if (facts.combatAdviceSentence.isEmpty() && lower.contains("recommended to use") &&
            (lower.contains("weapon") || lower.contains("magic")))
        {
            facts.combatAdviceSentence = sentence;
        }
    }

    private static void parseCannonAndVariant(String sentence, String lower,
        SlayerFacts facts)
    {
        if (isCannonSentence(lower) &&
            (facts.cannonSentence.isEmpty() ||
                containsNormalizedPhrase(lower, normalize(facts.assignedArea))))
        {
            facts.cannonSentence = sentence;
        }
        if (facts.xpPriorityVariant.isEmpty() &&
            (lower.contains("maximum xp") || lower.contains("more xp") ||
                lower.contains("better xp") || lower.contains("xp per kill")))
        {
            Matcher variant = LEVEL_VARIANT.matcher(sentence);
            if (variant.find())
            {
                facts.xpPriorityVariant = "level " + variant.group(1);
            }
        }
    }

    private static boolean isPositiveProtectionPrayer(String sentence)
    {
        if (!sentence.contains("protect from"))
        {
            return false;
        }
        return !sentence.contains("does not") && !sentence.contains("doesn t") &&
            !sentence.contains("will not") && !sentence.contains("won t") &&
            !sentence.contains("cannot") && !sentence.contains("can t") &&
            !sentence.contains("not affected") && !sentence.contains("aren t affected") &&
            !sentence.contains("no effect");
    }

    private static boolean isCannonSentence(String sentence)
    {
        return sentence.contains("allows for a cannon") ||
            sentence.contains("cannon may be used") ||
            sentence.contains("multicannon can be used") ||
            sentence.contains("allows a cannon");
    }

    private static List<String> sentences(String text)
    {
        List<String> sentences = new ArrayList<>();
        for (String value : text.split("(?<=[.!?])\\s+|\\r?\\n"))
        {
            String sentence = value.replaceFirst("^EXCERPT:\\s*", "")
                .replaceFirst("^[-*]\\s*", "").trim();
            if (sentence.length() >= 12 && sentence.length() <= 350 &&
                !sentence.startsWith("SOURCE:") && !sentence.startsWith("URL:"))
            {
                sentences.add(sentence);
            }
        }
        return sentences;
    }

    private static void addSentenceIfMissing(List<String> sentences, String addition, int limit)
    {
        String normalizedAddition = normalize(addition);
        for (String sentence : sentences)
        {
            if (normalize(sentence).equals(normalizedAddition))
            {
                return;
            }
        }
        if (sentences.size() < limit)
        {
            sentences.add(addition);
        }
    }

    private static void addAnchorIfPresent(List<String> anchors, String text, String anchor)
    {
        if (text.contains(anchor))
        {
            addValueIfMissing(anchors, anchor);
        }
    }

    private static void addValueIfMissing(List<String> values, String addition)
    {
        String normalizedAddition = normalize(addition);
        for (String value : values)
        {
            if (normalizedAddition.contains(normalize(value)))
            {
                return;
            }
        }
        values.add(addition);
    }

    private static void addOffensiveAnchors(List<String> anchors, String sentence)
    {
        for (String candidate : new String[]{
            "stab", "heavy ranged", "crush", "slash", "magic", "dragon hunter"})
        {
            addAnchorIfPresent(anchors, sentence, candidate);
        }
    }

    private static boolean containsNormalizedPhrase(String value, String phrase)
    {
        return !phrase.isEmpty() && (" " + value + " ").contains(" " + phrase + " ");
    }

    private static String normalize(String value)
    {
        return value == null ? "" : value.toLowerCase(Locale.ENGLISH)
            .replaceAll("[^a-z0-9]+", " ").trim();
    }
}

