/** Parsed player and Wiki evidence used by the Slayer answer policy. */
final class SlayerFacts
{
    final List<VerifiedLocation> destinations;
    final List<String> requiredItems = new ArrayList<>();
    final List<String> accessSentences = new ArrayList<>();
    final List<String> accessAnchors = new ArrayList<>();
    final List<String> offensiveAnchors = new ArrayList<>();
    String task = "";
    String remaining = "";
    String assignedArea = "";
    String equipment = "";
    String attackStyle = "";
    String attributes = "";
    String weakness = "";
    String weaknessBonus = "";
    String defenceLevel = "";
    String magicLevel = "";
    String stabDefence = "";
    String slashDefence = "";
    String crushDefence = "";
    String magicDefence = "";
    String lightRangedDefence = "";
    String standardRangedDefence = "";
    String heavyRangedDefence = "";
    String requiredSentence = "";
    String protectionPrayerSentence = "";
    String protectionPrayer = "";
    boolean hasZeroDamageMetalDragonPlan;
    String xpPriorityVariant = "";
    String cannonSentence = "";
    String cannonballCount = "";
    String usefulSupplySentence = "";
    String routeInstruction = "";
    String locationSentence = "";
    String riskSentence = "";
    String combatAdviceSentence = "";
    String targetRecommendationSentence = "";
    String recommendedTarget = "";
    String travelSentence = "";
    String travelAnchor = "";
    String offensiveStyleSentence = "";
    String beneficialGearSentence = "";

    SlayerFacts(List<VerifiedLocation> destinations)
    {
        this.destinations = destinations;
    }

    boolean hasDefensiveStats()
    {
        return !defenceLevel.isEmpty() || !magicLevel.isEmpty() ||
            !stabDefence.isEmpty() || !slashDefence.isEmpty() ||
            !crushDefence.isEmpty() || !magicDefence.isEmpty() ||
            !lightRangedDefence.isEmpty() || !standardRangedDefence.isEmpty() ||
            !heavyRangedDefence.isEmpty();
    }

    boolean hasEqualStyleDefences()
    {
        if (stabDefence.isEmpty() || slashDefence.isEmpty() ||
            crushDefence.isEmpty() || magicDefence.isEmpty() ||
            lightRangedDefence.isEmpty() || standardRangedDefence.isEmpty() ||
            heavyRangedDefence.isEmpty())
        {
            return false;
        }
        String expected = normalize(stabDefence);
        return expected.equals(normalize(slashDefence)) &&
            expected.equals(normalize(crushDefence)) &&
            expected.equals(normalize(magicDefence)) &&
            expected.equals(normalize(lightRangedDefence)) &&
            expected.equals(normalize(standardRangedDefence)) &&
            expected.equals(normalize(heavyRangedDefence));
    }

    private static String normalize(String value)
    {
        return value == null ? "" : value.toLowerCase(Locale.ENGLISH)
            .replaceAll("[^a-z0-9]+", " ").trim();
    }
}

package com.gielinorguide;

import java.util.List;
import java.util.Locale;

final class SlayerTaskIntentResolver
{
    boolean supports(String question, List<GuideMessage> history)
    {
        String normalized = normalize(question);
        if (normalized.matches(".*\\bslayer (?:task|assignment)\\b.*") ||
            normalized.matches(".*\\b(?:my|this|current|new|latest)(?: (?:new|latest|current))? " +
                "(?:task|assignment)\\b.*") ||
            normalized.matches(".*\\b(?:task|assignment) i (?:just )?(?:got|received|was assigned)\\b.*") ||
            normalized.matches(".*\\bfinish (?:my |this )?(?:task|assignment)\\b.*"))
        {
            return true;
        }
        if (!normalized.matches(".*\\b(?:it|them|those|monsters)\\b.*"))
        {
            if (!isCombatDetailQuestion(normalized) &&
                !WikiQueryPlanner.isReferentialFollowUp(question))
            {
                return false;
            }
        }
        int first = Math.max(0, history.size() - 4);
        for (int i = first; i < history.size(); i++)
        {
            String prior = normalize(history.get(i).getText());
            if (prior.contains("slayer task") || prior.contains("slayer assignment"))
            {
                return true;
            }
        }
        return false;
    }

    private static boolean isCombatDetailQuestion(String normalized)
    {
        return normalized.matches(".*\\bweak(?:ness|nesses)?\\b.*") ||
            normalized.matches(".*\\bweak to\\b.*") ||
            normalized.matches(".*\\b(?:defence|defense) (?:stat|stats|bonus|bonuses)\\b.*") ||
            normalized.matches(".*\\b(?:best|which|what) (?:attack )?style\\b.*");
    }

    private static String normalize(String value)
    {
        return value == null ? "" : value.toLowerCase(Locale.ENGLISH)
            .replaceAll("[^a-z0-9]+", " ").trim();
    }
}

package com.gielinorguide;

import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;

final class SlayerTaskSnapshot
{
    private final String name;
    private final String location;
    private final int initialAmount;
    private final int remainingAmount;

    SlayerTaskSnapshot(String name, String location, int initialAmount, int remainingAmount)
    {
        this.name = name == null ? "" : name.trim();
        this.location = location == null ? "" : location.trim();
        this.initialAmount = Math.max(0, initialAmount);
        this.remainingAmount = Math.max(0, remainingAmount);
    }

    static SlayerTaskSnapshot from(Client client)
    {
        int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
        if (remaining <= 0)
        {
            return new SlayerTaskSnapshot("", "", 0, 0);
        }
        try
        {
            int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
            int taskRow;
            if (taskId == 98)
            {
                List<Integer> bossRows = client.getDBRowsByValue(
                    DBTableID.SlayerTaskSublist.ID,
                    DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
                    0, client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
                if (bossRows.isEmpty())
                {
                    return new SlayerTaskSnapshot("", "", 0, 0);
                }
                taskRow = (Integer) client.getDBTableField(bossRows.get(0),
                    DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
            }
            else
            {
                List<Integer> taskRows = client.getDBRowsByValue(
                    DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
                if (taskRows.isEmpty())
                {
                    return new SlayerTaskSnapshot("", "", 0, 0);
                }
                taskRow = taskRows.get(0);
            }
            String taskName = (String) client.getDBTableField(taskRow,
                DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
            String taskLocation = "";
            int areaId = client.getVarpValue(VarPlayerID.SLAYER_AREA);
            if (areaId > 0)
            {
                List<Integer> areaRows = client.getDBRowsByValue(
                    DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
                if (!areaRows.isEmpty())
                {
                    taskLocation = (String) client.getDBTableField(areaRows.get(0),
                        DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0)[0];
                }
            }
            return new SlayerTaskSnapshot(taskName, taskLocation,
                client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL), remaining);
        }
        catch (RuntimeException exception)
        {
            return new SlayerTaskSnapshot("", "", 0, 0);
        }
    }

    boolean isActive()
    {
        return !name.isEmpty() && remainingAmount > 0;
    }

    String getWikiPageTitle()
    {
        return "Slayer task/" + name;
    }

    String asPlayerContext()
    {
        return "Active Slayer assignment explicitly enabled for this request:\n" +
            "- Task: " + name + "\n" +
            "- Remaining: " + remainingAmount + "\n" +
            "- Initial amount: " + initialAmount + "\n" +
            "- Assigned area: " + (location.isEmpty() ?
                "none specified by RuneLite" : location);
    }
}

package com.gielinorguide;

import java.util.Locale;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public final class TravelIntentResolver
{
    private static final Pattern[] DESTINATION_PATTERNS = {
        Pattern.compile("(?i)\\b(?:get|go|travel|navigate|walk|run|teleport|tp)\\s+(?:me\\s+)?to\\s+(.+)$"),
        Pattern.compile("(?i)\\b(?:route|directions|path|way)\\s+to\\s+(.+)$"),
        Pattern.compile("(?i)\\b(?:fastest|quickest|shortest|best)\\s+(?:way|route|path)\\s+(?:to\\s+)?(.+)$"),
        Pattern.compile("(?i)^\\s*where(?:'s| is)\\s+(.+)$"),
        Pattern.compile("(?i)^\\s*(?:take|bring)\\s+me\\s+to\\s+(.+)$")
    };
    private static final Pattern TRAILING_CONTEXT = Pattern.compile(
        "(?i)\\s+(?:from\\s+(?:here|where i am|my location)|right now|please)\\s*$");

    public Optional<String> extractDestination(String question)
    {
        if (question == null)
        {
            return Optional.empty();
        }
        String compact = question.replace('\u2019', '\'').replaceAll("\\s+", " ").trim();
        for (Pattern pattern : DESTINATION_PATTERNS)
        {
            Matcher matcher = pattern.matcher(compact);
            if (matcher.find())
            {
                String destination = matcher.group(1).replaceAll("[?!.]+$", "").trim();
                destination = TRAILING_CONTEXT.matcher(destination).replaceFirst("").trim();
                destination = destination.replaceFirst("(?i)^the\\s+", "");
                if (!destination.isEmpty() && !isPronoun(destination) &&
                    !isActivityRatherThanPlace(destination))
                {
                    return Optional.of(destination);
                }
            }
        }
        return Optional.empty();
    }

    public boolean isTravelFollowUp(String question)
    {
        if (question == null)
        {
            return false;
        }
        String normalized = question.toLowerCase(Locale.ENGLISH)
            .replaceAll("[^a-z0-9]+", " ").trim();
        return normalized.contains("get there") || normalized.contains("go there") ||
            normalized.contains("route there") || normalized.contains("directions there") ||
            normalized.contains("fastest way there") || normalized.contains("take me there") ||
            (normalized.contains("shortest path") &&
                normalized.matches(".*\\b(?:mark|route|navigate|use|set)\\b.*\\b(?:it|that|this)\\b.*")) ||
            normalized.matches("^(?:(?:what s|whats|what is|show me|give me) )?" +
                "(?:(?:the|teh) )?(?:route|directions|path)(?: from here)?$");
    }

    public boolean isDestinationSeeking(String question)
    {
        if (extractDestination(question).isPresent())
        {
            return true;
        }
        String normalized = question == null ? "" : question.toLowerCase(Locale.ENGLISH)
            .replaceAll("[^a-z0-9]+", " ").trim();
        return normalized.startsWith("where ") ||
            normalized.matches(".*\\bhow (?:do|can|should) i (?:get to|reach|travel to)\\b.*") ||
            normalized.matches(".*\\b(?:what|which) (?:place|location|route)\\b.*");
    }

    public boolean shouldUseShortestPath(String question)
    {
        return isDestinationSeeking(question) ||
            WikiQueryPlanner.isAccessQuestion(question) ||
            WikiQueryPlanner.isAcquisitionQuestion(question) ||
            WikiQueryPlanner.isGoalAssistanceQuestion(question) ||
            WikiQueryPlanner.isGoalWalkthroughQuestion(question);
    }

    private static boolean isPronoun(String destination)
    {
        String normalized = destination.toLowerCase(Locale.ENGLISH);
        return normalized.equals("there") || normalized.equals("it") ||
            normalized.equals("that place");
    }

    private static boolean isActivityRatherThanPlace(String destination)
    {
        String normalized = destination.toLowerCase(Locale.ENGLISH)
            .replaceAll("[^a-z0-9]+", " ").trim();
        return normalized.matches("^(?:level|lvl|train|raise|increase|improve)\\b.*") ||
            normalized.matches("^(?:make|earn)\\s+(?:money|gp)\\b.*") ||
            normalized.matches("^(?:kill|fight|beat|defeat)\\s+.+") ||
            normalized.matches("^(?:complete|finish|start|do)\\s+(?:a |an |the )?.+") ||
            normalized.contains(" at my level") || normalized.contains(" for my level") ||
            normalized.contains(" with my stats");
    }
}

