        }
        optionsByDestination = Collections.unmodifiableMap(immutable);
    }

    public List<VerifiedTravelOption> forDestination(String destinationId)
    {
        List<VerifiedTravelOption> options = optionsByDestination.get(destinationId);
        return options == null ? Collections.emptyList() : options;
    }

    public String asGroundingText(List<VerifiedLocation> destinations)
    {
        if (destinations.isEmpty())
        {
            return "No verified destination was resolved for this question. Do not invent a teleport route.";
        }

        StringBuilder result = new StringBuilder();
        for (VerifiedLocation destination : destinations)
        {
            List<VerifiedTravelOption> options = forDestination(destination.getId());
            if (options.isEmpty())
            {
                result.append("- No verified travel option is catalogued for ")
                    .append(destination.getName()).append(".\n");
                continue;
            }
            result.append(destination.getName()).append(":\n");
            for (VerifiedTravelOption option : options)
            {
                result.append("- ").append(option.getName()).append(": ")
                    .append(option.getGuidance()).append(" Source: ")
                    .append(option.getSourceUrl()).append('\n');
            }
        }
        return result.toString();
    }
