package com.gielinorguide;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** Adds access sections and bounded detail pages for named shortcuts and entrances. */
final class WikiAccessExpander
{
    private static final String API_URL = "https://oldschool.runescape.wiki/api.php";
    private static final int MAX_LINKED_ACCESS_PAGES = 4;
    private static final Pattern ACCESS_SECTION = Pattern.compile(
        "(?ims)^==\\s*(Transportation|Getting there|Access|Shortcuts?)\\s*==\\s*" +
            "(.*?)(?=^==[^=].*?==\\s*$|\\z)");
    private static final Pattern WIKI_LINK = Pattern.compile(
        "\\[\\[([^|#\\]]+)(?:#[^|\\]]*)?(?:\\|([^\\]]*))?]]");
    private static final Pattern ACCESS_TERM = Pattern.compile(
        "(?i)\\b(?:shortcut|grapple|rocks?|entrance|bridge|rope|gate|door|passage|" +
            "tunnel|ladder)\\b");

    private final OkHttpClient httpClient;
    private final Gson gson;
    private volatile Call activeCall;

    WikiAccessExpander(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    void expand(WikiResult base, Consumer<WikiResult> callback)
    {
        WikiSource primary = base.getPrimarySource();
        if (primary == null)
        {
            callback.accept(base);
            return;
        }
        Call call = httpClient.newCall(request(rawPageUrl(primary.getTitle())));
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    callback.accept(base);
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    if (!response.isSuccessful() || body == null)
                    {
                        callback.accept(base);
                        return;
                    }
                    AccessGrounding access = parseAccess(primary.getTitle(), primary.getUrl(),
                        revisionContent(body.string()));
                    if (access == null)
                    {
                        callback.accept(base);
                        return;
                    }
                    WikiResult expanded = merge(base, access.source,
                        new ArrayList<>());
                    if (access.linkedPages.isEmpty())
                    {
                        callback.accept(expanded);
                    }
                    else
                    {
                        fetchLinkedPages(expanded, access.linkedPages, callback);
                    }
                }
                catch (IOException | RuntimeException exception)
                {
                    callback.accept(base);
                }
            }
        });
    }

    AccessGrounding parseAccess(String title, String sourceUrl, String wikiText)
    {
        Matcher sections = ACCESS_SECTION.matcher(wikiText == null ? "" : wikiText);
        StringBuilder excerpt = new StringBuilder();
        Set<String> linkedPages = new LinkedHashSet<>();
        String firstSection = "";
        while (sections.find())
        {
            String sectionName = sections.group(1);
            String sectionText = sections.group(2);
            String plain = plain(sectionText);
            if (plain.isEmpty())
            {
                continue;
            }
            if (firstSection.isEmpty())
            {
                firstSection = sectionName.replace(' ', '_');
            }
            excerpt.append("Verified ").append(sectionName).append(" guidance:\n")
                .append(plain).append('\n');
            Matcher links = WIKI_LINK.matcher(sectionText);
            while (links.find() && linkedPages.size() < MAX_LINKED_ACCESS_PAGES)
            {
                String page = links.group(1).trim();
                String label = links.group(2) == null ? "" : links.group(2).trim();
                if (!page.equalsIgnoreCase(title) &&
                    ACCESS_TERM.matcher(page + " " + label).find())
                {
                    linkedPages.add(page);
                }
            }
        }
        if (excerpt.length() == 0)
        {
            return null;
        }
        String text = excerpt.toString().trim();
        if (text.length() > 3000)
        {
            text = text.substring(0, 3000) + "...";
        }
        WikiSource source = new WikiSource(title + " - Access routes",
            sourceUrl.replaceFirst("#.*$", "") + "#" + firstSection, text);
        return new AccessGrounding(source, new ArrayList<>(linkedPages));
    }

    List<WikiSource> linkedSources(String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        List<WikiSource> sources = new ArrayList<>();
        if (pages == null)
        {
            return sources;
        }
        for (JsonElement element : pages)
        {
            JsonObject page = element.getAsJsonObject();
            String title = string(page, "title");
            String url = string(page, "fullurl");
            String extract = string(page, "extract").replaceAll("\\s+", " ").trim();
            if (!title.isEmpty() && !url.isEmpty() && !extract.isEmpty())
            {
                sources.add(new WikiSource(title, url,
                    extract.length() <= 1400 ? extract : extract.substring(0, 1400) + "..."));
            }
        }
        return sources;
    }

    void cancel()
    {
        Call call = activeCall;
        if (call != null)
        {
            call.cancel();
        }
    }

    private void fetchLinkedPages(WikiResult base, List<String> pages,
        Consumer<WikiResult> callback)
    {
        Call call = httpClient.newCall(request(linkedPagesUrl(pages)));
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    callback.accept(base);
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    callback.accept(!response.isSuccessful() || body == null
                        ? base : merge(base, null, linkedSources(body.string())));
                }
                catch (IOException | RuntimeException exception)
                {
                    callback.accept(base);
                }
            }
        });
    }

    private String revisionContent(String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        if (pages == null || pages.size() == 0)
        {
            return "";
        }
        JsonArray revisions = pages.get(0).getAsJsonObject().getAsJsonArray("revisions");
        if (revisions == null || revisions.size() == 0)
        {
            return "";
        }
        JsonObject slots = revisions.get(0).getAsJsonObject().getAsJsonObject("slots");
        JsonObject main = slots == null ? null : slots.getAsJsonObject("main");
        return main == null ? "" : string(main, "content");
    }

    private static WikiResult merge(WikiResult base, WikiSource addition,
        List<WikiSource> linkedSources)
    {
        Map<String, WikiSource> sources = new LinkedHashMap<>();
        for (WikiSource source : base.getSources())
        {
            sources.put(source.getUrl(), source);
        }
        if (addition != null)
        {
            sources.put(addition.getUrl(), addition);
        }
        for (WikiSource source : linkedSources)
        {
            sources.put(source.getUrl(), source);
        }
        return new WikiResult(new ArrayList<>(sources.values()), base.isAvailable(),
            base.getDestinations());
    }

    private static String plain(String wikiText)
    {
        String text = wikiText
            .replaceAll("(?is)<ref\\b[^>]*>.*?</ref>|<ref\\b[^>]*/>", " ")
            .replaceAll("\\[\\[[^|\\]]+\\|([^\\]]+)]]", "$1")
            .replaceAll("\\[\\[([^\\]]+)]]", "$1")
            .replace("'''", "").replace("''", "")
            .replaceAll("(?m)^[*#:;]+\\s*", "- ");
        String previous;
        do
        {
            previous = text;
            text = text.replaceAll("(?is)\\{\\{[^{}]{0,1500}}}", " ");
        }
        while (!text.equals(previous));
        return text.replaceAll("[ \\t]+", " ")
            .replaceAll(" *\\r?\\n *", "\\n")
            .replaceAll("\\n{2,}", "\\n").trim();
    }

    private static HttpUrl rawPageUrl(String title)
    {
        return HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("titles", title)
            .addQueryParameter("prop", "revisions")
            .addQueryParameter("rvprop", "content")
            .addQueryParameter("rvslots", "main")
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
    }

    private static HttpUrl linkedPagesUrl(List<String> titles)
    {
        return HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("titles", String.join("|", titles))
            .addQueryParameter("prop", "extracts|info")
            .addQueryParameter("explaintext", "1")
            .addQueryParameter("exintro", "1")
            .addQueryParameter("exchars", "1400")
            .addQueryParameter("inprop", "url")
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
    }

    private static Request request(HttpUrl url)
    {
        return new Request.Builder().url(url)
            .header("User-Agent", "GielinorGuide RuneLite plugin access grounding")
            .build();
    }

    private static String string(JsonObject object, String name)
    {
        JsonElement value = object.get(name);
        return value == null || value.isJsonNull() ? "" : value.getAsString();
    }

    static final class AccessGrounding
    {
        private final WikiSource source;
        private final List<String> linkedPages;

        private AccessGrounding(WikiSource source, List<String> linkedPages)
        {
            this.source = source;
            this.linkedPages = linkedPages;
        }

        WikiSource getSource()
        {
            return source;
        }

        List<String> getLinkedPages()
        {
            return linkedPages;
        }
    }
}

package com.gielinorguide;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.LinkedHashSet;
import java.util.Set;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

final class WikiAcquisitionExpander
{
    private static final String API_URL = "https://oldschool.runescape.wiki/api.php";
    private static final int MAX_COMPONENTS = 8;
    private static final Pattern CREATION_SECTION = Pattern.compile(
        "(?ims)^==\\s*Creation\\s*==\\s*(.*?)(?=^==[^=].*?==\\s*$|\\z)");
    private static final Pattern FIELD = Pattern.compile(
        "(?m)^\\|\\s*([a-zA-Z][a-zA-Z0-9]*)\\s*=\\s*([^\\r\\n]*)");
    private static final Pattern LINK_TITLE = Pattern.compile(
        "(?is)<a\\b[^>]*\\btitle=\"([^\"]+)\"");

    private final OkHttpClient httpClient;
    private final Gson gson;
    private volatile Call activeCall;

    WikiAcquisitionExpander(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    void expand(WikiResult base, Consumer<WikiResult> callback)
    {
        WikiSource primary = base.getPrimarySource();
        if (primary == null)
        {
            callback.accept(base);
            return;
        }
        Call call = httpClient.newCall(request(rawPageUrl(primary.getTitle())));
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    callback.accept(base);
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    if (!response.isSuccessful() || body == null)
                    {
                        callback.accept(base);
                        return;
                    }
                    RecipeGrounding recipe = parseCreation(primary.getTitle(),
                        primary.getUrl(), revisionContent(body.string()));
                    if (recipe == null)
                    {
                        fetchRenderedGoal(base, primary, callback);
                        return;
                    }
                    WikiResult withRecipe = merge(base, recipe.source, new ArrayList<>());
                    if (recipe.components.isEmpty())
                    {
                        callback.accept(withRecipe);
                        return;
                    }
                    fetchComponents(withRecipe, recipe.components, callback);
                }
                catch (IOException | RuntimeException exception)
                {
                    callback.accept(base);
                }
            }
        });
    }

    RecipeGrounding parseCreation(String title, String sourceUrl, String wikiText)
    {
        Matcher sectionMatcher = CREATION_SECTION.matcher(wikiText == null ? "" : wikiText);
        if (!sectionMatcher.find())
        {
            return null;
        }
        Map<String, String> fields = new LinkedHashMap<>();
        Matcher fieldMatcher = FIELD.matcher(sectionMatcher.group(1));
        while (fieldMatcher.find())
        {
            fields.put(fieldMatcher.group(1).toLowerCase(), clean(fieldMatcher.group(2)));
        }

        List<String> components = new ArrayList<>();
        List<String> materials = new ArrayList<>();
        for (int i = 1; i <= MAX_COMPONENTS; i++)
        {
            String material = fields.get("mat" + i);
            if (material == null || material.isEmpty())
            {
                continue;
            }
            String quantity = fields.get("mat" + i + "quantity");
            if (quantity == null || quantity.isEmpty())
            {
                quantity = "1";
            }
            materials.add(quantity + " x " + material);
            components.add(material);
        }
        if (materials.isEmpty())
        {
            return null;
        }

        List<String> requirements = new ArrayList<>();
        for (int i = 1; i <= 3; i++)
        {
            String skill = fields.get("skill" + i);
            String level = fields.get("skill" + i + "lvl");
            if (skill != null && level != null)
            {
                String boostable = fields.get("skill" + i + "boostable");
                requirements.add(level + " " + skill +
                    ("no".equalsIgnoreCase(boostable) ? " (not boostable)" : ""));
            }
        }
        String excerpt = "Verified Creation recipe" +
            (requirements.isEmpty() ? "" : "; requires " + String.join(", ", requirements)) +
            "; materials: " + String.join(", ", materials) + ".";
        String url = sourceUrl.replaceFirst("#.*$", "") + "#Creation";
        return new RecipeGrounding(new WikiSource(title + " - Creation", url, excerpt),
            components);
    }

    void cancel()
    {
        Call call = activeCall;
        if (call != null)
        {
            call.cancel();
        }
    }

    private void fetchComponents(WikiResult base, List<String> components,
        Consumer<WikiResult> callback)
    {
        HttpUrl url = HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("titles", String.join("|", components))
            .addQueryParameter("prop", "extracts|info")
            .addQueryParameter("explaintext", "1")
            .addQueryParameter("exintro", "1")
            .addQueryParameter("exchars", "500")
            .addQueryParameter("exlimit", Integer.toString(components.size()))
            .addQueryParameter("inprop", "url")
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
        Call call = httpClient.newCall(request(url));
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    callback.accept(base);
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    if (!response.isSuccessful() || body == null)
                    {
                        callback.accept(base);
                        return;
                    }
                    callback.accept(merge(base, null, componentSources(body.string())));
                }
                catch (IOException | RuntimeException exception)
                {
                    callback.accept(base);
                }
            }
        });
    }

    private void fetchRenderedGoal(WikiResult base, WikiSource primary,
        Consumer<WikiResult> callback)
    {
        HttpUrl url = HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "parse")
            .addQueryParameter("page", primary.getTitle())
            .addQueryParameter("prop", "text")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
        Call call = httpClient.newCall(request(url));
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    callback.accept(base);
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    if (!response.isSuccessful() || body == null)
                    {
                        callback.accept(base);
                        return;
                    }
                    RecipeGrounding goal = parseRenderedGoal(primary.getTitle(),
                        primary.getUrl(), renderedHtml(body.string()));
                    if (goal == null)
                    {
                        callback.accept(base);
                        return;
                    }
                    WikiResult withGoal = merge(base, goal.source, new ArrayList<>());
                    if (goal.components.isEmpty())
                    {
                        callback.accept(withGoal);
                    }
                    else
                    {
                        fetchComponents(withGoal, goal.components, callback);
                    }
                }
                catch (IOException | RuntimeException exception)
                {
                    callback.accept(base);
                }
            }
        });
    }

    RecipeGrounding parseRenderedGoal(String title, String sourceUrl, String html)
    {
        if (html == null || html.isEmpty())
        {
            return null;
        }
        String lower = html.toLowerCase();
        int creation = lower.indexOf("creation");
        int itemSources = lower.indexOf("item sources");
        int focus = creation >= 0 ? creation : itemSources;
        if (focus < 0)
        {
            return null;
        }
        int start = Math.max(0, focus - 400);
        int end = Math.min(html.length(), focus + 18000);
        String focusedHtml = html.substring(start, end);
        String componentHtml = html.substring(Math.max(0, focus - 300), end);
        String text = htmlToText(focusedHtml);
        if (text.length() > 3200)
        {
            text = text.substring(0, 3200) + "...";
        }

        Set<String> linkedPages = new LinkedHashSet<>();
        Matcher links = LINK_TITLE.matcher(componentHtml);
        while (links.find() && linkedPages.size() < MAX_COMPONENTS)
        {
            String linkedTitle = htmlEntityDecode(links.group(1)).trim();
            String normalized = linkedTitle.toLowerCase();
            if (!linkedTitle.equalsIgnoreCase(title) &&
                !normalized.startsWith("file:") && !normalized.startsWith("category:") &&
                !normalized.contains("edit section") && !linkedTitle.isEmpty())
            {
                linkedPages.add(linkedTitle);
            }
        }
        WikiSource source = new WikiSource(title + " - goal details",
            sourceUrl.replaceFirst("#.*$", "") +
                (creation >= 0 ? "#Creation" : "#Item_sources"),
            "Verified rendered recipe and acquisition details: " + text);
        return new RecipeGrounding(source, new ArrayList<>(linkedPages));
    }

    private List<WikiSource> componentSources(String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        List<WikiSource> sources = new ArrayList<>();
        if (pages != null)
        {
            for (JsonElement element : pages)
            {
                JsonObject page = element.getAsJsonObject();
                String title = string(page, "title");
                String url = string(page, "fullurl");
                String extract = string(page, "extract").replaceAll("\\s+", " ").trim();
                if (!title.isEmpty() && !url.isEmpty() && !extract.isEmpty())
                {
                    sources.add(new WikiSource(title, url, extract));
                }
            }
        }
        return sources;
    }

    private String revisionContent(String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        if (pages == null || pages.size() == 0)
        {
            return "";
        }
        JsonArray revisions = pages.get(0).getAsJsonObject().getAsJsonArray("revisions");
        if (revisions == null || revisions.size() == 0)
        {
            return "";
        }
        JsonObject slots = revisions.get(0).getAsJsonObject().getAsJsonObject("slots");
        JsonObject main = slots == null ? null : slots.getAsJsonObject("main");
        return main == null ? "" : string(main, "content");
    }

    private String renderedHtml(String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject parse = root == null ? null : root.getAsJsonObject("parse");
        return parse == null ? "" : string(parse, "text");
    }

    private static WikiResult merge(WikiResult base, WikiSource recipe,
        List<WikiSource> componentSources)
    {
        Map<String, WikiSource> sources = new LinkedHashMap<>();
        for (WikiSource source : base.getSources())
        {
            sources.put(source.getUrl(), source);
        }
        if (recipe != null)
        {
            sources.put(recipe.getUrl(), recipe);
        }
        for (WikiSource source : componentSources)
        {
            sources.put(source.getUrl(), source);
        }
        return new WikiResult(new ArrayList<>(sources.values()), base.isAvailable());
    }

    private static HttpUrl rawPageUrl(String title)
    {
        return HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("titles", title)
            .addQueryParameter("prop", "revisions")
            .addQueryParameter("rvprop", "content")
            .addQueryParameter("rvslots", "main")
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
    }

    private static Request request(HttpUrl url)
    {
        return new Request.Builder().url(url)
            .header("User-Agent", "GielinorGuide RuneLite plugin acquisition grounding")
            .build();
    }

    private static String clean(String value)
    {
        return value.replaceAll("(?i)<ref\\b[^>]*>.*?</ref>|<ref\\b[^>]*/>", " ")
            .replaceAll("\\[\\[[^|\\]]+\\|([^\\]]+)\\]\\]", "$1")
            .replaceAll("\\[\\[([^\\]]+)\\]\\]", "$1")
            .replace("'''", "").replace("''", "")
            .replaceAll("\\s+", " ").trim();
    }

    private static String htmlToText(String html)
    {
        return htmlEntityDecode(html
            .replaceAll("(?is)<script\\b[^>]*>.*?</script>|<style\\b[^>]*>.*?</style>", " ")
            .replaceAll("(?i)<br\\s*/?>|</p>|</tr>|</li>|</h[1-6]>", "\\n")
            .replaceAll("(?is)<[^>]+>", " "))
            .replaceAll("[ \\t\\x0B\\f\\r]+", " ")
            .replaceAll(" *\\n *", "\\n")
            .replaceAll("\\n{2,}", "\\n")
            .trim();
    }

    private static String htmlEntityDecode(String value)
    {
        return value.replace("&times;", "×").replace("&nbsp;", " ")
            .replace("&amp;", "&").replace("&quot;", "\"")
            .replace("&#39;", "'").replace("&lt;", "<").replace("&gt;", ">");
    }

    private static String string(JsonObject object, String name)
    {
        JsonElement value = object.get(name);
        return value == null || value.isJsonNull() ? "" : value.getAsString();
    }

    static final class RecipeGrounding
    {
        private final WikiSource source;
        private final List<String> components;

        private RecipeGrounding(WikiSource source, List<String> components)
        {
            this.source = source;
            this.components = components;
        }

        WikiSource getSource()
        {
            return source;
        }

        List<String> getComponents()
        {
            return components;
        }
    }
}

package com.gielinorguide;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

public final class WikiClient
{
    private static final String API_URL = "https://oldschool.runescape.wiki/api.php";
    private static final int MAX_EXCERPT_LENGTH = 1600;
    private final OkHttpClient httpClient;
    private final Gson gson;
    private final WikiAcquisitionExpander acquisitionExpander;
    private final WikiPurposeExpander purposeExpander;
    private final WikiComparisonExpander comparisonExpander;
    private final WikiQuestRequirementExpander questRequirementExpander;
    private final WikiSlayerTaskExpander slayerTaskExpander;
    private final WikiDiaryExpander diaryExpander;
    private final WikiAccessExpander accessExpander;
    private final Map<String, WikiResult> resultCache = new ConcurrentHashMap<>();
    private volatile Call activeCall;

    public WikiClient(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient;
        this.gson = gson;
        this.acquisitionExpander = new WikiAcquisitionExpander(httpClient, gson);
        this.purposeExpander = new WikiPurposeExpander(httpClient, gson);
        this.comparisonExpander = new WikiComparisonExpander(httpClient, gson);
        this.questRequirementExpander = new WikiQuestRequirementExpander(httpClient, gson);
        this.slayerTaskExpander = new WikiSlayerTaskExpander(httpClient, gson);
        this.diaryExpander = new WikiDiaryExpander(httpClient, gson);
        this.accessExpander = new WikiAccessExpander(httpClient, gson);
    }

    public void search(String query, Consumer<WikiResult> callback)
    {
        search(query, false, false, false, callback);
    }

    public void search(String query, boolean expandAcquisition,
        Consumer<WikiResult> callback)
    {
        search(query, expandAcquisition, false, false, callback);
    }

    public void search(String query, boolean expandAcquisition, boolean expandPurpose,
        Consumer<WikiResult> callback)
    {
        search(query, expandAcquisition, expandPurpose, false, callback);
    }

    public void search(String query, boolean expandAcquisition, boolean expandPurpose,
        boolean expandComparison, Consumer<WikiResult> callback)
    {
        search(query, expandAcquisition, expandPurpose, expandComparison, false, callback);
    }

    public void search(String query, boolean expandAcquisition, boolean expandPurpose,
        boolean expandComparison, boolean expandQuestRequirements,
        Consumer<WikiResult> callback)
    {
        search(query, expandAcquisition, expandPurpose, expandComparison,
            expandQuestRequirements, false, callback);
    }

    public void search(String query, boolean expandAcquisition, boolean expandPurpose,
        boolean expandComparison, boolean expandQuestRequirements, boolean expandAccess,
        Consumer<WikiResult> callback)
    {
        String cacheKey = query.toLowerCase(Locale.ENGLISH).replaceAll("\\s+", " ").trim() +
            (expandAcquisition ? "|acquisition" : "|standard") +
            (expandPurpose ? "|purpose" : "") +
            (expandComparison ? "|comparison" : "") +
            (expandQuestRequirements ? "|quest-requirements" : "") +
            (expandAccess ? "|access" : "");
        WikiResult cached = resultCache.get(cacheKey);
        if (cached != null)
        {
            callback.accept(cached);
            return;
        }
        if (WikiQueryPlanner.isCanonicalPageQuery(query))
        {
            fetchExactPage(query, query, cacheKey, expandAcquisition, expandPurpose,
                expandComparison, expandQuestRequirements, expandAccess, true, callback);
            return;
        }

        searchForTitle(query, selectedTitle ->
            fetchExactPage(selectedTitle, query, cacheKey, expandAcquisition,
                expandPurpose, expandComparison, expandQuestRequirements,
                expandAccess, false, callback), callback);
    }

    private void searchForTitle(String query, Consumer<String> onTitle,
        Consumer<WikiResult> callback)
    {
        Request request = request(buildSearchUrl(query));
        Call call = httpClient.newCall(request);
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    callback.accept(WikiResult.unavailable());
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    if (!response.isSuccessful() || body == null)
                    {
                        callback.accept(WikiResult.unavailable());
                        return;
                    }
                    String selectedTitle = selectSearchTitle(body.string(), query);
                    if (selectedTitle == null)
                    {
                        callback.accept(new WikiResult(new ArrayList<>(), true));
                        return;
                    }
                    onTitle.accept(selectedTitle);
                }
                catch (IOException | RuntimeException exception)
                {
                    callback.accept(WikiResult.unavailable());
                }
            }
        });
    }

    HttpUrl buildUrl(String query)
    {
        return WikiQueryPlanner.isCanonicalPageQuery(query)
            ? buildExactUrl(query) : buildSearchUrl(query);
    }

    HttpUrl buildExactUrl(String title)
    {
        String pageTitle = WikiQueryPlanner.stripSection(title);
        boolean slayerTaskGuide = title != null &&
            title.toLowerCase(Locale.ENGLISH).startsWith("slayer task/");
        boolean slayerPlanningGuide = "Slayer Master".equals(title) ||
            "Slayer reward point".equals(title) || "Mortimer".equals(title);
        boolean preparationGuide = WikiPageCatalog.isRaidStrategyPage(title);
        boolean trainingGuide = title != null && title.endsWith(" training");
        boolean diaryGuide = WikiQueryPlanner.isAchievementDiaryQuery(title);
        return HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("prop", "extracts|info")
            .addQueryParameter("explaintext", "1")
            // Intro-only extracts often stop before the actionable first
            // section (notably the level 1-30 section of Sailing training).
            // Keep the payload bounded while including that first section.
            .addQueryParameter("exchars",
                trainingGuide ? "7000" :
                    diaryGuide ? "7000" :
                    slayerTaskGuide || slayerPlanningGuide || preparationGuide ? "5200" : "1200")
            .addQueryParameter("inprop", "url")
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .addQueryParameter("titles", pageTitle)
            .build();
    }

    private HttpUrl buildSearchUrl(String query)
    {
        return HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("generator", "search")
            .addQueryParameter("gsrsearch", query)
            .addQueryParameter("gsrnamespace", "0")
            .addQueryParameter("gsrlimit", "3")
            .addQueryParameter("prop", "info")
            .addQueryParameter("inprop", "url")
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
    }

    String selectSearchTitle(String json, String requestedQuery)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        String bestTitle = null;
        int bestRelevance = -1;
        int bestIndex = Integer.MAX_VALUE;
        if (pages != null)
        {
            for (JsonElement element : pages)
            {
                JsonObject page = element.getAsJsonObject();
                String title = getString(page, "title");
                int score = relevance(title, requestedQuery);
                int index = page.has("index") ? page.get("index").getAsInt() : Integer.MAX_VALUE;
                if (!title.isEmpty() && (score > bestRelevance ||
                    (score == bestRelevance && index < bestIndex)))
                {
                    bestTitle = title;
                    bestRelevance = score;
                    bestIndex = index;
                }
            }
        }
        return bestRelevance >= 30 ? bestTitle : null;
    }

    private void fetchExactPage(String title, String requestedQuery, String cacheKey,
        boolean expandAcquisition, boolean expandPurpose, boolean expandComparison,
        boolean expandQuestRequirements, boolean expandAccess,
        boolean searchIfMissing,
        Consumer<WikiResult> callback)
    {
        Call call = httpClient.newCall(request(buildExactUrl(title)));
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    callback.accept(WikiResult.unavailable());
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    if (!response.isSuccessful() || body == null)
                    {
                        callback.accept(WikiResult.unavailable());
                        return;
                    }
                    WikiResult result = parse(body.string(), requestedQuery);
                    // MediaWiki subpage titles are case-sensitive after the slash.
                    // RuneLite task names use display capitalization, so a valid
                    // task such as "Metal Dragons" can miss the canonical Wiki
                    // title "Metal dragons". Canonical queries normally bypass
                    // search; recover once through title search when that exact
                    // lookup returned no page content.
                    if (searchIfMissing && result.getSources().isEmpty())
                    {
                        searchForTitle(requestedQuery, selectedTitle ->
                            fetchExactPage(selectedTitle, requestedQuery, cacheKey,
                                expandAcquisition, expandPurpose, expandComparison,
                                expandQuestRequirements, expandAccess, false, callback),
                            callback);
                        return;
                    }
                    Consumer<WikiResult> finish = finalResult ->
                    {
                        if (finalResult.isAvailable())
                        {
                            resultCache.put(cacheKey, finalResult);
                        }
                        callback.accept(finalResult);
                    };
                    Consumer<WikiResult> afterComparison = expanded ->
                    {
                        Consumer<WikiResult> afterAccess = withAccess ->
                        {
                            if (expandAccess)
                            {
                                accessExpander.expand(withAccess, finish);
                            }
                            else
                            {
                                finish.accept(withAccess);
                            }
                        };
                        Consumer<WikiResult> afterSlayerProgression = withProgression ->
                        {
                            if (expandQuestRequirements)
                            {
                                questRequirementExpander.expand(withProgression, afterAccess);
                            }
                            else
                            {
                                afterAccess.accept(withProgression);
                            }
                        };
                        if (WikiQueryPlanner.isSlayerProgressionQuery(requestedQuery))
                        {
                            questRequirementExpander.expandPage(expanded,
                                "Fallen From Grace",
                                "https://oldschool.runescape.wiki/w/Fallen_From_Grace",
                                afterSlayerProgression);
                        }
                        else
                        {
                            afterSlayerProgression.accept(expanded);
                        }
                    };
                    Consumer<WikiResult> afterPurpose = expanded ->
                    {
                        if (expandComparison)
                        {
                            comparisonExpander.expand(expanded, afterComparison);
                        }
                        else
                        {
                            afterComparison.accept(expanded);
                        }
                    };
                    Consumer<WikiResult> afterAcquisition = expanded ->
                    {
                        if (expandPurpose)
                        {
                            purposeExpander.expand(expanded, afterPurpose);
                        }
                        else
                        {
                            afterPurpose.accept(expanded);
                        }
                    };
                    Consumer<WikiResult> afterDiary = expanded ->
                    {
                        if (expandAcquisition)
                        {
                            acquisitionExpander.expand(expanded, afterAcquisition);
                        }
                        else
                        {
                            afterAcquisition.accept(expanded);
                        }
                    };
                    Consumer<WikiResult> afterSlayer = expanded ->
                    {
                        if (WikiQueryPlanner.isAchievementDiaryQuery(requestedQuery) ||
                            WikiQueryPlanner.isAchievementDiaryQuery(title))
                        {
                            diaryExpander.expand(expanded,
                                WikiQueryPlanner.achievementDiaryTier(requestedQuery),
                                afterDiary);
                        }
                        else
                        {
                            afterDiary.accept(expanded);
                        }
                    };
                    if (title.toLowerCase(Locale.ENGLISH).startsWith("slayer task/") ||
                        requestedQuery.toLowerCase(Locale.ENGLISH).startsWith("slayer task/"))
                    {
                        slayerTaskExpander.expand(result, afterSlayer);
                    }
                    else
                    {
                        afterSlayer.accept(result);
                    }
                }
                catch (IOException | RuntimeException exception)
                {
                    callback.accept(WikiResult.unavailable());
                }
            }
        });
    }

    private static Request request(HttpUrl url)
    {
        return new Request.Builder().url(url)
            .header("User-Agent", "GielinorGuide RuneLite plugin")
            .build();
    }

    WikiResult parse(String json)
    {
        return parse(json, "");
    }

    WikiResult parse(String json, String requestedQuery)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        List<WikiSource> sources = new ArrayList<>();
        if (pages != null)
        {
            for (JsonElement pageElement : pages)
            {
                JsonObject page = pageElement.getAsJsonObject();
                String title = getString(page, "title");
                String url = WikiPageCatalog.addPreferredSectionAnchor(title,
                    getString(page, "fullurl"));
                String excerpt = compact(getString(page, "extract"),
                    expandedExcerptLimit(title));
                if (!title.isEmpty() && !url.isEmpty() && !excerpt.isEmpty())
                {
                    sources.add(new WikiSource(title, url, excerpt));
                }
            }
        }
        sources.sort(Comparator.comparingInt(
            (WikiSource source) -> relevance(source.getTitle(), requestedQuery)).reversed());
        if (!sources.isEmpty() && relevance(sources.get(0).getTitle(), requestedQuery) >= 80)
        {
            int end = 1;
            while (end < sources.size() &&
                relevance(sources.get(end).getTitle(), requestedQuery) >= 60)
            {
                end++;
            }
            sources = new ArrayList<>(sources.subList(0, end));
        }
        return new WikiResult(sources, true);
    }

    public void cancel()
    {
        Call call = activeCall;
        if (call != null)
        {
            call.cancel();
        }
        acquisitionExpander.cancel();
        purposeExpander.cancel();
        comparisonExpander.cancel();
        questRequirementExpander.cancel();
        slayerTaskExpander.cancel();
        diaryExpander.cancel();
        accessExpander.cancel();
    }

    private static String getString(JsonObject object, String name)
    {
        JsonElement value = object.get(name);
        return value == null || value.isJsonNull() ? "" : value.getAsString();
    }

    private static String compact(String text, int maxLength)
    {
        String compact = text.replaceAll("\\s+", " ").trim();
        if (compact.length() <= maxLength)
        {
            return compact;
        }
        return compact.substring(0, maxLength) + "...";
    }

    private static int expandedExcerptLimit(String title)
    {
        String normalized = title == null ? "" : title.toLowerCase(Locale.ENGLISH);
        if (normalized.startsWith("slayer task/") ||
            "slayer master".equals(normalized) ||
            "slayer reward point".equals(normalized) ||
            "mortimer".equals(normalized) || WikiPageCatalog.isRaidStrategyPage(title) ||
            WikiQueryPlanner.isAchievementDiaryQuery(title))
        {
            return 5200;
        }
        if (normalized.endsWith(" training"))
        {
            return 7000;
        }
        return MAX_EXCERPT_LENGTH;
    }

    private static int relevance(String title, String query)
    {
        String normalizedTitle = normalize(title);
        String normalizedQuery = normalize(query);
        if (normalizedTitle.isEmpty() || normalizedQuery.isEmpty())
        {
            return 0;
        }
        if (normalizedTitle.equals(normalizedQuery))
        {
            return 100;
        }
        String baseTitle = normalizedTitle.replaceFirst("\\s+[^ ]+$", "");
        if (baseTitle.equals(normalizedQuery))
        {
            return 90;
        }
        if (normalizedTitle.contains(normalizedQuery) || normalizedQuery.contains(normalizedTitle))
        {
            return 80;
        }
        int matched = 0;
        String[] queryWords = normalizedQuery.split(" ");
        for (String word : queryWords)
        {
            if (word.length() >= 3 && containsWord(normalizedTitle, word))
            {
                matched++;
            }
        }
        return queryWords.length == 0 ? 0 : matched * 60 / queryWords.length;
    }

    private static boolean containsWord(String value, String word)
    {
        return (" " + value + " ").contains(" " + word + " ");
    }

    private static String normalize(String value)
    {
        return value == null ? "" : value.toLowerCase(Locale.ENGLISH)
            .replaceAll("[^a-z0-9]+", " ").trim();
    }
}

package com.gielinorguide;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Adds a small, reviewable set of candidate pages for questions which ask the
 * model to compare a category. Candidate facts still come from the live Wiki;
 * this class only records which pages form a useful comparison set.
 */
final class WikiComparisonExpander
{
    private static final String API_URL = "https://oldschool.runescape.wiki/api.php";
    private static final Map<String, List<String>> CANDIDATES;

    static
    {
        Map<String, List<String>> candidates = new LinkedHashMap<>();
        candidates.put("Pet", Arrays.asList("Kitten", "Gertrude's Cat"));
        candidates.put("Slayer Master", Arrays.asList(
            "Mortimer", "Slayer reward point", "Slayer training"));
        candidates.put("Slayer reward point", Arrays.asList(
            "Mortimer", "Slayer Master", "Slayer training"));
        candidates.put("Slayer training", Arrays.asList(
            "Mortimer", "Slayer Master", "Slayer reward point"));
        candidates.put("Slayer helmet", Arrays.asList(
            "Mortimer", "Slayer Master", "Slayer reward point"));
        candidates.put("Mortimer", Arrays.asList(
            "Slayer Master", "Slayer reward point", "Slayer training"));
        CANDIDATES = Collections.unmodifiableMap(candidates);
    }

    private final OkHttpClient httpClient;
    private final Gson gson;
    private volatile Call activeCall;

    WikiComparisonExpander(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    void expand(WikiResult base, Consumer<WikiResult> callback)
    {
        WikiSource primary = base.getPrimarySource();
        if (primary == null)
        {
            callback.accept(base);
            return;
        }
        List<String> pages = candidatePages(primary.getTitle());
        if (pages.isEmpty())
        {
            callback.accept(base);
            return;
        }
        HttpUrl url = HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("titles", String.join("|", pages))
            .addQueryParameter("prop", "extracts|info")
            .addQueryParameter("explaintext", "1")
            // MediaWiki only returns one whole-page extract in a multi-title
            // query. Intro extracts are available for every candidate and
            // contain the acquisition facts needed for comparisons.
            .addQueryParameter("exintro", "1")
            .addQueryParameter("exchars", "1400")
            .addQueryParameter("exlimit", Integer.toString(pages.size()))
            .addQueryParameter("inprop", "url")
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
        Call call = httpClient.newCall(request(url));
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    callback.accept(base);
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    callback.accept(!response.isSuccessful() || body == null
                        ? base : merge(base, parseSources(body.string())));
                }
                catch (IOException | RuntimeException exception)
                {
                    callback.accept(base);
                }
            }
        });
    }

    static List<String> candidatePages(String primaryTitle)
    {
        List<String> pages = CANDIDATES.get(primaryTitle);
        return pages == null ? Collections.emptyList() : pages;
    }

    void cancel()
    {
        Call call = activeCall;
        if (call != null)
        {
            call.cancel();
        }
    }

    private List<WikiSource> parseSources(String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        List<WikiSource> sources = new ArrayList<>();
        if (pages != null)
        {
            for (JsonElement element : pages)
            {
                JsonObject page = element.getAsJsonObject();
                String title = string(page, "title");
                String url = string(page, "fullurl");
                String excerpt = string(page, "extract").replaceAll("\\s+", " ").trim();
                if (!title.isEmpty() && !url.isEmpty() && !excerpt.isEmpty())
                {
                    sources.add(new WikiSource(title, url, excerpt));
                }
            }
        }
        return sources;
    }

    private static WikiResult merge(WikiResult base, List<WikiSource> additions)
    {
        Map<String, WikiSource> sources = new LinkedHashMap<>();
        for (WikiSource source : base.getSources())
        {
            sources.put(source.getUrl(), source);
        }
        for (WikiSource source : additions)
        {
            sources.put(source.getUrl(), source);
        }
        return new WikiResult(new ArrayList<>(sources.values()), base.isAvailable());
    }

    private static Request request(HttpUrl url)
    {
        return new Request.Builder().url(url)
            .header("User-Agent", "GielinorGuide RuneLite plugin comparison grounding")
            .build();
    }

    private static String string(JsonObject object, String name)
    {
        JsonElement value = object.get(name);
        return value == null || value.isJsonNull() ? "" : value.getAsString();
    }
}

package com.gielinorguide;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.coords.WorldPoint;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

public final class WikiDestinationClient
{
    private static final String API_URL = "https://oldschool.runescape.wiki/api.php";
    private static final Pattern X_PARAMETER = Pattern.compile("(?i)(?:^|\\|)\\s*x\\s*=\\s*(\\d{1,5})");
    private static final Pattern Y_PARAMETER = Pattern.compile("(?i)(?:^|\\|)\\s*y\\s*=\\s*(\\d{1,5})");
    private static final Pattern PLANE_PARAMETER = Pattern.compile("(?i)(?:^|\\|)\\s*(?:plane|p)\\s*=\\s*([0-3])");
    private static final Pattern POSITIONAL_COORDINATES = Pattern.compile(
        "(?:^|\\|)\\s*(\\d{4,5})\\s*,\\s*(\\d{4,5})(?=\\s*(?:,|\\||}|$))");
    private static final Pattern PRIMARY_MAP_ASSIGNMENT = Pattern.compile(
        "(?is)\\|\\s*map\\s*=\\s*\\{\\{\\s*(?:ocean\\s+)?map\\b");
    private static final Pattern ENTRANCE_MAP_CUE = Pattern.compile(
        "(?i)\\b(?:entrance|entry|trapdoor)\\b");
    private static final Pattern TRAVEL_SECTION = Pattern.compile(
        "(?ims)^==\\s*(?:transportation|getting there|location)\\s*==\\s*(.*?)(?=^==[^=].*?==\\s*$|\\z)");
    private static final Pattern WIKI_LINK = Pattern.compile(
        "\\[\\[([^|#\\]]+)(?:#[^|\\]]*)?(?:\\|([^\\]]+))?]]");
    private static final int MAX_TRAVEL_GUIDANCE_LENGTH = 3500;
    private static final int MAX_SOURCE_PAGES = 4;
    private static final int MAX_DESTINATION_CANDIDATES = 8;
    private static final int UNDERGROUND_REGION_Y = 6400;
    private final OkHttpClient httpClient;
    private final Gson gson;
    private final Map<String, VerifiedLocation> verifiedCache = new ConcurrentHashMap<>();
    private volatile Call activeCall;

    public WikiDestinationClient(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient.newBuilder()
            .connectTimeout(8, TimeUnit.SECONDS)
            .readTimeout(10, TimeUnit.SECONDS)
            .callTimeout(12, TimeUnit.SECONDS)
            .build();
        this.gson = gson;
    }

    public void resolve(String destinationQuery, Consumer<VerifiedLocation> onSuccess,
        Runnable onUnavailable)
    {
        String cacheKey = normalize(destinationQuery);
        VerifiedLocation cached = verifiedCache.get(cacheKey);
        if (cached != null)
        {
            onSuccess.accept(cached);
            return;
        }
        HttpUrl url = HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("generator", "search")
            .addQueryParameter("gsrsearch", fuzzySearchQuery(destinationQuery))
            .addQueryParameter("gsrnamespace", "0")
            .addQueryParameter("gsrlimit", "5")
            .addQueryParameter("prop", "revisions|info")
            .addQueryParameter("rvprop", "content")
            .addQueryParameter("rvslots", "main")
            .addQueryParameter("inprop", "url")
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
        Request request = new Request.Builder().url(url)
            .header("User-Agent", "GielinorGuide RuneLite plugin")
            .build();
        Call call = httpClient.newCall(request);
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    onUnavailable.run();
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    VerifiedLocation location = !response.isSuccessful() || body == null
                        ? null : parse(destinationQuery, body.string());
                    if (location == null)
                    {
                        onUnavailable.run();
                    }
                    else
                    {
                        verifiedCache.put(cacheKey, location);
                        onSuccess.accept(location);
                    }
                }
                catch (IOException | RuntimeException exception)
                {
                    onUnavailable.run();
                }
            }
        });
    }

    /**
     * Resolves a place named in a grounded answer by first confirming that the place is linked
     * from one of the supplied Wiki source pages, then requiring that place's own Wiki page to
     * provide a single usable map point. Model text alone is never accepted as a route target.
     */
    public void resolveFromSources(String answer, List<WikiSource> sources,
        Consumer<VerifiedLocation> onSuccess, Runnable onUnavailable)
    {
        List<String> sourcePages = sourcePageTitles(sources);
        if (sourcePages.isEmpty())
        {
            onUnavailable.run();
            return;
        }
        Call call = httpClient.newCall(request(rawPagesUrl(sourcePages)));
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    onUnavailable.run();
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    if (!response.isSuccessful() || body == null)
                    {
                        onUnavailable.run();
                        return;
                    }
                    List<String> candidates = destinationCandidates(answer, body.string());
                    if (candidates.isEmpty())
                    {
                        onUnavailable.run();
                        return;
                    }
                    fetchDestinationCandidates(candidates, onSuccess, onUnavailable);
                }
                catch (IOException | RuntimeException exception)
                {
                    onUnavailable.run();
                }
            }
        });
    }

    private void fetchDestinationCandidates(List<String> candidates,
        Consumer<VerifiedLocation> onSuccess, Runnable onUnavailable)
    {
        for (String candidate : candidates)
        {
            VerifiedLocation cached = verifiedCache.get(normalize(candidate));
            if (cached != null)
            {
                onSuccess.accept(cached);
                return;
            }
        }
        Call call = httpClient.newCall(request(rawPagesUrl(candidates)));
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    onUnavailable.run();
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    VerifiedLocation location = !response.isSuccessful() || body == null
                        ? null : parseCandidateDestination(candidates, body.string());
                    if (location == null)
                    {
                        onUnavailable.run();
                        return;
                    }
                    for (String candidate : candidates)
                    {
                        if (normalize(candidate).equals(normalize(location.getName())) ||
                            location.getAliases().contains(candidate))
                        {
                            verifiedCache.put(normalize(candidate), location);
                        }
                    }
                    onSuccess.accept(location);
                }
                catch (IOException | RuntimeException exception)
                {
                    onUnavailable.run();
                }
            }
        });
    }

    List<String> destinationCandidates(String answer, String sourceJson)
    {
        JsonObject root = gson.fromJson(sourceJson, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        if (pages == null)
        {
            return Collections.emptyList();
        }
        String normalizedAnswer = normalize(answer);
        Map<String, DestinationCandidate> candidates = new java.util.LinkedHashMap<>();
        for (JsonElement element : pages)
        {
            JsonObject page = element.getAsJsonObject();
            String sourceTitle = string(page, "title");
            Matcher links = WIKI_LINK.matcher(revisionContent(page));
            while (links.find())
            {
                String title = links.group(1).trim();
                String label = links.group(2) == null ? title : links.group(2).trim();
                String mentioned = normalizedAnswer.contains(normalize(label)) ? label : title;
                int position = phraseIndex(normalizedAnswer, normalize(mentioned));
                if (position < 0 || !isUsefulDestinationLink(title, sourceTitle))
                {
                    continue;
                }
                int score = destinationCueScore(normalizedAnswer, position, title);
                String key = normalize(title);
                DestinationCandidate existing = candidates.get(key);
                if (existing == null || score > existing.score)
                {
                    candidates.put(key, new DestinationCandidate(title, score));
                }
            }
        }
        List<DestinationCandidate> ordered = new ArrayList<>(candidates.values());
        ordered.sort((left, right) -> Integer.compare(right.score, left.score));
        List<String> result = new ArrayList<>();
        for (DestinationCandidate candidate : ordered)
        {
            result.add(candidate.title);
            if (result.size() >= MAX_DESTINATION_CANDIDATES)
            {
                break;
            }
        }
        return result;
    }

    VerifiedLocation parseCandidateDestination(List<String> candidates, String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        if (pages == null)
        {
            return null;
        }
        VerifiedLocation best = null;
        int bestPriority = Integer.MIN_VALUE;
        for (int i = 0; i < candidates.size(); i++)
        {
            String candidate = candidates.get(i);
            JsonObject page = selectPage(candidate, pages);
            if (page == null)
            {
                continue;
            }
            String wikiText = revisionContent(page);
            WorldPoint point = singleMapPoint(wikiText);
            String title = string(page, "title");
            String sourceUrl = string(page, "fullurl");
            if (point == null || title.isEmpty() || sourceUrl.isEmpty())
            {
                continue;
            }
            int priority = 1000 - (i * 10);
            if (Pattern.compile("(?is)\\{\\{\\s*Infobox\\s+Location\\b")
                .matcher(wikiText).find())
            {
                priority += 100;
            }
            if (priority <= bestPriority)
            {
                continue;
            }
            String travelGuidance = travelSection(wikiText);
            String guidance = "The recommended place is linked by the supplied OSRS Wiki " +
                "source, and its own Wiki page verifies a map point at " + point.getX() +
                ", " + point.getY() + ", plane " + point.getPlane() + ".";
            if (!travelGuidance.isEmpty())
            {
                guidance += " Wiki travel guidance: " + travelGuidance;
            }
            WorldPoint routePoint = routeMapPoint(wikiText, point);
            if (!routePoint.equals(point))
            {
                guidance += " A separate Wiki entrance map verifies the Shortest Path " +
                    "handoff at " + routePoint.getX() + ", " + routePoint.getY() +
                    ", plane " + routePoint.getPlane() + ".";
            }
            best = new VerifiedLocation("wiki-" + normalize(title).replace(' ', '-'), title,
                Collections.singletonList(candidate), point, routePoint, guidance, sourceUrl);
            bestPriority = priority;
        }
        return best;
    }

    VerifiedLocation parse(String destinationQuery, String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        if (pages == null)
        {
            return null;
        }
        JsonObject selected = selectPage(destinationQuery, pages);
        if (selected == null)
        {
            return null;
        }
        String title = string(selected, "title");
        String sourceUrl = string(selected, "fullurl");
        String wikiText = revisionContent(selected);
        WorldPoint point = singleMapPoint(wikiText);
        if (title.isEmpty() || sourceUrl.isEmpty() || point == null)
        {
            return null;
        }
        String travelGuidance = travelSection(wikiText);
        String guidance = "The OSRS Wiki page supplies a single map coordinate for this destination at " +
            point.getX() + ", " + point.getY() + ", plane " + point.getPlane() + ".";
        if (!travelGuidance.isEmpty())
        {
            guidance += " Wiki travel guidance: " + travelGuidance;
        }
        WorldPoint routePoint = routeMapPoint(wikiText, point);
        if (!routePoint.equals(point))
        {
            guidance += " A separate Wiki entrance map verifies the Shortest Path handoff at " +
                routePoint.getX() + ", " + routePoint.getY() + ", plane " +
                routePoint.getPlane() + ".";
        }
        return new VerifiedLocation("wiki-" + normalize(title).replace(' ', '-'), title,
            Collections.singletonList(destinationQuery), point, routePoint, guidance, sourceUrl);
    }

    private static JsonObject selectPage(String destinationQuery, JsonArray pages)
    {
        String wanted = normalize(destinationQuery);
        JsonObject containedMatch = null;
        JsonObject fuzzyMatch = null;
        int bestDistance = Integer.MAX_VALUE;
        boolean tied = false;
        for (JsonElement element : pages)
        {
            JsonObject page = element.getAsJsonObject();
            String title = normalize(string(page, "title"));
            String baseTitle = title.replaceFirst("\\s*\\([^)]*\\)\\s*$", "");
            if (title.equals(wanted) || baseTitle.equals(wanted))
            {
                return page;
            }
            if (containedMatch == null && (title.contains(wanted) || wanted.contains(title)))
            {
                containedMatch = page;
            }
            int distance = levenshtein(wanted, baseTitle);
            if (distance < bestDistance)
            {
                bestDistance = distance;
                fuzzyMatch = page;
                tied = false;
            }
            else if (distance == bestDistance)
            {
                tied = true;
            }
        }
        if (containedMatch != null)
        {
            return containedMatch;
        }
        int allowedDistance = wanted.length() >= 9 ? 4 : wanted.length() >= 6 ? 2 : 1;
        return !tied && bestDistance <= allowedDistance ? fuzzyMatch : null;
    }

    private static List<String> sourcePageTitles(List<WikiSource> sources)
    {
        Set<String> titles = new LinkedHashSet<>();
        for (WikiSource source : sources)
        {
            HttpUrl url = HttpUrl.parse(source.getUrl());
            if (url == null || !"oldschool.runescape.wiki".equalsIgnoreCase(url.host()))
            {
                continue;
            }
            List<String> segments = url.pathSegments();
            if (segments.size() < 2 || !"w".equals(segments.get(0)))
            {
                continue;
            }
            String title = segments.get(segments.size() - 1).replace('_', ' ').trim();
            if (!title.isEmpty())
            {
                titles.add(title);
            }
            if (titles.size() >= MAX_SOURCE_PAGES)
            {
                break;
            }
        }
        return new ArrayList<>(titles);
    }

    private static boolean isUsefulDestinationLink(String title, String sourceTitle)
    {
        String normalized = normalize(title);
        return !normalized.isEmpty() && !normalized.equals(normalize(sourceTitle)) &&
            !title.contains(":") &&
            !normalized.matches("(?:members|quest points?|melee|magic|ranged|prayer|" +
                "minigame|combat level|old school runescape|update|collection log)");
    }

    private static int destinationCueScore(String answer, int position, String title)
    {
        String prefix = answer.substring(Math.max(0, position - 55), position);
        int score = 0;
        if (prefix.matches(".*\\b(?:in|at|inside|within|near|of)\\s+(?:the\\s+)?$"))
        {
            score += 40;
        }
        else if (prefix.matches(".*\\bto\\s+(?:the\\s+)?$"))
        {
            score += 25;
        }
        if (prefix.matches(".*\\b(?:basement|floor|room|entrance|building|area)\\b.*"))
        {
            score += 30;
        }
        if (normalize(title).matches(".*\\b(?:guild|dungeon|cave|tower|city|village|" +
            "island|camp|arena|lair|mine|temple|castle|palace|house|shop|bank|port|" +
            "ruins|pit|stronghold|outpost)\\b.*"))
        {
            score += 25;
        }
        return score;
    }

    private static int phraseIndex(String text, String phrase)
    {
        if (phrase.isEmpty())
        {
            return -1;
        }
        return (" " + text + " ").indexOf(" " + phrase + " ");
    }

    private static String revisionContent(JsonObject page)
    {
        JsonArray revisions = page.getAsJsonArray("revisions");
        if (revisions == null || revisions.size() == 0)
        {
            return "";
        }
        JsonObject slots = revisions.get(0).getAsJsonObject().getAsJsonObject("slots");
        JsonObject main = slots == null ? null : slots.getAsJsonObject("main");
        return main == null ? "" : string(main, "content");
    }

    static WorldPoint singleMapPoint(String wikiText)
    {
        Matcher primary = PRIMARY_MAP_ASSIGNMENT.matcher(wikiText);
        if (primary.find())
        {
            int templateStart = wikiText.indexOf("{{", primary.start());
            int templateEnd = wikiText.indexOf("}}", templateStart);
            if (templateStart >= 0 && templateEnd > templateStart)
            {
                WorldPoint point = parseMapTemplate(wikiText.substring(templateStart,
                    Math.min(templateEnd + 2, templateStart + 1000)));
                if (point != null)
                {
                    return point;
                }
            }
        }
        Set<WorldPoint> points = new LinkedHashSet<>();
        collectMapPoints(wikiText, "{{Map", points);
        collectMapPoints(wikiText, "{{Ocean map", points);
        return points.size() == 1 ? points.iterator().next() : null;
    }

    private static WorldPoint routeMapPoint(String wikiText, WorldPoint destinationPoint)
    {
        WorldPoint entrance = entranceMapPoint(wikiText);
        if (entrance != null && destinationPoint.getY() >= UNDERGROUND_REGION_Y &&
            entrance.getY() < UNDERGROUND_REGION_Y)
        {
            return entrance;
        }
        return destinationPoint;
    }

    static WorldPoint entranceMapPoint(String wikiText)
    {
        String text = wikiText == null ? "" : wikiText.replaceAll("(?is)<!--.*?-->", " ");
        int start = 0;
        while ((start = nextMapTemplate(text, start)) >= 0)
        {
            int end = text.indexOf("}}", start);
            if (end < 0)
            {
                return null;
            }
            String template = text.substring(start, Math.min(end + 2, start + 1000));
            if (ENTRANCE_MAP_CUE.matcher(template).find())
            {
                WorldPoint point = representativeMapPoint(template);
                if (point != null)
                {
                    return point;
                }
            }
            start = end + 2;
        }
        return null;
    }

    private static WorldPoint representativeMapPoint(String template)
    {
        int plane = 0;
        Integer parsedPlane = matchInt(PLANE_PARAMETER, template);
        if (parsedPlane != null)
        {
            plane = parsedPlane;
        }
        List<WorldPoint> points = new ArrayList<>();
        Matcher positional = POSITIONAL_COORDINATES.matcher(template);
        while (positional.find())
        {
            int x = Integer.parseInt(positional.group(1));
            int y = Integer.parseInt(positional.group(2));
            if (x > 0 && y > 0 && x <= 16383 && y <= 16383)
            {
                points.add(new WorldPoint(x, y, plane));
            }
        }
        if (points.isEmpty())
        {
            return parseMapTemplate(template);
        }
        // Polygon templates use x/y for the viewport center. Keep the handoff on a
        // Wiki-supplied polygon point nearest the mapped feature's center instead.
        double centerX = 0;
        double centerY = 0;
        for (WorldPoint point : points)
        {
            centerX += point.getX();
            centerY += point.getY();
        }
        centerX /= points.size();
        centerY /= points.size();
        WorldPoint nearest = null;
        double nearestDistance = Double.MAX_VALUE;
        for (WorldPoint point : points)
        {
            double xDistance = point.getX() - centerX;
            double yDistance = point.getY() - centerY;
            double distance = xDistance * xDistance + yDistance * yDistance;
            if (distance < nearestDistance)
            {
                nearest = point;
                nearestDistance = distance;
            }
        }
        return nearest;
    }

    private static int nextMapTemplate(String text, int fromIndex)
    {
        int map = indexOfIgnoreCase(text, "{{Map", fromIndex);
        int ocean = indexOfIgnoreCase(text, "{{Ocean map", fromIndex);
        if (map < 0)
        {
            return ocean;
        }
        if (ocean < 0)
        {
            return map;
        }
        return Math.min(map, ocean);
    }

    static WorldPoint firstMapPoint(String wikiText)
    {
        String text = wikiText == null ? "" : wikiText.replaceAll("(?is)<!--.*?-->", " ");
        int mapStart = indexOfIgnoreCase(text, "{{Map", 0);
        int oceanStart = indexOfIgnoreCase(text, "{{Ocean map", 0);
        int start;
        if (mapStart < 0)
        {
            start = oceanStart;
        }
        else if (oceanStart < 0)
        {
            start = mapStart;
        }
        else
        {
            start = Math.min(mapStart, oceanStart);
        }
        while (start >= 0)
        {
            int end = text.indexOf("}}", start);
            if (end < 0)
            {
                return null;
            }
            WorldPoint point = parseMapTemplate(text.substring(start,
                Math.min(end + 2, start + 1000)));
            if (point != null)
            {
                return point;
            }
            int nextMap = indexOfIgnoreCase(text, "{{Map", end + 2);
            int nextOcean = indexOfIgnoreCase(text, "{{Ocean map", end + 2);
            if (nextMap < 0)
            {
                start = nextOcean;
            }
            else if (nextOcean < 0)
            {
                start = nextMap;
            }
            else
            {
                start = Math.min(nextMap, nextOcean);
            }
        }
        return null;
    }

    static String travelSection(String wikiText)
    {
        Matcher matcher = TRAVEL_SECTION.matcher(wikiText == null ? "" : wikiText);
        if (!matcher.find())
        {
            return "";
        }
        String section = matcher.group(1)
            .replaceAll("(?is)<ref\\b[^>]*>.*?</ref>|<ref\\b[^>]*/>", " ")
            .replaceAll("(?is)\\{\\{[^{}]{0,500}\\}\\}", " ")
            .replaceAll("\\[\\[[^|\\]]+\\|([^\\]]+)\\]\\]", "$1")
            .replaceAll("\\[\\[([^\\]]+)\\]\\]", "$1")
            .replace("'''", "")
            .replace("''", "")
            .replaceAll("(?m)^[*#:;]+\\s*", "- ")
            .replaceAll("\\s+", " ")
            .trim();
        return section.length() <= MAX_TRAVEL_GUIDANCE_LENGTH
            ? section : section.substring(0, MAX_TRAVEL_GUIDANCE_LENGTH) + "...";
    }

    private static void collectMapPoints(String wikiText, String templateName,
        Set<WorldPoint> points)
    {
        int start = 0;
        while ((start = indexOfIgnoreCase(wikiText, templateName, start)) >= 0)
        {
            int end = wikiText.indexOf("}}", start);
            if (end < 0)
            {
                break;
            }
            String template = wikiText.substring(start, Math.min(end + 2, start + 1000));
            WorldPoint point = parseMapTemplate(template);
            if (point != null)
            {
                points.add(point);
            }
            start = end + 2;
        }
    }

    static WorldPoint parseMapTemplate(String template)
    {
        Integer x = matchInt(X_PARAMETER, template);
        Integer y = matchInt(Y_PARAMETER, template);
        if (x == null || y == null)
        {
            Matcher positional = POSITIONAL_COORDINATES.matcher(template);
            if (positional.find())
            {
                x = Integer.parseInt(positional.group(1));
                y = Integer.parseInt(positional.group(2));
            }
        }
        Integer plane = matchInt(PLANE_PARAMETER, template);
        int resolvedPlane = plane == null ? 0 : plane;
        if (x == null || y == null || x <= 0 || y <= 0 || x > 16383 || y > 16383)
        {
            return null;
        }
        return new WorldPoint(x, y, resolvedPlane);
    }

    private static Integer matchInt(Pattern pattern, String value)
    {
        Matcher matcher = pattern.matcher(value);
        return matcher.find() ? Integer.parseInt(matcher.group(1)) : null;
    }

    private static int indexOfIgnoreCase(String text, String value, int fromIndex)
    {
        return text.toLowerCase(Locale.ENGLISH).indexOf(value.toLowerCase(Locale.ENGLISH), fromIndex);
    }

    private static String string(JsonObject object, String name)
    {
        JsonElement value = object.get(name);
        return value == null || value.isJsonNull() ? "" : value.getAsString();
    }

    private static String normalize(String value)
    {
        return value == null ? "" : value.toLowerCase(Locale.ENGLISH)
            .replace('\u2019', '\'').replaceAll("[^a-z0-9]+", " ").trim();
    }

    private static HttpUrl rawPagesUrl(List<String> titles)
    {
        return HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("titles", String.join("|", titles))
            .addQueryParameter("prop", "revisions|info")
            .addQueryParameter("rvprop", "content")
            .addQueryParameter("rvslots", "main")
            .addQueryParameter("inprop", "url")
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
    }

    private static Request request(HttpUrl url)
    {
        return new Request.Builder().url(url)
            .header("User-Agent", "GielinorGuide RuneLite plugin destination grounding")
            .build();
    }

    static String fuzzySearchQuery(String value)
    {
        String[] words = value.trim().split("\\s+");
        StringBuilder query = new StringBuilder();
        for (String word : words)
        {
            if (query.length() > 0)
            {
                query.append(' ');
            }
            query.append(word);
            if (word.replaceAll("[^A-Za-z0-9]", "").length() >= 5)
            {
                query.append('~');
            }
        }
        return query.toString();
    }

    private static int levenshtein(String left, String right)
    {
        int[] previous = new int[right.length() + 1];
        for (int j = 0; j <= right.length(); j++)
        {
            previous[j] = j;
        }
        for (int i = 1; i <= left.length(); i++)
        {
            int[] current = new int[right.length() + 1];
            current[0] = i;
            for (int j = 1; j <= right.length(); j++)
            {
                int replacement = previous[j - 1] +
                    (left.charAt(i - 1) == right.charAt(j - 1) ? 0 : 1);
                current[j] = Math.min(Math.min(current[j - 1] + 1,
                    previous[j] + 1), replacement);
            }
            previous = current;
        }
        return previous[right.length()];
    }

    private static final class DestinationCandidate
    {
        private final String title;
        private final int score;

        private DestinationCandidate(String title, int score)
        {
            this.title = title;
            this.score = score;
        }
    }

    public void cancel()
    {
        Call call = activeCall;
        if (call != null)
        {
            call.cancel();
        }
    }
}

package com.gielinorguide;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** Adds the selected Achievement Diary tier's task table to Wiki grounding. */
final class WikiDiaryExpander
{
    private static final String API_URL = "https://oldschool.runescape.wiki/api.php";
    private static final Pattern SCP = Pattern.compile(
        "(?i)\\{\\{SCP\\|([^|}]+)\\|([^|}]+)[^}]*}}");
    private static final Pattern BOOSTABLE = Pattern.compile(
        "(?i)\\{\\{Boostable\\|([yn])[^}]*}}");
    private final OkHttpClient httpClient;
    private final Gson gson;
    private volatile Call activeCall;

    WikiDiaryExpander(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    void expand(WikiResult base, String tier, Consumer<WikiResult> callback)
    {
        WikiSource primary = base.getPrimarySource();
        if (primary == null || tier == null || tier.isEmpty())
        {
            callback.accept(base);
            return;
        }
        Call call = httpClient.newCall(request(rawPageUrl(primary.getTitle())));
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    callback.accept(base);
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    if (!response.isSuccessful() || body == null)
                    {
                        callback.accept(base);
                        return;
                    }
                    WikiSource tasks = parse(primary.getTitle(), primary.getUrl(),
                        revisionContent(body.string()), tier);
                    callback.accept(tasks == null ? base : merge(base, tasks));
                }
                catch (IOException | RuntimeException exception)
                {
                    callback.accept(base);
                }
            }
        });
    }

    WikiSource parse(String title, String sourceUrl, String wikiText, String tier)
    {
        Pattern section = Pattern.compile("(?ims)^==\\s*" + Pattern.quote(tier) +
            "\\s*==\\s*(.*?)(?=^==\\s*(?:Easy|Medium|Hard|Elite)\\s*==|\\z)");
        Matcher matcher = section.matcher(wikiText == null ? "" : wikiText);
        if (!matcher.find())
        {
            return null;
        }
        String selected = matcher.group(1).replaceFirst(
            "(?ims)^===\\s*Rewards\\s*===.*$", "");
        String tasks = taskTable(selected);
        if (tasks.isEmpty())
        {
            return null;
        }
        return new WikiSource(title + " - " + tier + " tasks",
            sourceUrl.replaceFirst("#.*$", "") + "#" + tier,
            "Verified " + title + " " + tier + " task set and requirements:\n" + tasks);
    }

    void cancel()
    {
        Call call = activeCall;
        if (call != null)
        {
            call.cancel();
        }
    }

    private static String taskTable(String wikiText)
    {
        StringBuilder result = new StringBuilder();
        for (String rawLine : wikiText.split("\\r?\\n"))
        {
            String line = rawLine.trim();
            if (line.isEmpty() || line.startsWith("{|" ) || line.startsWith("|}") ||
                line.startsWith("!") || "|-".equals(line))
            {
                continue;
            }
            if (line.startsWith("|"))
            {
                line = line.substring(1).trim();
            }
            boolean requirement = line.startsWith("*");
            if (requirement)
            {
                line = line.replaceFirst("^\\*+", "- ");
            }
            line = plain(line);
            if (!line.isEmpty())
            {
                result.append(requirement ? "  " : "").append(line).append('\n');
            }
        }
        String value = result.toString().trim();
        return value.length() <= 10000 ? value : value.substring(0, 10000) + "...";
    }

    private static String plain(String value)
    {
        String text = SCP.matcher(value).replaceAll("$1 $2");
        Matcher boost = BOOSTABLE.matcher(text);
        StringBuffer withBoosts = new StringBuffer();
        while (boost.find())
        {
            boost.appendReplacement(withBoosts,
                "n".equalsIgnoreCase(boost.group(1)) ? "(not boostable)" : "(boostable)");
        }
        boost.appendTail(withBoosts);
        text = withBoosts.toString()
            .replaceAll("(?i)\\{\\{\\s*FloorNumber\\s*\\|\\s*uk\\s*=\\s*([0-9]+)[^}]*}}", "$1st floor")
            .replaceAll("(?is)\\[\\[File:[^]]+]]", " ")
            .replaceAll("\\[\\[[^|\\]]+\\|([^\\]]+)]]", "$1")
            .replaceAll("\\[\\[([^#|\\]]+)(?:#[^|\\]]*)?]]", "$1")
            .replaceAll("(?is)<ref\\b[^>]*>.*?</ref>|<ref\\b[^>]*/>", " ")
            .replaceAll("(?is)<[^>]+>", " ")
            .replace("'''", "").replace("''", "");
        String previous;
        do
        {
            previous = text;
            text = text.replaceAll("(?is)\\{\\{[^{}]{0,1000}}}", " ");
        }
        while (!text.equals(previous));
        return text.replaceAll("\\s+", " ").trim();
    }

    private String revisionContent(String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        if (pages == null || pages.size() == 0)
        {
            return "";
        }
        JsonArray revisions = pages.get(0).getAsJsonObject().getAsJsonArray("revisions");
        if (revisions == null || revisions.size() == 0)
        {
            return "";
        }
        JsonObject slots = revisions.get(0).getAsJsonObject().getAsJsonObject("slots");
        JsonObject main = slots == null ? null : slots.getAsJsonObject("main");
        return main == null || !main.has("content") ? "" : main.get("content").getAsString();
    }

    private static WikiResult merge(WikiResult base, WikiSource addition)
    {
        Map<String, WikiSource> sources = new LinkedHashMap<>();
        for (WikiSource source : base.getSources())
        {
            sources.put(source.getUrl(), source);
        }
        sources.put(addition.getUrl(), addition);
        return new WikiResult(new ArrayList<>(sources.values()), base.isAvailable());
    }

    private static HttpUrl rawPageUrl(String title)
    {
        return HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("titles", title)
            .addQueryParameter("prop", "revisions")
            .addQueryParameter("rvprop", "content")
            .addQueryParameter("rvslots", "main")
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
    }

    private static Request request(HttpUrl url)
    {
        return new Request.Builder().url(url)
            .header("User-Agent", "GielinorGuide RuneLite plugin diary grounding")
            .build();
    }
}

