    private WikiPageCatalog()
    {
    }

    public static Optional<String> matchQuestion(String question)
    {
        String normalized = normalize(question);
        String bestPage = null;
        int bestAliasLength = -1;
        for (Map.Entry<String, String> entry : ALIASES.entrySet())
        {
            String alias = entry.getKey();
            if (containsPhrase(normalized, alias) && alias.length() > bestAliasLength)
            {
                bestPage = entry.getValue();
                bestAliasLength = alias.length();
            }
        }
        return Optional.ofNullable(bestPage);
    }

    public static String canonicalizeSubject(String subject)
    {
        String normalized = normalize(subject);
        String exact = ALIASES.get(normalized);
        if (exact != null)
        {
            return exact;
        }
        return matchQuestion(subject).orElse(subject.trim());
    }

    public static boolean hasStrategyPage(String canonicalPage)
    {
        return STRATEGY_PAGES.containsKey(canonicalPage);
    }

    public static String strategyPage(String canonicalPage)
    {
        return STRATEGY_PAGES.get(canonicalPage);
    }

    static boolean isCanonicalPage(String page)
    {
        return pagesForSmokeCheck().contains(page);
    }

    static boolean isRaidStrategyPage(String page)
    {
        return "Chambers of Xeric/Strategies".equals(page) ||
            "Theatre of Blood/Strategies".equals(page) ||
            "Tombs of Amascut/Strategies".equals(page);
    }

    static boolean isQuestPage(String page)
    {
        return QUEST_PAGES.contains(page);
    }

    static String addPreferredSectionAnchor(String page, String url)
    {
        if ("Soulreaper axe".equals(page))
        {
            return url + "#Creation";
        }
        if ("Food/Fast foods".equals(page))
        {
            return url + "#Combo_eating";
        }
        if ("Slayer reward point".equals(page))
        {
            return url + "#Obtaining_points";
        }
        return "Slayer helmet".equals(page) ? url + "#Creation" : url;
    }

    static Set<String> pagesForSmokeCheck()
    {
        Set<String> pages = new LinkedHashSet<>(ALIASES.values());
        pages.addAll(STRATEGY_PAGES.values());
        pages.add("Armour/Magic armour");
        pages.add("Armour/Ranged armour");
        pages.add("Armour/Melee armour");
        for (String skill : new String[]{"Attack", "Strength", "Defence", "Ranged",
            "Prayer", "Magic", "Runecraft", "Construction", "Hitpoints", "Agility",
            "Herblore", "Thieving", "Crafting", "Fletching", "Slayer", "Hunter",
            "Mining", "Smithing", "Fishing", "Cooking", "Firemaking", "Woodcutting",
            "Farming", "Sailing"})
        {
            pages.add(skill + " training");
        }
        return pages;
    }

    private static void register(Map<String, String> aliases, String page, String... values)
    {
        for (String value : values)
        {
            aliases.put(normalize(value), page);
        }
    }

    private static boolean containsPhrase(String text, String phrase)
    {
        return (" " + text + " ").contains(" " + phrase + " ");
    }

    private static String normalize(String value)
    {
        return value == null ? "" : value.toLowerCase(Locale.ENGLISH)
            .replace('\u2019', '\'').replaceAll("[^a-z0-9]+", " ").trim();
    }
}

package com.gielinorguide;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

final class WikiPurposeExpander
{
    private static final String API_URL = "https://oldschool.runescape.wiki/api.php";
    private static final int MAX_LINKED_USES = 8;
    private static final Pattern USES_SECTION = Pattern.compile(
        "(?ims)^==\\s*(Uses|Charging|Recharging)\\s*==\\s*(.*?)(?=^==[^=].*?==\\s*$|\\z)");
    private static final Pattern PURPOSE_SECTION = Pattern.compile(
        "(?ims)^==\\s*(Destinations|Products|Creation|Upgrading)\\s*==\\s*(.*?)(?=^==[^=].*?==\\s*$|\\z)");
    private static final Pattern WIKI_LINK = Pattern.compile(
        "\\[\\[([^|#\\]]+)(?:#[^|\\]]*)?(?:\\|[^\\]]*)?\\]\\]");
    private static final Pattern PLINK = Pattern.compile(
        "(?i)\\{\\{\\s*plink\\s*\\|\\s*([^|}]+)[^}]*\\}\\}");

    private final OkHttpClient httpClient;
    private final Gson gson;
    private volatile Call activeCall;

    WikiPurposeExpander(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    void expand(WikiResult base, Consumer<WikiResult> callback)
    {
        WikiSource primary = base.getPrimarySource();
        if (primary == null)
        {
            callback.accept(base);
            return;
        }
        Call call = httpClient.newCall(request(rawPageUrl(primary.getTitle())));
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    callback.accept(base);
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    if (!response.isSuccessful() || body == null)
                    {
                        callback.accept(base);
                        return;
                    }
                    UsesGrounding uses = parseUses(primary.getTitle(), primary.getUrl(),
                        revisionContent(body.string()));
                    if (uses == null)
                    {
                        callback.accept(base);
                        return;
                    }
                    WikiResult withUses = merge(base, uses.source, new ArrayList<>());
                    if (uses.linkedPages.isEmpty())
                    {
                        callback.accept(withUses);
                    }
                    else
                    {
                        fetchLinkedUses(withUses, uses.linkedPages, callback);
                    }
                }
                catch (IOException | RuntimeException exception)
                {
                    callback.accept(base);
                }
            }
        });
    }

    UsesGrounding parseUses(String title, String sourceUrl, String wikiText)
    {
        String text = wikiText == null ? "" : wikiText;
        Matcher section = USES_SECTION.matcher(text);
        if (!section.find())
        {
            return parsePurposeOverview(title, sourceUrl, text);
        }
        String heading = section.group(1);
        String sectionText = section.group(2);
        Set<String> linkedPages = new LinkedHashSet<>();
        if ("Uses".equalsIgnoreCase(heading))
        {
            Matcher plinks = PLINK.matcher(sectionText);
            while (plinks.find() && linkedPages.size() < MAX_LINKED_USES)
            {
                linkedPages.add(plinks.group(1).trim());
            }
            Matcher links = WIKI_LINK.matcher(sectionText);
            while (links.find() && linkedPages.size() < MAX_LINKED_USES)
            {
                String linked = links.group(1).trim();
                if (!linked.isEmpty() && !linked.equalsIgnoreCase(title) &&
                    !linked.toLowerCase().startsWith("file:"))
                {
                    linkedPages.add(linked);
                }
            }
        }
        String plain = plain(sectionText);
        if (plain.length() > 2200)
        {
            plain = plain.substring(0, 2200) + "...";
        }
        WikiSource source = new WikiSource(title + " - " + heading,
            sourceUrl.replaceFirst("#.*$", "") + "#" + heading, plain);
        return new UsesGrounding(source, new ArrayList<>(linkedPages));
    }

    private UsesGrounding parsePurposeOverview(String title, String sourceUrl, String text)
    {
        int firstHeading = text.indexOf("==");
        String introduction = firstHeading < 0 ? text : text.substring(0, firstHeading);
        StringBuilder relevant = new StringBuilder(stripLeadingTemplates(introduction));
        Matcher sections = PURPOSE_SECTION.matcher(text);
        while (sections.find())
        {
            relevant.append('\n').append(sections.group(1)).append(":\n")
                .append(sections.group(2));
        }
        String raw = relevant.toString();
        String purpose = plain(raw);
        if (purpose.isEmpty())
        {
            return null;
        }
        if (purpose.length() > 2600)
        {
            purpose = purpose.substring(0, 2600) + "...";
        }
        Set<String> linkedPages = new LinkedHashSet<>();
        Matcher plinks = PLINK.matcher(raw);
        while (plinks.find() && linkedPages.size() < MAX_LINKED_USES)
        {
            linkedPages.add(plinks.group(1).trim());
        }
        Matcher links = WIKI_LINK.matcher(raw);
        while (links.find() && linkedPages.size() < MAX_LINKED_USES)
        {
            String linked = links.group(1).trim();
            if (!linked.isEmpty() && !linked.equalsIgnoreCase(title) &&
                !linked.toLowerCase().startsWith("file:"))
            {
                linkedPages.add(linked);
            }
        }
        WikiSource source = new WikiSource(title + " - Purpose",
            sourceUrl.replaceFirst("#.*$", ""), purpose);
        return new UsesGrounding(source, new ArrayList<>(linkedPages));
    }

    private static String plain(String text)
    {
        return text
            .replaceAll("(?is)<ref\\b[^>]*>.*?</ref>|<ref\\b[^>]*/>", " ")
            .replaceAll("(?i)\\{\\{\\s*plink\\s*\\|\\s*([^|}]+)[^}]*\\}\\}", "$1")
            .replaceAll("(?is)\\{\\{[^{}]{0,1000}\\}\\}", " ")
            .replaceAll("\\[\\[[^|\\]]+\\|([^\\]]+)\\]\\]", "$1")
            .replaceAll("\\[\\[([^\\]]+)\\]\\]", "$1")
            .replace("'''", "").replace("''", "")
            .replaceAll("(?m)^[*#:;]+\\s*", "- ")
            .replaceAll("\\s+", " ").trim();
    }

    private static String stripLeadingTemplates(String text)
    {
        String value = text == null ? "" : text.trim();
        while (value.startsWith("{{"))
        {
            int depth = 0;
            int end = -1;
            for (int i = 0; i + 1 < value.length(); i++)
            {
                String pair = value.substring(i, i + 2);
                if ("{{".equals(pair))
                {
                    depth++;
                    i++;
                }
                else if ("}}".equals(pair))
                {
                    depth--;
                    i++;
                    if (depth == 0)
                    {
                        end = i + 1;
                        break;
                    }
                }
            }
            if (end < 0)
            {
                break;
            }
            value = value.substring(end).trim();
        }
        return value;
    }

    void cancel()
    {
        Call call = activeCall;
        if (call != null)
        {
            call.cancel();
        }
    }

    private void fetchLinkedUses(WikiResult base, List<String> pages,
        Consumer<WikiResult> callback)
    {
        HttpUrl url = HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("titles", String.join("|", pages))
            .addQueryParameter("prop", "extracts|info")
            .addQueryParameter("explaintext", "1")
            .addQueryParameter("exintro", "1")
            .addQueryParameter("exchars", "700")
            .addQueryParameter("exlimit", Integer.toString(pages.size()))
            .addQueryParameter("inprop", "url")
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
        Call call = httpClient.newCall(request(url));
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    callback.accept(base);
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    callback.accept(!response.isSuccessful() || body == null ? base :
                        merge(base, null, sources(body.string())));
                }
                catch (IOException | RuntimeException exception)
                {
                    callback.accept(base);
                }
            }
        });
    }

    private List<WikiSource> sources(String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        List<WikiSource> sources = new ArrayList<>();
        if (pages != null)
        {
            for (JsonElement element : pages)
            {
                JsonObject page = element.getAsJsonObject();
                String title = string(page, "title");
                String url = string(page, "fullurl");
                String extract = string(page, "extract").replaceAll("\\s+", " ").trim();
                if (!title.isEmpty() && !url.isEmpty() && !extract.isEmpty())
                {
                    sources.add(new WikiSource(title, url, extract));
                }
            }
        }
        return sources;
    }

    private String revisionContent(String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        if (pages == null || pages.size() == 0)
        {
            return "";
        }
        JsonArray revisions = pages.get(0).getAsJsonObject().getAsJsonArray("revisions");
        if (revisions == null || revisions.size() == 0)
        {
            return "";
        }
        JsonObject slots = revisions.get(0).getAsJsonObject().getAsJsonObject("slots");
        JsonObject main = slots == null ? null : slots.getAsJsonObject("main");
        return main == null ? "" : string(main, "content");
    }

    private static WikiResult merge(WikiResult base, WikiSource useSource,
        List<WikiSource> relatedSources)
    {
        Map<String, WikiSource> merged = new LinkedHashMap<>();
        for (WikiSource source : base.getSources())
        {
            merged.put(source.getUrl(), source);
        }
        if (useSource != null)
        {
            merged.put(useSource.getUrl(), useSource);
        }
        for (WikiSource source : relatedSources)
        {
            merged.put(source.getUrl(), source);
        }
        return new WikiResult(new ArrayList<>(merged.values()), base.isAvailable());
    }

    private static HttpUrl rawPageUrl(String title)
    {
        return HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("titles", title)
            .addQueryParameter("prop", "revisions")
            .addQueryParameter("rvprop", "content")
            .addQueryParameter("rvslots", "main")
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
    }

    private static Request request(HttpUrl url)
    {
        return new Request.Builder().url(url)
            .header("User-Agent", "GielinorGuide RuneLite plugin purpose grounding")
            .build();
    }

    private static String string(JsonObject object, String name)
    {
        JsonElement value = object.get(name);
        return value == null || value.isJsonNull() ? "" : value.getAsString();
    }

    static final class UsesGrounding
    {
        private final WikiSource source;
        private final List<String> linkedPages;

        private UsesGrounding(WikiSource source, List<String> linkedPages)
        {
            this.source = source;
            this.linkedPages = linkedPages;
        }

        WikiSource getSource()
        {
            return source;
        }

        List<String> getLinkedPages()
        {
            return linkedPages;
        }
    }
}

package com.gielinorguide;

import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public final class WikiQueryPlanner
{
    private static final List<String> SKILLS = Arrays.asList(
        "attack", "strength", "defence", "ranged", "prayer", "magic",
        "runecraft", "construction", "hitpoints", "agility", "herblore",
        "thieving", "crafting", "fletching", "slayer", "hunter", "mining",
        "smithing", "fishing", "cooking", "firemaking", "woodcutting",
        "farming", "sailing");
    private static final Pattern ACQUISITION = Pattern.compile(
        "(?i)\\b(?:how|where)\\b.{0,24}?\\b(?:get|obtain|acquire|make|create|find|buy)\\b\\s+(.+)$");
    private static final Pattern UNLOCK = Pattern.compile(
        "(?i)\\bhow\\b.{0,24}?\\bunlock\\b\\s+(.+)$");
    private static final Pattern CHARGE_DIRECT = Pattern.compile(
        "(?i)\\b(?:charge|recharge|refill)\\b\\s+(?:up\\s+)?(?:(?:my|the|a|an)\\s+)?(.+)$");
    private static final Pattern CHARGES_FOR = Pattern.compile(
        "(?i)\\b(?:charges?|charging|recharging|refilling)\\b.{0,35}?" +
            "\\b(?:for|to|on|into)\\s+(?:(?:my|the|a|an)\\s+)?(.+)$");
    private static final Pattern QUEST_ACTION = Pattern.compile(
        "(?i)^(?:let'?s do|walk me through|help me (?:do|start|complete|finish)|" +
            "how (?:do|can|should) i (?:do|start|complete|finish))\\s+(?:the\\s+)?" +
            "(.+?)\\s+quest[?!.]*$");
    private static final Pattern QUEST_GUIDE = Pattern.compile(
        "(?i)^(?:give me\\s+)?(?:a\\s+)?(?:guide|walkthrough)(?:\\s+(?:for|to|of|on))?" +
            "\\s+(?:the\\s+)?(.+?)\\s+quest[?!.]*$");
    private static final Pattern GOAL_WALKTHROUGH = Pattern.compile(
        "(?i)^(?:walk me through|give me\\s+(?:a\\s+)?(?:guide|walkthrough)(?:\\s+(?:for|to|on))?)" +
            "\\s+(?:getting|obtaining|acquiring|making|creating|crafting|building|unlocking)" +
            "\\s+(.+?)[?!.]*$");
    private static final Pattern OPTIMIZED_GOAL = Pattern.compile(
        "(?i)^(?:what(?:'s|s| is)\\s+)?(?:the\\s+)?" +
            "(?:best|easiest|simplest|fastest|quickest|cheapest)\\s+way\\s+to\\s+" +
            "(.+?)[?!.]*$");
    private static final Pattern HELP_GOAL = Pattern.compile(
        "(?i)^(?:please\\s+)?(?:help me|can you help me)\\s+(?:to\\s+)?" +
            "(?:do|with|finish|complete|start|continue|prepare for|kill|fight|beat|defeat|" +
            "get to|go to|travel to|reach|get|obtain|acquire|make|create|craft|build|buy|" +
            "unlock|farm)\\s+(.+?)[?!.]*$");
    private static final Pattern DIARY_TIER = Pattern.compile(
        "(?i)\\b(easy|medium|hard|elite)\\b");
    private static final Map<String, String> DIARY_AREAS = diaryAreas();

    private WikiQueryPlanner()
    {
    }

    public static String plan(String question)
    {
        String compact = question == null ? "" : question.replace('\u2019', '\'')
            .replaceAll("\\s+", " ").trim();
        String normalized = normalize(compact);

        String diaryPage = achievementDiaryPage(compact);
        if (diaryPage != null)
        {
            return diaryPage;
        }

        // A specifically named master is stronger intent than the generic
        // phrase "Slayer master" elsewhere in the same question.
        if (containsPhrase(normalized, "mortimer"))
        {
            return "Mortimer";
        }

        String equipmentPage = genericEquipmentPage(normalized);
        if (equipmentPage != null)
        {
            return equipmentPage;
        }

        String chargingSubject = chargingSubject(compact);
        if (chargingSubject != null)
        {
            return WikiPageCatalog.canonicalizeSubject(chargingSubject);
        }

        if (isTrainingQuestion(normalized))
        {
            for (String skill : SKILLS)
            {
                if (containsPhrase(normalized, skill) ||
                    ("runecraft".equals(skill) && containsPhrase(normalized, "runecrafting")) ||
                    ("ranged".equals(skill) && containsPhrase(normalized, "range")) ||
                    ("defence".equals(skill) && containsPhrase(normalized, "defense")))
                {
                    return capitalize(skill) + " training";
                }
            }
        }

        Optional<String> catalogPage = WikiPageCatalog.matchQuestion(compact);
        if (catalogPage.isPresent())
        {
            String page = catalogPage.get();
            return isStrategyQuestion(normalized) && WikiPageCatalog.hasStrategyPage(page)
                ? WikiPageCatalog.strategyPage(page) : page;
        }

        String questSubject = questWalkthroughSubject(compact);
        if (questSubject != null)
        {
            return WikiPageCatalog.canonicalizeSubject(questSubject);
        }

        String optimizedGoalSubject = matchedGoalSubject(OPTIMIZED_GOAL, compact, true);
        if (optimizedGoalSubject != null)
        {
            return optimizedGoalSubject;
        }

        String helpGoalSubject = matchedGoalSubject(HELP_GOAL, compact, false);
        if (helpGoalSubject != null)
        {
            return helpGoalSubject;
        }

        Matcher goalWalkthrough = GOAL_WALKTHROUGH.matcher(compact);
        if (goalWalkthrough.find())
        {
            return cleanSubject(goalWalkthrough.group(1));
        }

        Matcher acquisition = ACQUISITION.matcher(compact);
        if (acquisition.find())
        {
            return cleanSubject(acquisition.group(1));
        }
        Matcher unlock = UNLOCK.matcher(compact);
        if (unlock.find())
        {
            return cleanSubject(unlock.group(1));
        }
        return compact;
    }

    static boolean isCanonicalPageQuery(String query)
    {
        if (isAchievementDiaryQuery(query))
        {
            return true;
        }
        if (query != null && query.toLowerCase(Locale.ENGLISH).startsWith("slayer task/"))
        {
            return true;
        }
        if (WikiPageCatalog.isCanonicalPage(query))
        {
            return true;
        }
        String normalized = normalize(query);
        for (String skill : SKILLS)
        {
            if (normalized.equals(skill + " training"))
            {
                return true;
            }
        }
        return false;
    }

    static boolean isAcquisitionQuestion(String question)
    {
        String normalized = normalize(question);
        return !normalized.matches(".*\\bget to\\b.*") &&
            (normalized.matches(".*\\b(?:get|getting|obtain|obtaining|acquire|acquiring|make|making|" +
                    "create|creating|craft|crafting|build|building|buy|unlock|unlocking)\\b.*") ||
                normalized.matches(".*\\bwhat drops\\b.*") ||
                normalized.matches(".*\\bwhere.+(?:from|drop)\\b.*"));
    }

    static boolean isGoalWalkthroughQuestion(String question)
    {
        return question != null && GOAL_WALKTHROUGH.matcher(
            question.replace('\u2019', '\'').replaceAll("\\s+", " ").trim()).find();
    }

    static boolean isReferentialFollowUp(String question)
    {
        String normalized = normalize(question);
        return normalized.matches(".*\\b(?:those|them|these)\\b.*") ||
            normalized.matches(".*\\bfor (?:that|this)$") ||
            normalized.matches(".*\\b(?:this|next|remaining) (?:achievement )?(?:diary )?tasks?\\b.*") ||
            normalized.matches(".*\\b(?:those|these) (?:pieces|items|components|ingredients)\\b.*") ||
            normalized.matches(".*\\b(?:each|every) (?:piece|item|component|ingredient|one)\\b.*") ||
            normalized.matches("^(?:and )?(?:what|where|how|which|why)\\b.*\\b(?:it|that one)\\b.*") ||
            normalized.matches("^(?:and )?which\\b.*\\bshould i\\b.*\\b(?:first|next)$") ||
            normalized.matches("^(?:and )?what should i (?:do|work on) (?:first|next)$") ||
            normalized.matches("^(?:please )?(?:can you )?help me (?:do|with|finish|complete|start|continue) " +
                "(?:this|that|it|this one|that one)$") ||
            normalized.matches("^(?:what(?: s|s| is) )?(?:the )?(?:best|easiest|simplest|fastest|quickest|cheapest) " +
                "way to (?:do|finish|complete|continue) (?:this|that|it|this one|that one)$") ||
            normalized.matches("^(?:please )?walk me through (?:this|that|it|this one|that one)$") ||
            normalized.matches("^how (?:do|can|should) i (?:do|finish|complete|continue) " +
                "(?:this|that|it|this one|that one)$");
    }

    static boolean isGoalAssistanceQuestion(String question)
    {
        String compact = question == null ? "" : question.replace('\u2019', '\'')
            .replaceAll("\\s+", " ").trim();
        return OPTIMIZED_GOAL.matcher(compact).find() || HELP_GOAL.matcher(compact).find();
    }

    static boolean isPurposeQuestion(String question)
    {
        String normalized = normalize(question);
        return normalized.matches(".*\\bwhat (?:is|are).+\\bfor\\b.*") ||
            normalized.matches(".*\\bwhat.+\\bused for\\b.*") ||
            normalized.matches(".*\\bhow (?:do|can|should) i use\\b.*") ||
            normalized.matches(".*\\bwhy (?:do|would|should) i (?:want|need|keep|use)\\b.*") ||
            normalized.matches(".*\\bshould i keep\\b.*") ||
            normalized.matches(".*\\bwhat can i do with\\b.*");
    }

    static boolean isChargingQuestion(String question)
    {
        String normalized = normalize(question);
        return normalized.matches(".*\\b(?:charge|charges|charging|recharge|recharging|" +
            "refill|refilling)\\b.*");
    }

    static boolean isComparisonQuestion(String question)
    {
        String normalized = normalize(question);
        return normalized.matches(".*\\b(?:best|easiest|simplest|fastest|quickest|cheapest|lowest effort|least effort)\\b.*") &&
            !isTrainingQuestion(normalized) &&
            !normalized.matches(".*\\b(?:route|travel|get to|go to|reach)\\b.*");
    }

    static boolean isQuestRequirementQuestion(String question)
    {
        String normalized = normalize(question);
        return normalized.matches(".*\\b(?:quest|requirements?|reqs?|skills?|stats?|levels?)\\b.*") &&
            normalized.matches(".*\\b(?:need|require|requirements?|reqs?|skills?|stats?|levels?|ready|start|complete|finish)\\b.*");
    }

    static boolean isQuestReadinessQuestion(String question, String plannedQuery)
    {
        if (!WikiPageCatalog.isQuestPage(plannedQuery))
        {
            return false;
        }
        String normalized = normalize(question);
        boolean readinessLanguage = normalized.matches(
            ".*\\b(?:ready|prepare|preparing|preparation|requirements?|reqs?|need|missing|" +
                "before|first|work on|train|training)\\b.*");
        boolean broadGuidance = normalized.matches(
            ".*\\bwhat should i do (?:for|about|with)\\b.*");
        return (readinessLanguage || broadGuidance) &&
            !isQuestWalkthroughQuestion(question, plannedQuery);
    }

    static boolean isQuestWalkthroughQuestion(String question, String plannedQuery)
    {
        if (!WikiPageCatalog.isQuestPage(plannedQuery) &&
            questWalkthroughSubject(question) == null)
        {
            return false;
        }
        String normalized = normalize(question);
        return normalized.matches(".*\\b(?:walkthrough|guide|start|begin|complete|finish)\\b.*") ||
            normalized.matches(".*\\bwalk me through\\b.*") ||
            normalized.matches(".*\\b(?:lets|let s) do\\b.*") ||
            normalized.matches(".*\\bhow (?:do|can|should) i (?:do|start|complete|finish)\\b.*") ||
            normalized.matches(".*\\bhelp me (?:do|with|start|complete|finish)\\b.*");
    }

    static boolean isAchievementDiaryQuestion(String question, String plannedQuery)
    {
        return isAchievementDiaryQuery(plannedQuery) || achievementDiaryPage(question) != null;
    }

    static boolean isAchievementDiaryWalkthroughQuestion(String question,
        String plannedQuery)
    {
        if (!isAchievementDiaryQuestion(question, plannedQuery))
        {
            return false;
        }
        String normalized = normalize(question);
        return normalized.matches(".*\\b(?:walkthrough|guide|help|start|begin|do|complete|finish|next)\\b.*") ||
            normalized.matches(".*\\bwalk me through\\b.*");
    }

    static boolean isAchievementDiaryQuery(String query)
    {
        String title = stripSection(query);
        return "Achievement Diary".equalsIgnoreCase(title) ||
            title.toLowerCase(Locale.ENGLISH).endsWith(" diary");
    }

    static String achievementDiaryTier(String questionOrQuery)
    {
        if (questionOrQuery == null)
        {
            return "";
        }
        int anchor = questionOrQuery.indexOf('#');
        String value = anchor >= 0 ? questionOrQuery.substring(anchor + 1) : questionOrQuery;
        Matcher matcher = DIARY_TIER.matcher(value);
        return matcher.find() ? capitalize(matcher.group(1).toLowerCase(Locale.ENGLISH)) : "";
    }

    static String achievementDiaryHelperName(String query)
    {
        String title = stripSection(query);
        String tier = achievementDiaryTier(query);
        if ("Achievement Diary".equalsIgnoreCase(title))
        {
            return tier.isEmpty() ? "an achievement diary" : tier + " achievement diaries";
        }
        String area = title.replaceFirst("(?i)\\s+Diary$", "");
        return tier.isEmpty() ? area + " achievement diary" : area + " " + tier;
    }

    static String stripSection(String query)
    {
        if (query == null)
        {
            return "";
        }
        int anchor = query.indexOf('#');
        return (anchor < 0 ? query : query.substring(0, anchor)).trim();
    }

    private static String questWalkthroughSubject(String question)
    {
        String compact = question == null ? "" : question.replace('\u2019', '\'')
            .replaceAll("\\s+", " ").trim();
        for (Pattern pattern : Arrays.asList(QUEST_ACTION, QUEST_GUIDE))
        {
            Matcher matcher = pattern.matcher(compact);
            if (matcher.find())
            {
                return matcher.group(1).trim();
            }
        }
        return null;
    }

    static boolean isSkillTrainingQuestion(String question)
    {
        return isTrainingQuestion(normalize(question));
    }

    static boolean isAccessQuestion(String question)
    {
        String normalized = normalize(question);
        return normalized.matches(".*\\b(?:get to|get there|go to|go there|route there|" +
            "directions there|reach|enter|entrance|access|shortcut|shortcuts|unlock|" +
            "unlocked|grapple)\\b.*");
    }

    static boolean isContextualSubjectFollowUp(String question)
    {
        String normalized = normalize(question);
        return isReferentialFollowUp(question) ||
            normalized.matches(".*\\b(?:this|that|these|those)\\s+(?:[a-z0-9]+\\s+){0,3}" +
            "(?:shortcut|shortcuts|item|items|quest|quests|route|routes|option|options|" +
            "method|methods|teleport|teleports|spell|spells|prayer|prayers|weapon|weapons|" +
            "armour|armor|gear|boss|monster|location|requirement|skill)\\b.*");
    }

    static boolean needsSemanticPlanning(String question, String plannedQuery)
    {
        if (question == null || question.trim().split("\\s+").length < 3)
        {
            return false;
        }
        if (isContextualSubjectFollowUp(question))
        {
            return true;
        }
        if (isGoalAssistanceQuestion(question) &&
            normalize(question).equals(normalize(plannedQuery)))
        {
            return true;
        }
        if (isAcquisitionQuestion(question) || isPurposeQuestion(question) ||
            isChargingQuestion(question) ||
            isComparisonQuestion(question) || isQuestRequirementQuestion(question) ||
            isQuestReadinessQuestion(question, plannedQuery) ||
            isQuestWalkthroughQuestion(question, plannedQuery) ||
            isAchievementDiaryQuestion(question, plannedQuery) ||
            isSkillTrainingQuestion(question) || isSlayerProgressionQuery(plannedQuery) ||
            (plannedQuery != null && plannedQuery.toLowerCase(Locale.ENGLISH)
                .startsWith("slayer task/")))
        {
            return false;
        }
        return true;
    }

    static boolean isSlayerProgressionQuery(String query)
    {
        return "Slayer Master".equals(query) || "Slayer reward point".equals(query) ||
            "Slayer training".equals(query) || "Slayer helmet".equals(query) ||
            "Mortimer".equals(query);
    }

    static boolean isSemanticQuerySupportedByQuestion(String question, String query)
    {
        String normalizedQuestion = normalize(question);
        String normalizedQuery = normalize(query);
        if (normalizedQuestion.isEmpty() || normalizedQuery.isEmpty())
        {
            return false;
        }
        if (containsPhrase(normalizedQuestion, normalizedQuery))
        {
            return true;
        }
        for (String word : normalizedQuery.split(" "))
        {
            if (word.length() >= 3 &&
                !word.matches("guide|guides|strategy|strategies|training|quest|quests|" +
                    "old|school|runescape|osrs|wiki|page|the|and|for|from|with") &&
                containsPhrase(normalizedQuestion, word))
            {
                return true;
            }
        }
        return false;
    }

    static boolean isSemanticQuerySupportedByConversation(String question,
        List<GuideMessage> history, String query)
    {
        if (isSemanticQuerySupportedByQuestion(question, query))
        {
            return true;
        }
        if (!isContextualSubjectFollowUp(question))
        {
            return false;
        }
        int start = Math.max(0, history.size() - 6);
        for (int i = history.size() - 1; i >= start; i--)
        {
            if (isSemanticQuerySupportedByQuestion(history.get(i).getText(), query))
            {
                return true;
            }
        }
        return false;
    }

    private static boolean isTrainingQuestion(String normalized)
    {
        return normalized.matches(".*\\b(?:level|lvl|train|training|xp|experience)\\b.*") &&
            (normalized.matches(".*\\b(?:best|fastest|quickest|cheapest|afk|efficient|way|method)\\b.*") ||
                normalized.matches(".*\\b(?:level|lvl|train)\\b.*"));
    }

    private static String cleanSubject(String value)
    {
        String subject = value.replaceAll("[?!.]+$", "").trim()
            .replaceFirst("(?i)^(?:a|an|the|my)\\s+", "")
            .replaceFirst("(?i)\\s+(?:in|on)\\s+(?:old school runescape|osrs)\\s*$", "")
            .trim();
        return WikiPageCatalog.canonicalizeSubject(subject);
    }

    private static String matchedGoalSubject(Pattern pattern, String question,
        boolean stripAction)
    {
        Matcher matcher = pattern.matcher(question);
        if (!matcher.find())
        {
            return null;
        }
        String value = matcher.group(1).trim();
        if (stripAction)
        {
            value = value.replaceFirst(
                "(?i)^(?:prepare for|get to|go to|travel to|do|finish|complete|start|continue|" +
                    "kill|fight|beat|defeat|reach|get|obtain|acquire|make|create|craft|build|" +
                    "buy|unlock|farm)\\s+(?:the\\s+)?", "");
        }
        String normalized = normalize(value);
        if (normalized.matches("(?:this|that|it|this one|that one)"))
        {
            return null;
        }
        return cleanSubject(value);
    }

    private static String chargingSubject(String question)
    {
        for (Pattern pattern : Arrays.asList(CHARGE_DIRECT, CHARGES_FOR))
        {
            Matcher matcher = pattern.matcher(question);
            if (matcher.find())
            {
                return cleanSubject(matcher.group(1));
            }
        }
        return null;
    }

    private static String achievementDiaryPage(String question)
    {
        String normalized = normalize(question);
        boolean diaryLanguage = normalized.matches(".*\\b(?:achievement )?diar(?:y|ies)\\b.*");
        boolean taskSetLanguage = DIARY_TIER.matcher(normalized).find() &&
            normalized.matches(".*\\b(?:task|tasks|set)\\b.*");
        if (!diaryLanguage && !taskSetLanguage)
        {
            return null;
        }

        String areaPage = null;
        int longest = -1;
        for (Map.Entry<String, String> entry : DIARY_AREAS.entrySet())
        {
            if (containsPhrase(normalized, entry.getKey()) && entry.getKey().length() > longest)
            {
                areaPage = entry.getValue() + " Diary";
                longest = entry.getKey().length();
            }
        }
        String page = areaPage == null ? "Achievement Diary" : areaPage;
        if (areaPage == null && normalized.matches(".*\\b(?:this|a|the|one) " +
            "(?:achievement )?diary task\\b.*"))
        {
            return null;
        }
        String tier = achievementDiaryTier(question);
        return tier.isEmpty() ? page : page + "#" + tier;
    }

    private static Map<String, String> diaryAreas()
    {
        Map<String, String> areas = new LinkedHashMap<>();
        areas.put("ardougne", "Ardougne");
        areas.put("ardy", "Ardougne");
        areas.put("desert", "Desert");
        areas.put("falador", "Falador");
        areas.put("fally", "Falador");
        areas.put("fremennik province", "Fremennik");
        areas.put("fremennik", "Fremennik");
        areas.put("kandarin", "Kandarin");
        areas.put("karamja", "Karamja");
        areas.put("kourend and kebos", "Kourend & Kebos");
        areas.put("kourend kebos", "Kourend & Kebos");
        areas.put("kourend", "Kourend & Kebos");
        areas.put("lumbridge and draynor", "Lumbridge & Draynor");
        areas.put("lumbridge draynor", "Lumbridge & Draynor");
        areas.put("lumbridge", "Lumbridge & Draynor");
        areas.put("lumby", "Lumbridge & Draynor");
        areas.put("morytania", "Morytania");
        areas.put("varrock", "Varrock");
        areas.put("western provinces", "Western Provinces");
        areas.put("western", "Western Provinces");
        areas.put("wilderness", "Wilderness");
        areas.put("wildy", "Wilderness");
        return areas;
    }

    private static boolean isStrategyQuestion(String normalized)
    {
        return normalized.matches(".*\\b(?:kill|fight|beat|defeat|boss|gear|setup|strategy|mechanics|" +
            "prepare|preparation|prep|ready|requirements?)\\b.*") ||
            normalized.matches(".*\\bwhat (?:do|would) i need\\b.*") ||
            normalized.matches(".*\\bwhat should i do\\b.*\\b(?:raid|content)\\b.*");
    }

    private static String genericEquipmentPage(String normalized)
    {
        if (!normalized.matches(".*\\b(?:gear|armour|armor|equipment|setup)\\b.*"))
        {
            return null;
        }
        if (normalized.matches(".*\\b(?:magic|mage)\\b.*"))
        {
            return "Armour/Magic armour";
        }
        if (normalized.matches(".*\\b(?:ranged|range)\\b.*"))
        {
            return "Armour/Ranged armour";
        }
        if (normalized.matches(".*\\b(?:melee|strength|attack)\\b.*"))
        {
            return "Armour/Melee armour";
        }
        return null;
    }

    private static boolean containsPhrase(String text, String phrase)
    {
        return Pattern.compile("(^| )" + Pattern.quote(phrase) + "( |$)")
            .matcher(text).find();
    }

    private static String capitalize(String value)
    {
        return Character.toUpperCase(value.charAt(0)) + value.substring(1);
    }

    private static String normalize(String value)
    {
        return value.toLowerCase(Locale.ENGLISH).replaceAll("[^a-z0-9]+", " ").trim();
    }
}

package com.gielinorguide;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** Extracts requirements and required items from a quest's live Quest details template. */
final class WikiQuestRequirementExpander
{
    private static final String API_URL = "https://oldschool.runescape.wiki/api.php";
    private static final Pattern FIELD = Pattern.compile(
        "(?ims)^\\|\\s*(requirements|items)\\s*=\\s*(.*?)(?=^\\|\\s*[a-zA-Z][a-zA-Z0-9]*\\s*=|^}}|\\z)");
    private static final Pattern SKILL = Pattern.compile(
        "(?i)\\{\\{\\s*SCP\\s*\\|\\s*([^|}]+)\\s*\\|\\s*([^|}]+)[^}]*}}");
    private static final Pattern LINK_WITH_LABEL = Pattern.compile(
        "\\[\\[[^|\\]]+\\|([^\\]]+)]]");
    private static final Pattern LINK = Pattern.compile("\\[\\[([^#|\\]]+)(?:#[^|\\]]*)?]]");

    private final OkHttpClient httpClient;
    private final Gson gson;
    private volatile Call activeCall;

    WikiQuestRequirementExpander(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    void expand(WikiResult base, Consumer<WikiResult> callback)
    {
        WikiSource primary = base.getPrimarySource();
        if (primary == null)
        {
            callback.accept(base);
            return;
        }
        expandPage(base, primary.getTitle(), primary.getUrl(), callback);
    }

    void expandPage(WikiResult base, String title, String sourceUrl,
        Consumer<WikiResult> callback)
    {
        Call call = httpClient.newCall(request(rawPageUrl(title)));
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    callback.accept(base);
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    if (!response.isSuccessful() || body == null)
                    {
                        callback.accept(base);
                        return;
                    }
                    WikiSource requirements = parse(title, sourceUrl,
                        revisionContent(body.string()));
                    callback.accept(requirements == null ? base : merge(base, requirements));
                }
                catch (IOException | RuntimeException exception)
                {
                    callback.accept(base);
                }
            }
        });
    }

    WikiSource parse(String title, String sourceUrl, String wikiText)
    {
        Matcher fields = FIELD.matcher(wikiText == null ? "" : wikiText);
        Map<String, String> values = new LinkedHashMap<>();
        while (fields.find())
        {
            values.put(fields.group(1).toLowerCase(), plain(fields.group(2)));
        }
        String requirements = values.get("requirements");
        if (requirements == null || requirements.isEmpty())
        {
            return null;
        }
        StringBuilder excerpt = new StringBuilder("Verified quest requirements:\n")
            .append(requirements);
        String items = values.get("items");
        if (items != null && !items.isEmpty())
        {
            excerpt.append("\nVerified required items:\n").append(items);
        }
        return new WikiSource(title + " - Requirements",
            sourceUrl.replaceFirst("#.*$", "") + "#Details", excerpt.toString());
    }

    void cancel()
    {
        Call call = activeCall;
        if (call != null)
        {
            call.cancel();
        }
    }

    private String revisionContent(String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        if (pages == null || pages.size() == 0)
        {
            return "";
        }
        JsonArray revisions = pages.get(0).getAsJsonObject().getAsJsonArray("revisions");
        if (revisions == null || revisions.size() == 0)
        {
            return "";
        }
        JsonObject slots = revisions.get(0).getAsJsonObject().getAsJsonObject("slots");
        JsonObject main = slots == null ? null : slots.getAsJsonObject("main");
        return main == null ? "" : string(main, "content");
    }

    private static String plain(String wikiText)
    {
        Matcher skills = SKILL.matcher(wikiText);
        StringBuffer replacedSkills = new StringBuffer();
        while (skills.find())
        {
            skills.appendReplacement(replacedSkills, Matcher.quoteReplacement(
                skills.group(2).trim() + " " + skills.group(1).trim()));
        }
        skills.appendTail(replacedSkills);
        String text = replacedSkills.toString()
            .replaceAll("(?i)\\{\\{\\s*Boostable\\s*\\|\\s*no\\s*}}", " (not boostable)")
            .replaceAll("(?i)\\{\\{\\s*Boostable\\s*\\|\\s*yes\\s*}}", " (boostable)")
            .replaceAll("(?i)\\{\\{\\s*Questreqstart\\s*\\|\\s*yes\\s*}}", " (required to start)");
        text = LINK_WITH_LABEL.matcher(text).replaceAll("$1");
        text = LINK.matcher(text).replaceAll("$1");
        text = text.replaceAll("(?is)<ref\\b[^>]*>.*?</ref>|<ref\\b[^>]*/>", "")
            .replaceAll("(?is)\\{\\{[^{}]{0,1000}}}", "")
            .replace("'''", "").replace("''", "")
            .replaceAll("(?m)^\\*+\\s*", "- ")
            .replaceAll("[ \\t]+", " ")
            .replaceAll(" *\\r?\\n *", "\n")
            .replaceAll("\\n{2,}", "\n").trim();
        return text.length() <= 3000 ? text : text.substring(0, 3000) + "...";
    }

    private static WikiResult merge(WikiResult base, WikiSource addition)
    {
        Map<String, WikiSource> sources = new LinkedHashMap<>();
        for (WikiSource source : base.getSources())
        {
            sources.put(source.getUrl(), source);
        }
        sources.put(addition.getUrl(), addition);
        return new WikiResult(new ArrayList<>(sources.values()), base.isAvailable());
    }

    private static HttpUrl rawPageUrl(String title)
    {
        return HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("titles", title)
            .addQueryParameter("prop", "revisions")
            .addQueryParameter("rvprop", "content")
            .addQueryParameter("rvslots", "main")
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
    }

    private static Request request(HttpUrl url)
    {
        return new Request.Builder().url(url)
            .header("User-Agent", "GielinorGuide RuneLite plugin quest grounding")
            .build();
    }

    private static String string(JsonObject object, String name)
    {
        JsonElement value = object.get(name);
        return value == null || value.isJsonNull() ? "" : value.getAsString();
    }
}

package com.gielinorguide;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class WikiResult
{
    private final List<WikiSource> sources;
    private final List<VerifiedLocation> destinations;
    private final boolean available;

    public WikiResult(List<WikiSource> sources, boolean available)
    {
        this(sources, available, Collections.emptyList());
    }

    public WikiResult(List<WikiSource> sources, boolean available,
        List<VerifiedLocation> destinations)
    {
        this.sources = Collections.unmodifiableList(new ArrayList<>(sources));
        this.destinations = Collections.unmodifiableList(new ArrayList<>(destinations));
        this.available = available;
    }

    public static WikiResult unavailable()
    {
        return new WikiResult(Collections.emptyList(), false);
    }

    public List<WikiSource> getSources()
    {
        return sources;
    }

    public List<VerifiedLocation> getDestinations()
    {
        return destinations;
    }

    /** The canonical page returned by MediaWiki, after redirects are resolved. */
    public WikiSource getPrimarySource()
    {
        return sources.isEmpty() ? null : sources.get(0);
    }

    public boolean isAvailable()
    {
        return available;
    }

    public String asGroundingText()
    {
        if (!available)
        {
            return "The OSRS Wiki lookup failed. Do not state specific facts unless they are in the verified location catalog; clearly say when you cannot verify something.";
        }
        if (sources.isEmpty())
        {
            return "The OSRS Wiki search returned no useful pages. Do not guess; clearly state what could not be verified.";
        }

        StringBuilder result = new StringBuilder();
        for (WikiSource source : sources)
        {
            result.append("SOURCE: ").append(source.getTitle()).append('\n')
                .append("URL: ").append(source.getUrl()).append('\n')
                .append("EXCERPT: ").append(source.getExcerpt()).append("\n\n");
        }
        return result.toString();
    }
}

package com.gielinorguide;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.coords.WorldPoint;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** Adds verified combat and location-comparison sections from a Slayer task page. */
final class WikiSlayerTaskExpander
{
    private static final String API_URL = "https://oldschool.runescape.wiki/api.php";
    private static final int MAX_RELATED_PAGES = 6;
    private static final Pattern SECTION = Pattern.compile(
        "(?ims)^==\\s*(Location Comparisons?|Locations|Safespots)\\s*==\\s*(.*?)(?=^==[^=].*?==\\s*$|\\z)");
    private static final Pattern MONSTER_VARIANTS = Pattern.compile(
        "(?ims)^==\\s*Monster variants\\s*==\\s*(.*?)(?=^==[^=].*?==\\s*$|\\z)");
    private static final Pattern STRENGTHS = Pattern.compile(
        "(?ims)^==\\s*Strengths and weaknesses\\s*==\\s*(.*?)(?=^==[^=].*?==\\s*$|\\z)");
    private static final Pattern TRANSPORTATION = Pattern.compile(
        "(?ims)^==\\s*(?:Transportation|Getting there)\\s*==\\s*(.*?)(?=^==[^=].*?==\\s*$|\\z)");
    private static final Pattern LAYOUT = Pattern.compile(
        "(?ims)^==\\s*Layout\\s*==\\s*(.*?)(?=^==[^=].*?==\\s*$|\\z)");
    private static final Pattern WIKI_LINK = Pattern.compile(
        "\\[\\[([^|#\\]]+)(?:#[^|\\]]*)?(?:\\|[^\\]]*)?]]");
    private static final Pattern RECOMMENDED_TARGET_LINK = Pattern.compile(
        "(?is)recommended to (?:kill|fight|attack)\\s+(?:an?\\s+)?" +
            "\\[\\[([^|#\\]]+)(?:#[^|\\]]*)?(?:\\|[^\\]]*)?]]");
    private static final Pattern ALTERNATIVE_LOCATION_LINK = Pattern.compile(
        "(?is)(?:the\\s+)?\\[\\[([^|#\\]]+)(?:#[^|\\]]*)?(?:\\|[^\\]]*)?]]" +
            "\\s+is\\s+(?:an?\\s+)?(?:second\\s+)?alternative");
    private static final Pattern TABLE_LOCATION = Pattern.compile(
        "(?m)^\\|\\s*\\[\\[([^|#\\]]+)(?:#[^|\\]]*)?(?:\\|([^\\]]+))?]]\\s*([^\\r\\n]*)");
    private static final Pattern INFOBOX_FIELD = Pattern.compile(
        "(?im)^\\|\\s*(attack style|elementalweaknesstype|elementalweaknesspercent|" +
            "max hit|attributes|slaylvl|def|mage|dstab|dslash|dcrush|dmagic|" +
            "dlight|dstandard|dheavy)(?:[0-9]+)?\\s*=\\s*(.+)$");
    private static final Pattern MONSTER_PAGE = Pattern.compile(
        "(?is)\\{\\{\\s*Infobox\\s+Monster\\b");
    private static final Pattern MAP_TEMPLATE = Pattern.compile(
        "(?is)\\{\\{\\s*Map\\b.*?}}\\s*");

    private final OkHttpClient httpClient;
    private final Gson gson;
    private volatile Call activeCall;

    WikiSlayerTaskExpander(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    void expand(WikiResult base, Consumer<WikiResult> callback)
    {
        WikiSource primary = base.getPrimarySource();
        if (primary == null)
        {
            callback.accept(base);
            return;
        }
        Call call = httpClient.newCall(request(rawPageUrl(primary.getTitle())));
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    callback.accept(base);
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    if (!response.isSuccessful() || body == null)
                    {
                        callback.accept(base);
                        return;
                    }
                    String wikiText = revisionContent(body.string());
                    WikiSource detail = parse(primary.getTitle(), primary.getUrl(), wikiText);
                    WikiResult expanded = merge(base, detail,
                        objectiveLocations(primary.getUrl(), wikiText));
                    List<String> relatedPages = relatedPages(wikiText);
                    if (relatedPages.isEmpty())
                    {
                        callback.accept(expanded);
                    }
                    else
                    {
                        fetchRelatedPages(expanded, relatedPages, callback);
                    }
                }
                catch (IOException | RuntimeException exception)
                {
                    callback.accept(base);
                }
            }
        });
    }

    WikiSource parse(String title, String sourceUrl, String wikiText)
    {
        String text = wikiText == null ? "" : wikiText;
        StringBuilder details = new StringBuilder();
        int firstSection = text.indexOf("==Slayer Unlocks==");
        if (firstSection > 0)
        {
            String introduction = afterNamedTemplate(
                text.substring(0, firstSection), "Infobox Slayer");
            details.append("Verified task combat guidance:\n")
                .append(plain(introduction));
        }
        else
        {
            WikiSource monster = parseMonsterPage(title, sourceUrl, text);
            if (monster != null)
            {
                details.append(monster.getExcerpt());
            }
        }
        Matcher sections = SECTION.matcher(text);
        while (sections.find())
        {
            String sectionText = plain(sections.group(2));
            if (!sectionText.isEmpty())
            {
                details.append("\nVerified ").append(sections.group(1)).append(":\n")
                    .append(sectionText);
            }
        }
        Matcher variants = MONSTER_VARIANTS.matcher(text);
        if (variants.find())
        {
            String sectionText = plain(variants.group(1));
            if (!sectionText.isEmpty())
            {
                details.append("\nVerified monster variants:\n").append(sectionText);
            }
        }
        if (details.length() == 0)
        {
            return null;
        }
        String excerpt = details.length() <= 6500 ? details.toString() :
            details.substring(0, 6500) + "...";
        return new WikiSource(title + " - Combat and location comparison",
            sourceUrl.replaceFirst("#.*$", "") + "#Location_Comparison", excerpt);
    }

    List<String> relatedPages(String wikiText)
    {
        String text = wikiText == null ? "" : wikiText;
        Set<String> pages = new LinkedHashSet<>();
        int firstHeading = text.indexOf("==");
        String introduction = afterNamedTemplate(
            firstHeading < 0 ? text : text.substring(0, firstHeading), "Infobox Slayer");
        Matcher recommendedTarget = RECOMMENDED_TARGET_LINK.matcher(introduction);
        if (recommendedTarget.find() && isUsefulRelatedPage(recommendedTarget.group(1).trim()))
        {
            pages.add(recommendedTarget.group(1).trim());
        }
        Matcher alternativeLocation = ALTERNATIVE_LOCATION_LINK.matcher(introduction);
        while (alternativeLocation.find() && pages.size() < MAX_RELATED_PAGES)
        {
            String page = alternativeLocation.group(1).trim();
            if (isUsefulRelatedPage(page))
            {
                pages.add(page);
            }
        }
        Matcher monsterLinks = WIKI_LINK.matcher(introduction);
        while (monsterLinks.find())
        {
            String page = monsterLinks.group(1).trim();
            if (isUsefulRelatedPage(page))
            {
                pages.add(page);
                break;
            }
        }

        Matcher sections = SECTION.matcher(text);
        while (sections.find() && pages.size() < MAX_RELATED_PAGES)
        {
            if (!sections.group(1).toLowerCase(Locale.ENGLISH)
                    .startsWith("location comparison") &&
                !"Locations".equalsIgnoreCase(sections.group(1)))
            {
                continue;
            }
            Matcher locations = TABLE_LOCATION.matcher(sections.group(2));
            while (locations.find() && pages.size() < MAX_RELATED_PAGES)
            {
                String page = locations.group(1).trim();
                if (isUsefulRelatedPage(page))
                {
                    pages.add(page);
                }
            }
        }
        return new ArrayList<>(pages);
    }

    WikiSource parseMonsterPage(String title, String sourceUrl, String wikiText)
    {
        String text = wikiText == null ? "" : wikiText;
        StringBuilder excerpt = new StringBuilder("Verified monster combat details:\n");
        Matcher fields = INFOBOX_FIELD.matcher(text);
        while (fields.find())
        {
            excerpt.append("- ").append(fieldLabel(fields.group(1))).append(": ")
                .append(plain(fields.group(2))).append('\n');
        }
        int firstHeading = text.indexOf("==");
        String introduction = afterNamedTemplate(
            firstHeading < 0 ? text : text.substring(0, firstHeading),
            "Infobox Monster");
        String overview = plain(introduction);
        if (!overview.isEmpty())
        {
            excerpt.append("Verified monster overview:\n").append(overview).append('\n');
        }
        Matcher strengths = STRENGTHS.matcher(text);
        if (strengths.find())
        {
            excerpt.append("Verified strengths, weaknesses, and combat setup:\n")
                .append(plain(strengths.group(1)));
        }
        String result = excerpt.toString().trim();
        if (result.equals("Verified monster combat details:"))
        {
            return null;
        }
        return new WikiSource(title + " - Combat details",
            sourceUrl.replaceFirst("#.*$", "") + "#Strengths_and_weaknesses",
            truncate(result, 5000));
    }

    WikiSource parseLocationPage(String title, String sourceUrl, String wikiText)
    {
        String text = wikiText == null ? "" : wikiText;
        int firstHeading = text.indexOf("==");
        String introduction = firstHeading < 0 ? text : text.substring(0, firstHeading);
        Matcher transport = TRANSPORTATION.matcher(text);
        StringBuilder excerpt = new StringBuilder("Verified location and route guidance:\n")
            .append(plain(introduction));
        if (transport.find())
        {
            excerpt.append("\nVerified transportation options:\n")
                .append(plain(transport.group(1)));
        }
        Matcher layout = LAYOUT.matcher(text);
        if (layout.find())
        {
            excerpt.append("\nVerified interior layout and access hazards:\n")
                .append(plain(layout.group(1)));
        }
        String result = excerpt.toString().trim();
        if (result.equals("Verified location and route guidance:"))
        {
            return null;
        }
        return new WikiSource(title + " - Getting there", sourceUrl,
            truncate(result, 4500));
    }

    List<VerifiedLocation> objectiveLocations(String sourceUrl, String wikiText)
    {
        String text = wikiText == null ? "" : wikiText;
        Matcher sections = SECTION.matcher(text);
        Map<String, VerifiedLocation> objectives = new LinkedHashMap<>();
        while (sections.find())
        {
            String sectionName = sections.group(1);
            if (!sectionName.toLowerCase(Locale.ENGLISH)
                    .startsWith("location comparison") &&
                !"Locations".equalsIgnoreCase(sectionName))
            {
                continue;
            }
            for (String row : sections.group(2).split("(?m)^\\|-\\s*$"))
            {
                Matcher location = TABLE_LOCATION.matcher(row);
                Matcher map = MAP_TEMPLATE.matcher(row);
                if (!location.find() || !map.find())
                {
                    continue;
                }
                String baseName = location.group(1).trim();
                String displayName = location.group(2) == null ||
                    location.group(2).trim().isEmpty()
                    ? baseName : location.group(2).trim();
                String qualifier = location.group(3) == null
                    ? "" : location.group(3).trim();
                String name = qualifier.matches("\\([^)]{1,80}\\)")
                    ? displayName + " " + qualifier : displayName;
                WorldPoint point = WikiDestinationClient.parseMapTemplate(map.group());
                if (name.isEmpty() || point == null)
                {
                    continue;
                }
                String id = destinationId(name);
                List<String> aliases = new ArrayList<>(Collections.singletonList(baseName));
                if (!displayName.equals(baseName))
                {
                    aliases.add(displayName);
                }
                if (name.toLowerCase(Locale.ENGLISH).contains(" cave"))
                {
                    aliases.add(name.replaceAll("(?i) cave", " Dungeon"));
                }
                else if (name.toLowerCase(Locale.ENGLISH).contains(" dungeon"))
                {
                    aliases.add(name.replaceAll("(?i) dungeon", " Cave"));
                }
                String guidance = "The OSRS Wiki task location table verifies an interior " +
                    "monster spawn at " + point.getX() + ", " + point.getY() +
                    ", plane " + point.getPlane() + ". Use this as the final objective; " +
                    "the location entrance is only an access step.";
                objectives.put(id, new VerifiedLocation(id, name, aliases, point,
                    guidance, sourceUrl.replaceFirst("#.*$", "") + "#" +
                        sectionName.replace(' ', '_')));
            }
        }
        return new ArrayList<>(objectives.values());
    }

    void cancel()
    {
        Call call = activeCall;
        if (call != null)
        {
            call.cancel();
        }
    }

    private void fetchRelatedPages(WikiResult base, List<String> pages,
        Consumer<WikiResult> callback)
    {
        Call call = httpClient.newCall(request(rawPagesUrl(pages)));
        activeCall = call;
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (!call.isCanceled())
                {
                    callback.accept(base);
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    if (!response.isSuccessful() || body == null)
                    {
                        callback.accept(base);
                        return;
                    }
                    String json = body.string();
                    callback.accept(merge(applyRouteTargets(base, json),
                        relatedSources(json)));
                }
                catch (IOException | RuntimeException exception)
                {
                    callback.accept(base);
                }
            }
        });
    }

    List<WikiSource> relatedSources(String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        List<WikiSource> sources = new ArrayList<>();
        if (pages == null)
        {
            return sources;
        }
        for (JsonElement element : pages)
        {
            JsonObject page = element.getAsJsonObject();
            String title = string(page, "title");
            String url = string(page, "fullurl");
            String text = revisionContent(page);
            WikiSource source = MONSTER_PAGE.matcher(text).find()
                ? parseMonsterPage(title, url, text)
                : parseLocationPage(title, url, text);
            if (source != null)
            {
                sources.add(source);
            }
        }
        return sources;
    }

    WikiResult applyRouteTargets(WikiResult base, String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        if (pages == null || base.getDestinations().isEmpty())
        {
            return base;
        }
        Map<String, WorldPoint> routePoints = new LinkedHashMap<>();
        for (JsonElement element : pages)
        {
            JsonObject page = element.getAsJsonObject();
            String text = revisionContent(page);
            if (MONSTER_PAGE.matcher(text).find())
            {
                continue;
            }
            String title = string(page, "title");
            WorldPoint routePoint = WikiDestinationClient.firstMapPoint(text);
            if (!title.isEmpty() && routePoint != null)
            {
                routePoints.put(normalizeTitle(title), routePoint);
            }
        }
        if (routePoints.isEmpty())
        {
            return base;
        }
        List<VerifiedLocation> destinations = new ArrayList<>();
        for (VerifiedLocation destination : base.getDestinations())
        {
            WorldPoint routePoint = null;
            String destinationName = normalizeTitle(destination.getName());
            for (Map.Entry<String, WorldPoint> entry : routePoints.entrySet())
            {
                if (destinationName.equals(entry.getKey()) ||
                    destinationName.startsWith(entry.getKey() + " "))
                {
                    routePoint = entry.getValue();
                    break;
                }
                for (String alias : destination.getAliases())
                {
                    if (normalizeTitle(alias).equals(entry.getKey()))
                    {
                        routePoint = entry.getValue();
                        break;
                    }
                }
                if (routePoint != null)
                {
                    break;
                }
            }
            destinations.add(routePoint == null ? destination :
                destination.withRouteWorldPoint(routePoint));
        }
        return new WikiResult(base.getSources(), base.isAvailable(), destinations);
    }

    private String revisionContent(String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        JsonObject query = root == null ? null : root.getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        if (pages == null || pages.size() == 0)
        {
            return "";
        }
        return revisionContent(pages.get(0).getAsJsonObject());
    }

    private static String revisionContent(JsonObject page)
    {
        JsonArray revisions = page.getAsJsonArray("revisions");
        if (revisions == null || revisions.size() == 0)
        {
            return "";
        }
        JsonObject slots = revisions.get(0).getAsJsonObject().getAsJsonObject("slots");
        JsonObject main = slots == null ? null : slots.getAsJsonObject("main");
        return main == null ? "" : string(main, "content");
    }

    private static String plain(String wikiText)
    {
        String text = MAP_TEMPLATE.matcher(wikiText).replaceAll(" ")
            .replaceAll("(?i)\\{\\{\\s*Yes\\s*}}", "Yes")
            .replaceAll("(?i)\\{\\{\\s*No\\s*}}", "No")
            .replaceAll("(?i)\\{\\{\\s*Fairycode\\s*\\|\\s*([a-z]{3})[^}]*}}", "$1")
            .replaceAll("(?i)\\{\\{\\s*SCP\\s*\\|\\s*([^|}]+)\\s*\\|\\s*" +
                "([0-9]+)[^}]*}}", "$2 $1")
            .replaceAll("(?i)\\{\\{\\s*SCP\\s*\\|\\s*([^|}]+)\\s*}}", "$1")
            .replaceAll("(?is)\\[\\[File:[^]]+]]", " ")
            .replaceAll("\\[\\[[^|\\]]+\\|([^\\]]+)]]", "$1")
            .replaceAll("\\[\\[([^#|\\]]+)(?:#[^|\\]]*)?]]", "$1")
            .replaceAll("(?is)<ref\\b[^>]*>.*?</ref>|<ref\\b[^>]*/>", " ")
            .replaceAll("(?is)<[^>]+>", " ")
            .replaceAll("(?i)\\{\\{\\s*FloorNumber\\s*\\|\\s*uk\\s*=\\s*([0-9]+)[^}]*}}", "$1st floor")
            .replace("'''", "").replace("''", "")
            .replaceAll("(?m)^\\{\\|.*$|^\\|}.*$|^\\|-.*$", "")
            .replaceAll("(?m)^!+\\s*", "")
            .replaceAll("(?m)^\\|+\\s*", "- ")
            .replaceAll("(?m)^\\*+\\s*", "  - ")
            .replaceAll("[ \\t]+", " ")
            .replaceAll(" *\\r?\\n *", "\n")
            .replaceAll("\\n{2,}", "\n").trim();
        String previous;
        do
        {
            previous = text;
            text = text.replaceAll("(?is)\\{\\{[^{}]{0,2000}}}", " ");
        }
        while (!text.equals(previous));
        return text.replaceAll("[ \\t]+", " ")
            .replaceAll(" *\\r?\\n *", "\n")
            .replaceAll("\\n{2,}", "\n").trim();
    }

    private static WikiResult merge(WikiResult base, WikiSource addition,
        List<VerifiedLocation> destinations)
    {
        Map<String, WikiSource> sources = new LinkedHashMap<>();
        for (WikiSource source : base.getSources())
        {
            sources.put(source.getUrl(), source);
        }
        if (addition != null)
        {
            sources.put(addition.getUrl(), addition);
        }
        Map<String, VerifiedLocation> mergedDestinations = new LinkedHashMap<>();
        for (VerifiedLocation destination : base.getDestinations())
        {
            mergedDestinations.put(destination.getId(), destination);
        }
        for (VerifiedLocation destination : destinations)
        {
            mergedDestinations.put(destination.getId(), destination);
        }
        return new WikiResult(new ArrayList<>(sources.values()), base.isAvailable(),
            new ArrayList<>(mergedDestinations.values()));
    }

    private static WikiResult merge(WikiResult base, List<WikiSource> additions)
    {
        Map<String, WikiSource> sources = new LinkedHashMap<>();
        for (WikiSource source : base.getSources())
        {
            sources.put(source.getUrl(), source);
        }
        for (WikiSource addition : additions)
        {
            sources.put(addition.getUrl(), addition);
        }
        return new WikiResult(new ArrayList<>(sources.values()), base.isAvailable(),
            base.getDestinations());
    }

    private static String destinationId(String title)
    {
        return title.toLowerCase(Locale.ENGLISH).replaceAll("[^a-z0-9]+", "-")
            .replaceAll("^-|-$", "");
    }

    private static String normalizeTitle(String title)
    {
        return title == null ? "" : title.toLowerCase(Locale.ENGLISH)
            .replaceAll("[^a-z0-9]+", " ").trim();
    }

    private static HttpUrl rawPageUrl(String title)
    {
        return HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("titles", title)
            .addQueryParameter("prop", "revisions")
            .addQueryParameter("rvprop", "content")
            .addQueryParameter("rvslots", "main")
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
    }

    private static HttpUrl rawPagesUrl(List<String> titles)
    {
        return HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("titles", String.join("|", titles))
            .addQueryParameter("prop", "revisions|info")
            .addQueryParameter("rvprop", "content")
            .addQueryParameter("rvslots", "main")
            .addQueryParameter("inprop", "url")
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
    }

    private static String afterNamedTemplate(String text, String templateName)
    {
        String lower = text.toLowerCase();
        int start = lower.indexOf("{{" + templateName.toLowerCase());
        if (start < 0)
        {
            return text;
        }
        int depth = 0;
        for (int i = start; i + 1 < text.length(); i++)
        {
            String pair = text.substring(i, i + 2);
            if ("{{".equals(pair))
            {
                depth++;
                i++;
            }
            else if ("}}".equals(pair))
            {
                depth--;
                i++;
                if (depth == 0)
                {
                    return text.substring(i + 1);
                }
            }
        }
        return text;
    }

    private static boolean isUsefulRelatedPage(String page)
    {
        String lower = page.toLowerCase();
        return !page.isEmpty() && !lower.startsWith("file:") &&
            !lower.equals("slayer task") && !lower.equals("slayer") &&
            !lower.equals("slayer monsters");
    }

    private static String fieldLabel(String field)
    {
        String normalized = field.toLowerCase();
        if ("elementalweaknesstype".equals(normalized))
        {
            return "elemental weakness";
        }
        if ("elementalweaknesspercent".equals(normalized))
