        }
        if ("mage".equals(normalized))
        {
            return "Magic level";
        }
        if ("dstab".equals(normalized))
        {
            return "stab defence";
        }
        if ("dslash".equals(normalized))
        {
            return "slash defence";
        }
        if ("dcrush".equals(normalized))
        {
            return "crush defence";
        }
        if ("dmagic".equals(normalized))
        {
            return "magic defence";
        }
        if ("dlight".equals(normalized))
        {
            return "light ranged defence";
        }
        if ("dstandard".equals(normalized))
        {
            return "standard ranged defence";
        }
        if ("dheavy".equals(normalized))
        {
