package com.gielinorguide;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class LocationResolverTest
{
    private final LocationResolver resolver = new LocationResolver();

    @Test
    public void resolvesVerifiedAppearanceDestinations()
    {
        assertEquals("falador-hairdresser", resolver.resolveMentions("Visit the Falador Hairdresser").get(0).getId());
        assertEquals("makeover-mage", resolver.resolveMentions("Talk to the Makeover Mage").get(0).getId());
        assertEquals("thessalia", resolver.resolveMentions("Try Thessalia's Fine Clothes").get(0).getId());
        assertEquals("lumbridge", resolver.resolveMentions("How do I get to Lumby?").get(0).getId());
        assertEquals("nightmare-zone", resolver.resolveMentions(
            "ok how do i get to the nmz").get(0).getId());
        assertEquals("corporeal-beast", resolver.resolveMentions(
            "how to get to corp").get(0).getId());
        assertEquals("observatory", resolver.resolveMentions(
            "fastest way to the observatory").get(0).getId());
        assertEquals("skavid-map-city-guards", resolver.resolveMentions(
            "how do i get a skavid map").get(0).getId());
    }

    @Test
    public void usesWikiVerifiedCoordinates()
    {
        assertEquals(new WorldPoint(2945, 3380, 0), resolver.byId("falador-hairdresser").getWorldPoint());
        assertEquals(new WorldPoint(2918, 3322, 0), resolver.byId("makeover-mage").getWorldPoint());
        assertEquals(new WorldPoint(3206, 3416, 0), resolver.byId("thessalia").getWorldPoint());
        assertEquals(new WorldPoint(2466, 3496, 0),
            resolver.byId("king-narnode-shareen").getWorldPoint());
        assertEquals(new WorldPoint(3165, 3490, 0),
            resolver.byId("grand-exchange").getWorldPoint());
        assertEquals(new WorldPoint(3000, 3360, 0),
            resolver.byId("falador").getWorldPoint());
        assertEquals(new WorldPoint(2605, 3115, 0),
            resolver.byId("nightmare-zone").getWorldPoint());
        assertEquals(new WorldPoint(2441, 3162, 0),
            resolver.byId("observatory").getWorldPoint());
        assertEquals(new WorldPoint(2541, 3029, 0),
            resolver.byId("skavid-map-city-guards").getWorldPoint());
        assertEquals(new WorldPoint(2704, 9431, 0),
            resolver.byId("brimhaven-dungeon").getWorldPoint());
        assertEquals(new WorldPoint(2744, 3155, 0),
            resolver.byId("brimhaven-dungeon").getRouteWorldPoint());
        assertEquals(new WorldPoint(3421, 3537, 0),
            resolver.byId("slayer-tower").getWorldPoint());
        assertEquals(new WorldPoint(2428, 3425, 0),
            resolver.byId("stronghold-slayer-cave").getWorldPoint());
        assertEquals(new WorldPoint(3203, 3681, 0),
            resolver.byId("corporeal-beast").getWorldPoint());
    }

    @Test
    public void hairIntentProducesOnlyTrustedHairdresserAction()
    {
        List<VerifiedLocation> result = resolver.resolveForResponse(
            "Where can I change my hair?", "You can do that in Falador.", Collections.emptyList());
        assertEquals(1, result.size());
        assertEquals("falador-hairdresser", result.get(0).getId());
    }

    @Test
    public void followUpRetainsPreviousVerifiedDestination()
    {
        List<GuideMessage> history = Arrays.asList(
            new GuideMessage(GuideMessage.Role.USER, "Where can I change my hair?"),
            new GuideMessage(GuideMessage.Role.ASSISTANT, "Visit the Falador Hairdresser."));
        List<VerifiedLocation> result = resolver.resolveForResponse(
            "How do I get there from Varrock?", "Travel west to Falador.", history);
        assertEquals(1, result.size());
        assertEquals("falador-hairdresser", result.get(0).getId());
    }

    @Test
    public void unverifiedDestinationNeverProducesMarker()
    {
        assertTrue(resolver.resolveForResponse(
            "Show me a made-up place", "Go to Imaginary Castle at 9999, 9999.", Collections.emptyList()).isEmpty());
    }

    @Test
    public void specificFaladorPlaceWinsOverContainingCity()
    {
        List<VerifiedLocation> result = resolver.resolveMentions("Falador Hairdresser");
        assertEquals(1, result.size());
        assertEquals("falador-hairdresser", result.get(0).getId());
    }

    @Test
    public void trainingAnswerDoesNotCreateIncidentalRouteButtons()
    {
        List<VerifiedLocation> result = resolver.resolveForResponse(
            "What is the best way to level Sailing?",
            "At level 30 you can sail The Storm Tempor, then Backwater and Porth Gwennith.",
            Collections.emptyList());
        assertTrue(result.isEmpty());
    }

    @Test
    public void navigationAnswerStillCreatesVerifiedRouteButton()
    {
        List<VerifiedLocation> result = resolver.resolveForResponse(
            "How do I get to the Observatory?",
            "Use a ring of dueling, then travel to the Observatory.",
            Collections.emptyList());
        assertEquals(1, result.size());
        assertEquals("observatory", result.get(0).getId());
    }

    @Test
    public void metalDragonTravelAnswerCreatesBrimhavenEntranceRoute()
    {
        List<VerifiedLocation> result = resolver.resolveForResponse(
            "how to get to metal dragons",
            "Metal dragons are in Brimhaven Dungeon, on Karamja.",
            Collections.emptyList());
        assertEquals(1, result.size());
        assertEquals("brimhaven-dungeon", result.get(0).getId());
        assertEquals(new WorldPoint(2744, 3155, 0),
            result.get(0).getRouteWorldPoint());
    }

    @Test
    public void slayerAnswerCreatesRouteForRecommendedVerifiedLocation()
    {
        List<VerifiedLocation> result = resolver.resolveForResponse(
            "Help me do my Slayer task",
            "For the fastest option, go to Stronghold Slayer Cave. Slayer Tower is slower.",
            Collections.emptyList());
        assertEquals(2, result.size());
        assertEquals("stronghold-slayer-cave", result.get(0).getId());
        assertEquals("slayer-tower", result.get(1).getId());
    }

    @Test
    public void newSlayerTaskWordingCreatesRouteForRecommendedLocation()
    {
        List<VerifiedLocation> result = resolver.resolveForResponse(
            "Help me with my new task",
            "Your assignment is bloodvelds in the Slayer Tower.",
            Collections.emptyList());
        assertEquals(1, result.size());
        assertEquals("slayer-tower", result.get(0).getId());
    }

    @Test
    public void wikiGroundingResolutionIgnoresShortLocationAliases()
    {
        assertTrue(resolver.resolveNamedMentions(
            "The alternate fee is listed as GE: 45,000 coins.").isEmpty());
        assertEquals("grand-exchange", resolver.resolveNamedMentions(
            "Travel to the Grand Exchange.").get(0).getId());
    }
}

