package com.gielinorguide;

import java.io.IOException;
import java.net.ConnectException;
import java.net.SocketTimeoutException;
import java.net.UnknownHostException;
import javax.net.ssl.SSLHandshakeException;
import okhttp3.OkHttpClient;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

public class OpenAiClientErrorTest
{
    @Test
    public void configuresEnoughTimeForModelGeneration()
    {
        OpenAiClient client = new OpenAiClient(new OkHttpClient(), new com.google.gson.Gson());

        assertTrue(client.connectTimeoutMillis() >= 20_000);
        assertTrue(client.readTimeoutMillis() >= 120_000);
        assertTrue(client.callTimeoutMillis() >= 150_000);
    }

    @Test
    public void categorizesDnsFailuresWithoutRawDetails()
    {
        String message = OpenAiClient.friendlyConnectionError(
            new UnknownHostException("private diagnostic detail"));
        assertTrue(message.contains("DNS"));
        assertTrue(!message.contains("private diagnostic detail"));
    }

    @Test
    public void categorizesTimeouts()
    {
        assertTrue(OpenAiClient.friendlyConnectionError(new SocketTimeoutException())
            .contains("timed out"));
    }

    @Test
    public void categorizesTlsFailuresNestedInsideIoException()
    {
        assertTrue(OpenAiClient.friendlyConnectionError(
            new IOException(new SSLHandshakeException("certificate detail")))
            .contains("TLS"));
    }

    @Test
    public void categorizesBlockedConnections()
    {
        assertTrue(OpenAiClient.friendlyConnectionError(new ConnectException())
            .contains("blocked or refused"));
    }
}

