package com.gielinorguide;

import com.google.gson.Gson;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class OpenAiResponseParserTest
{
    private final OpenAiResponseParser parser = new OpenAiResponseParser(new Gson());

    @Test
    public void parsesOutputTextFromMessageItems()
    {
        String json = "{\"output\":[" +
            "{\"type\":\"reasoning\",\"summary\":[]}," +
            "{\"type\":\"message\",\"content\":[" +
            "{\"type\":\"output_text\",\"text\":\"The Hairdresser is north of Falador's western bank.\"}," +
            "{\"type\":\"output_text\",\"text\":\"Hair and beard changes are free.\"}]}]}";

        assertEquals("The Hairdresser is north of Falador's western bank.\nHair and beard changes are free.",
            parser.parse(json));
    }

    @Test
    public void ignoresNullResponseFieldsAndReasoningContent()
    {
        String json = "{\"error\":null,\"output_text\":null,\"output\":[" +
            "{\"type\":\"reasoning\",\"content\":null}," +
            "null," +
            "{\"type\":\"message\",\"content\":[null," +
            "{\"type\":\"output_text\",\"text\":\"Use a ring of wealth.\"}]}]}";

        assertEquals("Use a ring of wealth.", parser.parse(json));
    }

    @Test
    public void parsesTopLevelOutputTextWhenProvided()
    {
        assertEquals("A concise answer.", parser.parse("{\"output_text\":\"A concise answer.\"}"));
    }

    @Test(expected = IllegalArgumentException.class)
    public void rejectsResponsesWithoutReadableText()
    {
        parser.parse("{\"output\":[{\"type\":\"reasoning\"}]}");
    }

    @Test(expected = IllegalArgumentException.class)
    public void surfacesApiErrorObjectsAsFailures()
    {
        parser.parse("{\"error\":{\"message\":\"Invalid API key\"}}");
    }
}

