        add(cases, "best gear for demonics", "Demonic gorilla/Strategies");

        add(cases, "what is the best magic gear for my level in my bank", "Armour/Magic armour");
        add(cases, "best mage setup with my stats", "Armour/Magic armour");
        add(cases, "what range armour should i use", "Armour/Ranged armour");
        add(cases, "best ranged gear from my bank", "Armour/Ranged armour");
        add(cases, "what melee equipment should i wear", "Armour/Melee armour");
        add(cases, "best strength gear at my level", "Armour/Melee armour");

        add(cases, "how do i unlock piety", "Piety");
        add(cases, "where do i get rigor", "Rigour");
        add(cases, "requirements for augury", "Augury");
        add(cases, "how do i unlock preserve prayer", "Preserve");

        return cases;
    }

    @Test
    public void selectsIntendedCanonicalWikiPage()
    {
        assertEquals(question, expectedPage, WikiQueryPlanner.plan(question));
    }

    private static void add(List<Object[]> cases, String question, String expected)
    {
        cases.add(new Object[]{question, expected});
    }
}

