package com.gielinorguide;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class SessionGroundingStateTest
{
    @Test
    public void reusesVerifiedEvidenceForReferentialFollowUp()
    {
        SessionGroundingState state = new SessionGroundingState();
        WikiResult recipe = new WikiResult(Collections.singletonList(new WikiSource(
            "Soulreaper axe - Creation",
            "https://oldschool.runescape.wiki/w/Soulreaper_axe#Creation",
            "Materials include four boss components.")), true);
        state.remember(recipe);

        assertSame(recipe, state.forFollowUp("okay, how do i get those pieces?", false));
        assertSame(recipe, state.forFollowUp("where does each one come from?", false));
        assertSame(recipe, state.forFollowUp("which should i work on first?", false));
        assertSame(recipe, state.forFollowUp("what should i do next?", false));
        assertSame(recipe, state.forFollowUp(
            "which skill should i work on first for that?", false));
        assertSame(recipe, state.forFollowUp("help me do this", false));
        assertSame(recipe, state.forFollowUp(
            "what's the best way to finish this?", false));
        assertSame(recipe, state.forFollowUp("walk me through this", false));
        assertNull(state.forFollowUp(
            "what should i do first to get ready for mm2?", false));
        assertNull(state.forFollowUp("how do i get a dragon scimitar?", false));
        assertNull(state.forFollowUp("how should i level firemaking?", false));
    }

    @Test
    public void clearDropsVerifiedFollowUpEvidence()
    {
        SessionGroundingState state = new SessionGroundingState();
        state.remember(new WikiResult(Collections.singletonList(new WikiSource(
            "Item", "https://example.invalid/item", "Verified.")), true));
        state.clear();
        assertNull(state.forFollowUp("how do i get those?", false));
    }

    @Test
    public void explicitTargetNeverReusesUnrelatedGrounding()
    {
        SessionGroundingState state = new SessionGroundingState();
        state.remember(new WikiResult(Collections.singletonList(new WikiSource(
            "Herb", "https://oldschool.runescape.wiki/w/Herb", "Herb evidence.")), true));

        assertNull(state.forFollowUp("best way to kill them?", true));
    }
}

