package com.gielinorguide;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SlayerTaskIntentResolverTest
{
    private final SlayerTaskIntentResolver resolver = new SlayerTaskIntentResolver();

    @Test
    public void recognizesNaturalTaskHelpQuestions()
    {
        assertTrue(resolver.supports("help me finish my slayer task", Collections.emptyList()));
        assertTrue(resolver.supports("whats the safest way to do this slayer assignment", Collections.emptyList()));
        assertTrue(resolver.supports("where are the monsters for my current task", Collections.emptyList()));
        assertTrue(resolver.supports("help me with my new task", Collections.emptyList()));
        assertTrue(resolver.supports("I just got a new assignment", Collections.emptyList()));
        assertTrue(resolver.supports("help with the task I just got", Collections.emptyList()));
        assertTrue(resolver.supports(
            "how do i get to bloodvelds for my slayer task", Collections.emptyList()));
        assertFalse(resolver.supports("what is the fastest way to train slayer", Collections.emptyList()));
        assertFalse(resolver.supports("which slayer master should I use for points?",
            Collections.emptyList()));
        assertFalse(resolver.supports("what's the best slayer master for me?",
            Collections.emptyList()));
        assertFalse(resolver.supports("help me get my slayer helmet",
            Collections.emptyList()));
        assertFalse(resolver.supports("which quest task should I do next?",
            Collections.emptyList()));
    }

    @Test
    public void keepsSlayerContextForShortFollowUps()
    {
        java.util.List<GuideMessage> history = Arrays.asList(
            new GuideMessage(GuideMessage.Role.USER, "help with my slayer task"),
            new GuideMessage(GuideMessage.Role.ASSISTANT, "Your Slayer assignment is aberrant spectres."));
        assertTrue(resolver.supports("where do i fight them safely", history));
        assertTrue(resolver.supports("what are bloodvelds weak to", history));
        assertTrue(resolver.supports("show me their defence stats", history));
        assertTrue(resolver.supports("help me do this", history));
        assertTrue(resolver.supports("what's the best way to finish this?", history));
        assertFalse(resolver.supports("what is vorkath weak to", Collections.emptyList()));
    }
}

