import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

public class TravelIntentResolverTest
{
    private final TravelIntentResolver resolver = new TravelIntentResolver();

    @Test
    public void extractsDestinationsFromCommonTravelWording()
    {
        assertEquals("Falador", resolver.extractDestination(
            "what's the fastest way to Falador?").get());
        assertEquals("Slayer Tower", resolver.extractDestination(
            "How do I get to the Slayer Tower from here?").get());
