        assertEquals("Thessalia", resolver.extractDestination("where is Thessalia?").get());
    }

    @Test
    public void doesNotTreatNonTravelOrUnresolvedPronounsAsDestinations()
    {
        assertFalse(resolver.extractDestination("What is sold at the GE?").isPresent());
        assertFalse(resolver.extractDestination("How do I get there?").isPresent());
        assertFalse(resolver.extractDestination(
            "whats the best way to level magic at my level").isPresent());
        assertFalse(resolver.extractDestination(
            "where is the best place to train ranged with my stats").isPresent());
        assertFalse(resolver.extractDestination(
            "what is the fastest way to make gp").isPresent());
        assertFalse(resolver.extractDestination(
            "whats the best magic gear for my level in my bank").isPresent());
    }

    @Test
    public void recognizesTravelFollowUpsWithoutInventingANewDestination()
    {
        assertFalse(resolver.extractDestination("what's the fastest way there?").isPresent());
        org.junit.Assert.assertTrue(resolver.isTravelFollowUp("what's the fastest way there?"));
        org.junit.Assert.assertTrue(resolver.isTravelFollowUp("whats teh route?"));
        org.junit.Assert.assertTrue(resolver.isTravelFollowUp(
            "can you mark it for shortest path"));
        org.junit.Assert.assertTrue(resolver.isDestinationSeeking(
            "where do i go for the giant champion scroll"));
        org.junit.Assert.assertTrue(resolver.isDestinationSeeking(
            "where can i fight that monster"));
    }

    @Test
    public void usesShortestPathForActionableQuestionsOnly()
    {
        org.junit.Assert.assertTrue(resolver.shouldUseShortestPath(
            "how do i get a skavid map"));
        org.junit.Assert.assertTrue(resolver.shouldUseShortestPath(
            "help me obtain emberlight"));
        org.junit.Assert.assertTrue(resolver.shouldUseShortestPath(
            "walk me through getting a fire cape"));
        org.junit.Assert.assertTrue(resolver.shouldUseShortestPath(
            "how do i access the slayer tower"));
        org.junit.Assert.assertTrue(resolver.shouldUseShortestPath(
            "how to get to metal dragons"));

        assertFalse(resolver.shouldUseShortestPath("what are ancient shards for"));
        assertFalse(resolver.shouldUseShortestPath("what does protect from magic do"));
    }
}

