package com.gielinorguide;

import com.google.gson.Gson;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.OkHttpClient;

/** Live, opt-in acquisition graph check. It never calls OpenAI. */
public final class WikiAcquisitionSmokeCheck
{
    private WikiAcquisitionSmokeCheck()
    {
    }

    public static void main(String[] args) throws Exception
    {
        OkHttpClient httpClient = new OkHttpClient();
        try
        {
            run(httpClient);
        }
        finally
        {
            LiveWikiCheckSupport.close(httpClient);
        }
    }

    private static void run(OkHttpClient httpClient) throws Exception
    {
        WikiClient client = new WikiClient(httpClient, new Gson());
        Map<String, String> excerpts = fetch(client, "Soulreaper axe");
        requireContains(excerpts, "Soulreaper axe - Creation", "Leviathan's lure");
        requireContains(excerpts, "Leviathan's lure", "The Leviathan");
        requireContains(excerpts, "Siren's staff", "The Whisperer");
        requireContains(excerpts, "Executioner's axe head", "Vardorvis");
        requireContains(excerpts, "Eye of the Duke", "Duke Sucellus");

        excerpts = fetch(client, "Crystal armour seed");
        requireContains(excerpts, "Crystal armour seed - goal details", "Crystal body");
        requireContains(excerpts, "Crystal armour seed - goal details", "3 × Crystal armour seed");
        requireContains(excerpts, "Crystal armour seed - goal details", "150 × Crystal shard");
        requireContains(excerpts, "Crystal armour seed - goal details", "Reward Chest (The Gauntlet)");
        System.out.println("Verified Soulreaper component sources and full crystal armour " +
            "goal details without using OpenAI.");
    }

    private static Map<String, String> fetch(WikiClient client, String query) throws Exception
    {
        CountDownLatch done = new CountDownLatch(1);
        AtomicReference<WikiResult> resultRef = new AtomicReference<>();
        client.search(query, true, result ->
        {
            resultRef.set(result);
            done.countDown();
        });
        if (!done.await(60, TimeUnit.SECONDS))
        {
            client.cancel();
            throw new IllegalStateException("Timed out while checking acquisition grounding for " + query);
        }
        WikiResult result = resultRef.get();
        if (result == null || !result.isAvailable())
        {
            throw new IllegalStateException("Acquisition grounding was unavailable for " + query);
        }
        Map<String, String> excerpts = new HashMap<>();
        for (WikiSource source : result.getSources())
        {
            excerpts.put(source.getTitle(), source.getExcerpt());
        }
        return excerpts;
    }

    private static void requireContains(Map<String, String> excerpts, String title, String text)
    {
        String excerpt = excerpts.get(title);
        if (excerpt == null || !excerpt.contains(text))
        {
            throw new IllegalStateException("Missing expected grounding: " + title + " -> " + text);
        }
    }
}

package com.gielinorguide;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** Live, opt-in catalog check. It uses the Wiki only and never calls OpenAI. */
public final class WikiCatalogSmokeCheck
{
    private static final String API_URL = "https://oldschool.runescape.wiki/api.php";
    private static final int BATCH_SIZE = 20;

    private WikiCatalogSmokeCheck()
    {
    }

    public static void main(String[] args) throws Exception
    {
        Set<String> pages = WikiPageCatalog.pagesForSmokeCheck();
        List<String> allPages = new ArrayList<>(pages);
        List<String> failures = new ArrayList<>();
        OkHttpClient client = new OkHttpClient();
        Gson gson = new Gson();

        try
        {
            for (int start = 0; start < allPages.size(); start += BATCH_SIZE)
            {
                int end = Math.min(start + BATCH_SIZE, allPages.size());
                checkBatch(client, gson, allPages.subList(start, end), failures);
            }

            if (!failures.isEmpty())
            {
                throw new IllegalStateException("Wiki catalog pages missing or empty: " +
                    String.join(", ", failures));
            }
            System.out.println("Verified " + allPages.size() +
                " canonical OSRS Wiki pages without using OpenAI.");
        }
        finally
        {
            LiveWikiCheckSupport.close(client);
        }
    }

    private static void checkBatch(OkHttpClient client, Gson gson, List<String> pages,
        List<String> failures) throws IOException
    {
        HttpUrl url = HttpUrl.parse(API_URL).newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("titles", String.join("|", pages))
            .addQueryParameter("prop", "extracts")
            .addQueryParameter("explaintext", "1")
            .addQueryParameter("exintro", "1")
            .addQueryParameter("exchars", "300")
            .addQueryParameter("exlimit", Integer.toString(BATCH_SIZE))
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .build();
        Request request = new Request.Builder().url(url)
            .header("User-Agent", "GielinorGuide RuneLite plugin catalog check")
            .build();
        try (Response response = client.newCall(request).execute();
             ResponseBody body = response.body())
        {
            if (!response.isSuccessful() || body == null)
            {
                throw new IOException("OSRS Wiki returned HTTP " + response.code());
            }
            JsonObject root = gson.fromJson(body.string(), JsonObject.class);
            JsonObject query = root == null ? null : root.getAsJsonObject("query");
            JsonArray results = query == null ? null : query.getAsJsonArray("pages");
            if (results == null)
            {
                throw new IOException("OSRS Wiki response did not contain pages");
            }
            for (JsonElement element : results)
            {
                JsonObject page = element.getAsJsonObject();
                String title = string(page, "title");
                String extract = string(page, "extract");
                if (page.has("missing") || extract.trim().isEmpty())
                {
                    failures.add(title);
                }
            }
        }
    }

    private static String string(JsonObject object, String key)
    {
        JsonElement value = object.get(key);
        return value == null || value.isJsonNull() ? "" : value.getAsString();
    }
}

