    @Test
    public void missingCanonicalSubpageFallsBackToWikiTitleSearch() throws Exception
    {
        List<String> requests = new CopyOnWriteArrayList<>();
        OkHttpClient httpClient = new OkHttpClient.Builder().addInterceptor(chain ->
        {
            String generator = chain.request().url().queryParameter("generator");
            String title = chain.request().url().queryParameter("titles");
            String prop = chain.request().url().queryParameter("prop");
            requests.add(generator == null ? title + "|" + prop : "search");
            String json;
            if ("search".equals(generator))
            {
                json = "{\"query\":{\"pages\":[{\"index\":1," +
                    "\"title\":\"Slayer task/Metal dragons\"}]}}";
            }
            else if ("revisions".equals(prop))
            {
                json = "{\"query\":{\"pages\":[{" +
                    "\"title\":\"Slayer task/Metal dragons\"," +
                    "\"revisions\":[{\"slots\":{\"main\":{\"content\":" +
                    "\"{{Infobox Slayer\\n|name = Metal dragons\\n}}\\n" +
                    "Metal dragons are found in Brimhaven Dungeon.\\n" +
                    "==Slayer Unlocks==\\nUnlocks\"}}}]}]}}";
            }
            else if ("Slayer task/Metal Dragons".equals(title))
            {
                json = "{\"query\":{\"pages\":[{\"title\":" +
                    "\"Slayer task/Metal Dragons\",\"missing\":true}]}}";
            }
            else
            {
                json = "{\"query\":{\"pages\":[" +
                    page("Slayer task/Metal dragons",
                        "Metal dragons are found in Brimhaven Dungeon.") + "]}}";
            }
            return new Response.Builder()
                .request(chain.request())
                .protocol(Protocol.HTTP_1_1)
                .code(200)
                .message("OK")
                .body(ResponseBody.create(MediaType.parse("application/json"), json))
                .build();
        }).build();
        WikiClient fallbackClient = new WikiClient(httpClient, new Gson());
        CountDownLatch done = new CountDownLatch(1);
        AtomicReference<WikiResult> result = new AtomicReference<>();

        fallbackClient.search("Slayer task/Metal Dragons", value ->
        {
            result.set(value);
            done.countDown();
        });

        assertTrue(done.await(5, TimeUnit.SECONDS));
        assertEquals("Slayer task/Metal dragons",
            result.get().getPrimarySource().getTitle());
        assertTrue(result.get().asGroundingText().contains("Brimhaven Dungeon"));
        assertTrue(requests.contains("Slayer task/Metal Dragons|extracts|info"));
        assertTrue(requests.contains("search"));
        assertTrue(requests.contains("Slayer task/Metal dragons|extracts|info"));
    }

