package com.gielinorguide;

import com.google.gson.Gson;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.OkHttpClient;

/** Live, opt-in comparison-evidence check. It never calls OpenAI. */
public final class WikiComparisonSmokeCheck
{
    private WikiComparisonSmokeCheck()
    {
    }

    public static void main(String[] args) throws Exception
    {
        OkHttpClient httpClient = new OkHttpClient();
        try
        {
            run(httpClient);
        }
        finally
        {
            LiveWikiCheckSupport.close(httpClient);
        }
    }

    private static void run(OkHttpClient httpClient) throws Exception
    {
        CountDownLatch done = new CountDownLatch(1);
        AtomicReference<WikiResult> resultRef = new AtomicReference<>();
        WikiClient client = new WikiClient(httpClient, new Gson());
        client.search("Pet", false, false, true, result ->
        {
            resultRef.set(result);
            done.countDown();
        });
        if (!done.await(60, TimeUnit.SECONDS))
        {
            client.cancel();
            throw new IllegalStateException("Timed out while checking pet comparison evidence");
        }
        WikiResult result = resultRef.get();
        if (result == null || !result.isAvailable())
        {
            throw new IllegalStateException("Pet comparison grounding was unavailable");
        }
        Map<String, String> excerpts = new HashMap<>();
        for (WikiSource source : result.getSources())
        {
            excerpts.put(source.getTitle(), source.getExcerpt());
        }
        requireContains(excerpts, "Kitten", "Gertrude's Cat");
        requireContains(excerpts, "Kitten", "first kitten is free");
        requireContains(excerpts, "Kitten", "100 coins");
        requirePresent(excerpts, "Gertrude's Cat");
        System.out.println("Verified guaranteed kitten requirements and cost without using OpenAI.");
    }

    private static void requirePresent(Map<String, String> excerpts, String title)
    {
        if (!excerpts.containsKey(title))
        {
            throw new IllegalStateException("Missing comparison page: " + title);
        }
    }

    private static void requireContains(Map<String, String> excerpts, String title, String text)
    {
        String excerpt = excerpts.get(title);
        if (excerpt == null || !excerpt.contains(text))
        {
            throw new IllegalStateException("Missing expected comparison grounding: " +
                title + " -> " + text);
        }
    }
}

