            Arrays.asList("Champions' Guild", "Larxus"), json);

        assertEquals("Champions' Guild", location.getName());
        assertEquals(new WorldPoint(3190, 3366, 0), location.getWorldPoint());
    }

    @Test
    public void routesRustySwordRecommendationToTheHamHideoutEntrance()
    {
        String answer = "Pickpocket H.A.M. members in the H.A.M. Hideout for a rusty sword.";
        String sourceJson = response("Rusty sword",
            "https://oldschool.runescape.wiki/w/Rusty_sword",
            "The easiest way is pickpocketing [[H.A.M. Member]]s (requires 15 " +
                "[[Thieving]], reached by picking the [[H.A.M. Hideout]] trapdoor).");
        List<String> candidates = client.destinationCandidates(answer, sourceJson);
        String destinationJson = response("H.A.M. Hideout",
            "https://oldschool.runescape.wiki/w/H.A.M._Hideout",
            "{{Infobox Location|map={{Map|mtype=focusarea|3137,9663|3199,9663|" +
                "3199,9601|3137,9601|mapID=-1|zoom=2}}}} " +
                "{{Map|caption=The H.A.M. Hideout entrance west of the Lumbridge " +
                "general store|x=3200|y=3235|mtype=polygon|3162,3248|3165,3245|" +
                "3170,3250|3166,3254|3164,3252|3165,3251}}");

        VerifiedLocation location = client.parseCandidateDestination(candidates,
            destinationJson);

        assertEquals("H.A.M. Hideout", location.getName());
        assertEquals(new WorldPoint(3137, 9663, 0), location.getWorldPoint());
        assertEquals(new WorldPoint(3165, 3251, 0), location.getRouteWorldPoint());
