    private static String response(String title, String url, String content)
    {
        return "{\"query\":{\"pages\":[" + page(title, url, content) + "]}}";
    }

    private static String page(String title, String url, String content)
    {
        return "{\"title\":\"" + title +
            "\",\"fullurl\":\"" + url +
            "\",\"revisions\":[{\"slots\":{\"main\":{\"content\":\"" +
            content.replace("\\", "\\\\").replace("\"", "\\\"") +
            "\"}}}]}";
    }
}

