package com.gielinorguide;

import com.google.gson.Gson;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.OkHttpClient;

/** Live, opt-in linked-use check. It never calls OpenAI. */
public final class WikiPurposeSmokeCheck
{
    private WikiPurposeSmokeCheck()
    {
    }

    public static void main(String[] args) throws Exception
    {
        OkHttpClient httpClient = new OkHttpClient();
        try
        {
            run(httpClient);
        }
        finally
        {
            LiveWikiCheckSupport.close(httpClient);
        }
    }

    private static void run(OkHttpClient httpClient) throws Exception
    {
        WikiClient client = new WikiClient(httpClient, new Gson());
        WikiResult result = fetch(client, "Revenant ether");
        Map<String, String> excerpts = new HashMap<>();
        for (WikiSource source : result.getSources())
        {
            excerpts.put(source.getTitle(), source.getExcerpt());
        }
        requireContains(excerpts, "Revenant ether - Uses", "Bracelet of ethereum");
        requireContains(excerpts, "Revenant ether - Uses", "Ursine chainmace");
        requireContains(excerpts, "Bracelet of ethereum", "reduced by 75%");
        requireContains(excerpts, "Bracelet of ethereum", "16,000");
        requirePresent(excerpts, "Craw's bow");
        requirePresent(excerpts, "Webweaver bow");
        requirePresent(excerpts, "Thammaron's sceptre");
        requirePresent(excerpts, "Accursed sceptre");
        requirePresent(excerpts, "Viggora's chainmace");
        requirePresent(excerpts, "Ursine chainmace");

        WikiResult ancient = fetch(client, "Ancient shard");
        Map<String, String> ancientExcerpts = new HashMap<>();
        for (WikiSource source : ancient.getSources())
        {
            ancientExcerpts.put(source.getTitle(), source.getExcerpt());
        }
        requireContains(ancientExcerpts, "Ancient shard - Purpose", "Darklight");
        requireContains(ancientExcerpts, "Ancient shard - Purpose", "333 charges");
        requireContains(ancientExcerpts, "Ancient shard - Purpose", "transportation");
        requirePresent(ancientExcerpts, "Arclight");
        System.out.println("Verified revenant-ether and ancient-shard purpose grounding without using OpenAI.");
    }

    private static WikiResult fetch(WikiClient client, String page) throws Exception
    {
        CountDownLatch done = new CountDownLatch(1);
        AtomicReference<WikiResult> resultRef = new AtomicReference<>();
        client.search(page, false, true, result ->
        {
            resultRef.set(result);
            done.countDown();
        });
        if (!done.await(60, TimeUnit.SECONDS))
        {
            client.cancel();
            throw new IllegalStateException("Timed out while checking purpose for " + page);
        }
        WikiResult result = resultRef.get();
        if (result == null || !result.isAvailable())
        {
            throw new IllegalStateException("Purpose grounding was unavailable for " + page);
        }
        return result;
    }

    private static void requirePresent(Map<String, String> excerpts, String title)
    {
        if (!excerpts.containsKey(title))
        {
            throw new IllegalStateException("Missing linked-use page: " + title);
        }
    }

    private static void requireContains(Map<String, String> excerpts, String title, String text)
    {
        String excerpt = excerpts.get(title);
        if (excerpt == null || !excerpt.contains(text))
        {
            throw new IllegalStateException("Missing expected purpose grounding: " +
                title + " -> " + text);
        }
    }
}

package com.gielinorguide;

import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class WikiQueryPlannerTest
{
    @Test
    public void targetsSkillTrainingGuidesInsteadOfRawQuestions()
    {
        assertEquals("Sailing training", WikiQueryPlanner.plan("best way to level sailing?"));
        assertEquals("Magic training", WikiQueryPlanner.plan("what is the fastest way to train magic"));
        assertEquals("Ranged training", WikiQueryPlanner.plan("best ranged xp at my level"));
    }

    @Test
    public void stripsAcquisitionQuestionScaffolding()
    {
        assertEquals("Soulreaper axe", WikiQueryPlanner.plan("how to get soul reaper axe?"));
        assertEquals("Hellcat", WikiQueryPlanner.plan("how can I obtain a hellcat in OSRS?"));
        assertEquals("Emberlight", WikiQueryPlanner.plan("walk me through getting emberlight."));
        assertTrue(WikiQueryPlanner.isAcquisitionQuestion(
            "walk me through getting emberlight."));
        assertTrue(WikiQueryPlanner.isGoalWalkthroughQuestion(
            "walk me through getting emberlight."));
    }

    @Test
    public void targetsTheItemForChargingQuestions()
    {
        assertEquals("trident of the swamp", WikiQueryPlanner.plan(
            "how can i get more charges for my trident of the swamp"));
        assertEquals("trident of the swamp", WikiQueryPlanner.plan(
            "how do I recharge my trident of the swamp?"));
        assertTrue(WikiQueryPlanner.isChargingQuestion(
            "what do I need to recharge my trident of the swamp?"));
        assertFalse(WikiQueryPlanner.needsSemanticPlanning(
            "how can i get more charges for my trident of the swamp",
            "Trident of the swamp"));
    }

    @Test
    public void leavesOtherQuestionsIntact()
    {
        assertEquals("What does Protect from Magic do?",
            WikiQueryPlanner.plan("What does Protect from Magic do?"));
        assertEquals("Ancient shard",
            WikiQueryPlanner.plan("what are ancient shards for?"));
        assertTrue(WikiQueryPlanner.isPurposeQuestion(
            "what are ancient shards for?"));
        assertEquals("Giant champion scroll", WikiQueryPlanner.plan(
            "where do i fight the giant for the giant champion scroll"));
    }

    @Test
    public void doesNotDuplicateCanonicalDestinationInSearchQuery()
    {
        VerifiedLocation lumbridge = new LocationResolver().byId("lumbridge");
        assertEquals("Lumbridge", GuideService.buildWikiSearchQuery(
            "how od i get to lumby", Collections.singletonList(lumbridge)));
    }

    @Test
    public void recognizesOpenEndedComparisonsWithoutHijackingTrainingOrTravel()
    {
        assertTrue(WikiQueryPlanner.isComparisonQuestion(
            "whats teh easiest cosmetic pet to obtain?"));
        assertTrue(WikiQueryPlanner.isComparisonQuestion("what is the lowest effort pet"));
        assertFalse(WikiQueryPlanner.isComparisonQuestion("best way to level sailing"));
        assertFalse(WikiQueryPlanner.isComparisonQuestion("fastest route to Falador"));
    }

    @Test
    public void treatsNaturalGoalHelpAsAFirstClassIntent()
    {
        assertEquals("ranarr seeds",
            WikiQueryPlanner.plan("what's the best way to farm ranarr seeds?"));
        assertEquals("ranarr seeds",
            WikiQueryPlanner.plan("help me obtain ranarr seeds"));
        assertTrue(WikiQueryPlanner.isGoalAssistanceQuestion(
            "what's the best way to farm ranarr seeds?"));
        assertTrue(WikiQueryPlanner.isGoalAssistanceQuestion("help me do this"));
        assertTrue(WikiQueryPlanner.isReferentialFollowUp("help me do this"));
        assertTrue(WikiQueryPlanner.isReferentialFollowUp(
            "what's the best way to finish this?"));
        assertTrue(WikiQueryPlanner.isReferentialFollowUp("walk me through this"));
        assertTrue(WikiQueryPlanner.isContextualSubjectFollowUp("help me do this"));
        assertFalse(WikiQueryPlanner.isReferentialFollowUp(
            "help me obtain ranarr seeds"));
    }

    @Test
    public void recognizesQuestRequirementQuestions()
    {
        assertEquals("At First Light",
            WikiQueryPlanner.plan("what do i need for at first light quest"));
        assertTrue(WikiQueryPlanner.isQuestRequirementQuestion(
            "what do i need for at first light quest"));
        String readiness = "what should i do first to get ready for mm2?";
        assertEquals("Monkey Madness II", WikiQueryPlanner.plan(readiness));
        assertTrue(WikiQueryPlanner.isQuestReadinessQuestion(
            readiness, "Monkey Madness II"));
        assertFalse(WikiQueryPlanner.isQuestWalkthroughQuestion(
            readiness, "Monkey Madness II"));
        assertFalse(WikiQueryPlanner.isReferentialFollowUp(readiness));
        assertFalse(WikiQueryPlanner.needsSemanticPlanning(
            readiness, "Monkey Madness II"));

        String broadGuidance = "what should i do for mm2?";
        assertEquals("Monkey Madness II", WikiQueryPlanner.plan(broadGuidance));
        assertTrue(WikiQueryPlanner.isQuestReadinessQuestion(
            broadGuidance, "Monkey Madness II"));
        assertFalse(WikiQueryPlanner.isQuestWalkthroughQuestion(
            broadGuidance, "Monkey Madness II"));
        assertFalse(WikiQueryPlanner.needsSemanticPlanning(
            broadGuidance, "Monkey Madness II"));
    }

    @Test
    public void recognizesQuestWalkthroughsWithoutTreatingTrainingAsQuestFollowUp()
    {
        assertTrue(WikiQueryPlanner.isQuestWalkthroughQuestion(
            "lets do while guthix sleeps quest", "While Guthix Sleeps"));
        assertTrue(WikiQueryPlanner.isQuestWalkthroughQuestion(
            "walk me through monkey madness 2", "Monkey Madness II"));
        assertFalse(WikiQueryPlanner.isQuestWalkthroughQuestion(
            "how should i level firemaking", "Firemaking training"));
        assertTrue(WikiQueryPlanner.isSkillTrainingQuestion(
            "how should i level firemaking"));
        assertEquals("Cook's Assistant",
            WikiQueryPlanner.plan("walk me through Cook's Assistant quest"));
        assertTrue(WikiQueryPlanner.isQuestWalkthroughQuestion(
            "walk me through Cook's Assistant quest", "Cook's Assistant"));
    }

    @Test
    public void recognizesAllSlayerProgressionEvidencePages()
    {
        assertTrue(WikiQueryPlanner.isSlayerProgressionQuery("Slayer Master"));
        assertTrue(WikiQueryPlanner.isSlayerProgressionQuery("Slayer reward point"));
        assertTrue(WikiQueryPlanner.isSlayerProgressionQuery("Slayer training"));
        assertTrue(WikiQueryPlanner.isSlayerProgressionQuery("Slayer helmet"));
        assertTrue(WikiQueryPlanner.isSlayerProgressionQuery("Mortimer"));
        assertFalse(WikiQueryPlanner.isSlayerProgressionQuery("Slayer task/Aberrant spectres"));
    }

    @Test
    public void sendsOnlyUnclassifiedWordingToSemanticFallback()
    {
        assertTrue(WikiQueryPlanner.needsSemanticPlanning(
            "I could really use a hand working toward Emberlight", "Emberlight"));
        assertFalse(WikiQueryPlanner.needsSemanticPlanning(
            "walk me through getting Emberlight", "Emberlight"));
        assertFalse(WikiQueryPlanner.needsSemanticPlanning(
            "help me with my slayer task", "Slayer task/Earth Warriors"));
        assertTrue(WikiQueryPlanner.isSemanticQuerySupportedByQuestion(
            "I could really use a hand working toward Emberlight", "Emberlight"));
        assertFalse(WikiQueryPlanner.isSemanticQuerySupportedByQuestion(
            "how do I add charges to my trident of the swamp",
            "Demonic Pacts League/Areas/Varlamore"));
    }

    @Test
    public void resolvesDemonstrativeShortcutFollowUpsAgainstRecentContext()
    {
        String followUp = "hwo do i unlock that agility shortcut";
        java.util.List<GuideMessage> history = Arrays.asList(
            new GuideMessage(GuideMessage.Role.USER, "how to get to observatory"),
            new GuideMessage(GuideMessage.Role.ASSISTANT,
                "The Observatory grapple shortcut may need to be unlocked."),
            new GuideMessage(GuideMessage.Role.USER, followUp));

        assertTrue(WikiQueryPlanner.isContextualSubjectFollowUp(followUp));
        assertTrue(WikiQueryPlanner.needsSemanticPlanning(followUp,
            WikiQueryPlanner.plan(followUp)));
        assertTrue(WikiQueryPlanner.isSemanticQuerySupportedByConversation(
            followUp, history, "Rocks (Observatory)"));
        assertFalse(WikiQueryPlanner.isSemanticQuerySupportedByConversation(
            followUp, history, "Demonic Pacts League/Areas/Varlamore"));
    }

    @Test
    public void recognizesAchievementDiaryGoalsAndTaskSets()
    {
        assertEquals("Varrock Diary#Hard",
            WikiQueryPlanner.plan("walk me through the Varrock hard diary"));
        assertEquals("Lumbridge & Draynor Diary#Elite",
            WikiQueryPlanner.plan("help me do the Lumbridge elite tasks"));
        assertEquals("Achievement Diary",
            WikiQueryPlanner.plan("which achievement diary should I work on?"));
        assertTrue(WikiQueryPlanner.isAchievementDiaryWalkthroughQuestion(
            "help me with the Varrock hard tasks", "Varrock Diary#Hard"));
        assertEquals("Varrock Hard",
            WikiQueryPlanner.achievementDiaryHelperName("Varrock Diary#Hard"));
        assertFalse(WikiQueryPlanner.needsSemanticPlanning(
            "walk me through the Varrock hard diary", "Varrock Diary#Hard"));
        assertTrue(WikiQueryPlanner.needsSemanticPlanning(
            "help me with this diary task", "help me with this diary task"));
        assertTrue(WikiQueryPlanner.isReferentialFollowUp(
            "walk me through this diary task"));
        assertTrue(WikiQueryPlanner.isReferentialFollowUp(
            "which skill should i work on first for that?"));
    }
}

