package com.gielinorguide;

import com.google.gson.Gson;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.OkHttpClient;

/** Live, opt-in quest requirement check. It never calls OpenAI. */
public final class WikiQuestRequirementSmokeCheck
{
    private WikiQuestRequirementSmokeCheck()
    {
    }

    public static void main(String[] args) throws Exception
    {
        OkHttpClient httpClient = new OkHttpClient();
        try
        {
            run(httpClient);
        }
        finally
        {
            LiveWikiCheckSupport.close(httpClient);
        }
    }

    private static void run(OkHttpClient httpClient) throws Exception
    {
        WikiClient client = new WikiClient(httpClient, new Gson());
        Map<String, String> excerpts = fetch(client, "At First Light");
        requireContains(excerpts, "At First Light - Requirements", "46 Hunter");
        requireContains(excerpts, "At First Light - Requirements", "30 Herblore");
        requireContains(excerpts, "At First Light - Requirements", "27 Construction");
        requireContains(excerpts, "At First Light - Requirements", "Children of the Sun");
        requireContains(excerpts, "At First Light - Requirements", "Eagles' Peak");
        requireContains(excerpts, "At First Light - Requirements", "Needle");

        excerpts = fetch(client, "Monkey Madness II");
        requireContains(excerpts, "Monkey Madness II - Requirements", "69 Slayer");
        requireContains(excerpts, "Monkey Madness II - Requirements", "60 Firemaking");
        requireContains(excerpts, "Monkey Madness II - Requirements", "Enlightened Journey");
        requireContains(excerpts, "Monkey Madness II - Requirements", "Watchtower");
        System.out.println("Verified quest requirements and items without using OpenAI.");
    }

    private static Map<String, String> fetch(WikiClient client, String title)
        throws Exception
    {
        CountDownLatch done = new CountDownLatch(1);
        AtomicReference<WikiResult> resultRef = new AtomicReference<>();
        client.search(title, false, false, false, true, result ->
        {
            resultRef.set(result);
            done.countDown();
        });
        if (!done.await(60, TimeUnit.SECONDS))
        {
            client.cancel();
            throw new IllegalStateException(
                "Timed out while checking quest requirements for " + title);
        }
        WikiResult result = resultRef.get();
        if (result == null || !result.isAvailable())
        {
            throw new IllegalStateException(
                "Quest requirement grounding was unavailable for " + title);
        }
        Map<String, String> excerpts = new HashMap<>();
        for (WikiSource source : result.getSources())
        {
            excerpts.put(source.getTitle(), source.getExcerpt());
        }
        return excerpts;
    }

    private static void requireContains(Map<String, String> excerpts, String title, String text)
    {
        String excerpt = excerpts.get(title);
        if (excerpt == null || !excerpt.contains(text))
        {
            throw new IllegalStateException("Missing expected quest grounding: " +
                title + " -> " + text);
        }
    }
}

package com.gielinorguide;

import com.google.gson.Gson;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.OkHttpClient;

/** Live, opt-in Slayer guide check. It never calls OpenAI. */
public final class WikiSlayerSmokeCheck
{
    private WikiSlayerSmokeCheck()
    {
    }

    public static void main(String[] args) throws Exception
    {
        OkHttpClient httpClient = new OkHttpClient();
        try
        {
            run(httpClient);
        }
        finally
        {
            LiveWikiCheckSupport.close(httpClient);
        }
    }

    private static void run(OkHttpClient httpClient) throws Exception
    {
        WikiClient client = new WikiClient(httpClient, new Gson());
        WikiResult result = fetch(client, "Slayer task/Aberrant spectres");
        if (result == null || !result.isAvailable() || result.getSources().isEmpty())
        {
            throw new IllegalStateException("Slayer task grounding was unavailable");
        }
        StringBuilder grounding = new StringBuilder();
        for (WikiSource source : result.getSources())
        {
            grounding.append(source.getExcerpt()).append('\n');
        }
        String excerpt = grounding.toString();
        require(excerpt, "nose peg");
        require(excerpt, "Protect from Magic");
        require(excerpt, "Stronghold Slayer Cave");
        require(excerpt, "Location Comparison");
        require(excerpt, "Safespottable");
        require(excerpt, "elemental weakness");
        require(excerpt, "Air");
        require(excerpt, "Slayer ring");
        require(excerpt, "transportation");
        LocationResolver locationResolver = new LocationResolver();
        List<VerifiedLocation> destinations =
            locationResolver.resolveMentions(result.asGroundingText());
        SlayerAnswerGuard.Result guarded = new SlayerAnswerGuard(
            locationResolver).enforce(
            "I couldn't verify their location, weaknesses, or route, so I won't guess.",
            "- Equipment: Nose peg, Trident of the swamp\n" +
                "- Task: Aberrant Spectres\n- Remaining: 10\n" +
                "- Assigned area: none specified by RuneLite",
            result, destinations);
        require(guarded.getAnswer(), "Slayer Tower");
        require(guarded.getAnswer(), "From Canifis");
        require(guarded.getAnswer(), "61 Agility spiked chain");
        require(guarded.getAnswer(), "Air (50%)");
        require(guarded.getAnswer(), "Protect from Magic");
        if (guarded.getDestinations().isEmpty())
        {
            throw new IllegalStateException("Slayer fallback did not provide a route target");
        }

        WikiResult metal = fetch(client, "Slayer task/Metal Dragons");
        require(metal.asGroundingText(), "recommended to kill bronze dragons");
        require(metal.asGroundingText(), "Verified monster variants");
        require(metal.asGroundingText(), "Slayer XP");
        require(metal.asGroundingText(), "Fairy ring code");
        SlayerAnswerGuard.Result metalGuarded = new SlayerAnswerGuard(
            locationResolver).enforce(
            "You have 39 Metal Dragons remaining.",
            "- Task: Metal Dragons\n- Remaining: 39\n" +
                "- Assigned area: Brimhaven Dungeon",
            metal, metal.getDestinations());
        require(metalGuarded.getAnswer(), "bronze dragons");
        require(metalGuarded.getAnswer(), "Brimhaven Dungeon (task only area)");
        require(metalGuarded.getAnswer(), "Fast task / points");
        require(metalGuarded.getAnswer(), "stab");
        require(metalGuarded.getAnswer(), "Earth (50%)");
        require(metalGuarded.getAnswer(), "dragon hunter");
        require(metalGuarded.getAnswer(), "verified entrance first");
        require(metalGuarded.getAnswer(), "anti-dragon shield");
        require(metalGuarded.getAnswer(), "super antifire potion by itself");
        require(metalGuarded.getAnswer(), "regular antifire potion");
        require(metalGuarded.getAnswer(), "Protect from Melee");
        require(metalGuarded.getAnswer(), "outside melee range");
        require(metalGuarded.getAnswer(), "875");
        if (metalGuarded.getAnswer().contains("Grand Exchange") ||
            metalGuarded.getAnswer().contains("Getting there: ") ||
            metalGuarded.getAnswer().contains("XP/hour"))
        {
            throw new IllegalStateException("Metal dragon fallback included unrelated travel");
        }
        if (metalGuarded.getDestinations().isEmpty() ||
            !"brimhaven-dungeon-task-only-area".equals(
                metalGuarded.getDestinations().get(0).getId()))
        {
            throw new IllegalStateException(
                "Metal dragon fallback did not choose the task-only Brimhaven target");
        }
        if (!new net.runelite.api.coords.WorldPoint(2744, 3155, 0).equals(
            metalGuarded.getDestinations().get(0).getRouteWorldPoint()))
        {
            throw new IllegalStateException(
                "Metal dragon fallback did not route to the Brimhaven entrance first");
        }

        WikiResult fireGiants = fetch(client, "Slayer task/Fire giants");
        SlayerAnswerGuard.Result fireGuarded = new SlayerAnswerGuard(
            locationResolver).enforce(
            "Attack the level 109 fire giants for better XP and use your cannon.",
            "- Task: Fire Giants\n- Remaining: 50\n" +
                "- Assigned area: Giants' Den\n" +
                "- Bank snapshot: Dwarf multicannon, Steel cannonball x1,789",
            fireGiants, fireGiants.getDestinations());
        require(fireGuarded.getAnswer(), "Giants' Den allows a dwarf multicannon");
        require(fireGuarded.getAnswer(), "1,789 steel cannonballs");
        require(fireGuarded.getAnswer(), "Water (100%)");
        require(fireGuarded.getAnswer(), "Protect from Melee only if fighting next to them");
        if (fireGuarded.getAnswer().contains("level 109") ||
            fireGuarded.getAnswer().contains("better XP"))
        {
            throw new IllegalStateException(
                "Fire giant fallback preferred XP per kill over fast completion");
        }
        if (fireGuarded.getDestinations().isEmpty() ||
            !"giants-den".equals(fireGuarded.getDestinations().get(0).getId()))
        {
            throw new IllegalStateException(
                "Fire giant fallback did not resolve the assigned Giants' Den");
        }
        if (fireGuarded.getDestinations().get(0).getRouteWorldPoint().equals(
            fireGuarded.getDestinations().get(0).getWorldPoint()))
        {
            throw new IllegalStateException(
                "Fire giant fallback did not separate the Giants' Den entrance route");
        }
        System.out.println("Verified Slayer title recovery, target selection, offense, " +
            "protection, Fire giant task criteria, and concise routing without using OpenAI.");
    }

    private static WikiResult fetch(WikiClient client, String query) throws Exception
    {
        CountDownLatch done = new CountDownLatch(1);
        AtomicReference<WikiResult> resultRef = new AtomicReference<>();
        client.search(query, result ->
        {
            resultRef.set(result);
            done.countDown();
        });
        if (!done.await(60, TimeUnit.SECONDS))
        {
            client.cancel();
            throw new IllegalStateException("Timed out while checking " + query);
        }
        WikiResult result = resultRef.get();
        if (result == null || !result.isAvailable() || result.getSources().isEmpty())
        {
            throw new IllegalStateException("Slayer task grounding was unavailable for " + query);
        }
        return result;
    }

    private static void require(String excerpt, String expected)
    {
        if (!excerpt.contains(expected))
        {
            throw new IllegalStateException("Missing expected Slayer grounding: " + expected);
        }
    }
}

