    @Test
    public void usesLinkedLocationEntranceBeforeInteriorSlayerObjective()
    {
        VerifiedLocation interior = new VerifiedLocation(
            "brimhaven-dungeon-task-only-area",
            "Brimhaven Dungeon (task only area)",
            Collections.singletonList("Brimhaven Dungeon"),
            new WorldPoint(2661, 9453, 0),
            "Use this as the final objective; the entrance is only an access step.",
            "https://oldschool.runescape.wiki/w/Slayer_task/Metal_dragons");
        WikiResult base = new WikiResult(Collections.emptyList(), true,
            Collections.singletonList(interior));
        String json = "{\"query\":{\"pages\":[" +
            revisionPage("Brimhaven Dungeon",
                "{{Infobox Location|name=Brimhaven Dungeon}}\\n" +
                    "{{Map|2744,3155|2760,3063|caption=Entrances}}") + "]}}";
        WikiSlayerTaskExpander expander = new WikiSlayerTaskExpander(
            new OkHttpClient(), new Gson());

        WikiResult routed = expander.applyRouteTargets(base, json);

        assertEquals(new WorldPoint(2661, 9453, 0),
            routed.getDestinations().get(0).getWorldPoint());
        assertEquals(new WorldPoint(2744, 3155, 0),
            routed.getDestinations().get(0).getRouteWorldPoint());
    }

    @Test
    public void treatsRedirectedMonsterPageAsTaskEvidence()
    {
        String wikiText = "{{Infobox Monster\n|attack style = [[Melee]]\n}}\n" +
            "Earth warriors are found in the [[Edgeville Dungeon]].\n" +
            "==Locations==\n{| class=\"wikitable\"\n|[[Edgeville Dungeon]]\n|}\n";
        WikiSlayerTaskExpander expander = new WikiSlayerTaskExpander(
            new OkHttpClient(), new Gson());

        WikiSource source = expander.parse("Earth warrior",
            "https://oldschool.runescape.wiki/w/Earth_warrior", wikiText);

        assertTrue(source.getExcerpt().contains("attack style: Melee"));
        assertTrue(source.getExcerpt().contains("found in the Edgeville Dungeon"));
        assertTrue(source.getExcerpt().contains("Verified Locations"));
        assertTrue(expander.relatedPages(wikiText).contains("Edgeville Dungeon"));
    }

    @Test
    public void classifiesRedirectedRelatedPagesByContentInsteadOfRequestedTitle()
    {
        String json = "{\"query\":{\"pages\":[" +
            revisionPage("Earth warrior", "{{Infobox Monster\\n|attack style = [[Melee]]\\n}}") + "," +
            revisionPage("Edgeville Dungeon", "{{Infobox Location}}\\nA dungeon location.") + "]}}";
        WikiSlayerTaskExpander expander = new WikiSlayerTaskExpander(
            new OkHttpClient(), new Gson());

        java.util.List<WikiSource> sources = expander.relatedSources(json);

        assertTrue(sources.get(0).getExcerpt().contains("attack style: Melee"));
        assertTrue(sources.get(1).getExcerpt().contains("Verified location and route guidance"));
    }

    private static String revisionPage(String title, String content)
    {
        return "{\"title\":\"" + title + "\",\"fullurl\":\"https://oldschool.runescape.wiki/w/" +
            title.replace(" ", "_") + "\",\"revisions\":[{\"slots\":{\"main\":{\"content\":\"" +
            content + "\"}}}]}";
    }
